test "win32: goto_window waits for run and goes round the windows" {
    // Activating a window moves the focus, which would reach the asking
    // terminal's core inside its key callback, so the move is recorded and
    // made by createRequested; with one window the key reaches the
    // terminal. Activation needs the foreground, which a test process does
    // not hold, but `Window.present` restores a minimized window first, so
    // the window gone to is the one no longer minimized.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    var windows: [3]*Window = undefined;
    var panes: [3]*Surface = undefined;
    for (&windows, &panes, 0..) |*w, *p, i| {
        w.* = try testFrame(&app);
        p.* = try testPane(&app, w.*);
        w.*.tab().tree = try .init(alloc, p.*);
        if (i == 0) {
            // Alone, there is nowhere to go.
            try std.testing.expect(!try app.performAction(.{ .surface = &p.*.core_surface }, .goto_window, .next));
            try std.testing.expectEqual(0, app.requests.items.len);
        }
    }

    // In GTK's order, newest first: next is the window opened before,
    // previous the one opened after, round the ends.
    try std.testing.expectEqual(windows[2], app.windowBeside(windows[0], .next).?);
    try std.testing.expectEqual(windows[1], app.windowBeside(windows[0], .previous).?);
    try std.testing.expectEqual(windows[1], app.windowBeside(windows[2], .next).?);
    try std.testing.expectEqual(windows[0], app.windowBeside(windows[2], .previous).?);

    const Case = struct { to: apprt.action.GotoWindow, want: usize, other: usize };
    for ([_]Case{
        .{ .to = .next, .want = 2, .other = 1 },
        .{ .to = .previous, .want = 1, .other = 2 },
    }) |c| {
        for (windows[1..]) |w| _ = win32.ShowWindow(w.hwnd, win32.SW_SHOWMINNOACTIVE);
        try std.testing.expect(try app.performAction(.{ .surface = &panes[0].core_surface }, .goto_window, c.to));
        try std.testing.expectEqual(1, app.requests.items.len);
        try std.testing.expect(win32.IsIconic(windows[c.want].hwnd).toBool());
        app.createRequested();
        try std.testing.expectEqual(0, app.requests.items.len);
        try std.testing.expect(!win32.IsIconic(windows[c.want].hwnd).toBool());
        try std.testing.expect(win32.IsIconic(windows[c.other].hwnd).toBool());
    }

    // A closing terminal drops its own.
    try std.testing.expect(try app.performAction(.{ .surface = &panes[0].core_surface }, .goto_window, .next));
    app.forgetClosing(&panes[0].core_surface);
    try std.testing.expect(app.requests.items[0] == .dropped);
    app.requests.clearRetainingCapacity();

    // A window closing between others leaves the rest in opening order.
    const last = try testFrame(&app);
    try std.testing.expect(win32.DestroyWindow(windows[1].hwnd).toBool());
    try std.testing.expectEqual(last, app.windowBeside(windows[0], .next).?);
    try std.testing.expectEqual(windows[2], app.windowBeside(windows[0], .previous).?);
}

test "win32: resize_window waits for run and resizes the window of a lone terminal" {
    // A program asks for it (CSI 8 t), and the core asks from inside a
    // tick; the terminals are laid out again, so it is recorded and made
    // by createRequested. As on GTK and macOS only the one terminal of a
    // window at a size of its own is resized, and a zero dimension is
    // kept.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    const target: apprt.Target = .{ .surface = &pane.core_surface };
    const scale = try pane.getContentScale();

    // Recorded, not made; then the width, and the height kept.
    const before = try clientRect(window.hwnd);
    try std.testing.expect(try app.performAction(target, .resize_window, .{ .width = 300, .height = 0 }));
    try std.testing.expectEqual(1, app.requests.items.len);
    try std.testing.expectEqual(before, try clientRect(window.hwnd));
    app.createRequested();
    // The terminal's grid, beside which its scroll bar goes.
    const wide = try clientRect(window.hwnd);
    const bar = ScrollBar.width(pane);
    try std.testing.expect(bar > 0);
    try std.testing.expectEqual(Window.scaledSize(300, scale.x), (try clientRect(pane.hwnd)).right);
    try std.testing.expectEqual(Window.scaledSize(300, scale.x) + bar, wide.right);
    try std.testing.expectEqual(before.bottom, wide.bottom);
    try std.testing.expectEqual(wide, try paneRect(window, pane));

    // The height, and the width kept.
    try std.testing.expect(try app.performAction(target, .resize_window, .{ .width = 0, .height = 200 }));
    app.createRequested();
    const tall = try clientRect(window.hwnd);
    try std.testing.expectEqual(wide.right, tall.right);
    try std.testing.expectEqual(Window.scaledSize(200, scale.y), tall.bottom);

    // Not for a maximized window, nor one covering its monitor.
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWMAXIMIZED);
    try std.testing.expect(!try app.performAction(target, .resize_window, .{ .width = 300, .height = 200 }));
    _ = win32.ShowWindow(window.hwnd, win32.SW_RESTORE);
    window.toggleFullscreen();
    try std.testing.expect(!try app.performAction(target, .resize_window, .{ .width = 300, .height = 200 }));
    window.toggleFullscreen();
    try std.testing.expectEqual(0, app.requests.items.len);

    // Nor for a snapped one, which Windows tells apart from Windows 10
    // 1903 (IsWindowArranged); one that is not is resized.
    const arranged = struct {
        fn yes(_: win32.HWND) callconv(.winapi) win32.BOOL {
            return .TRUE;
        }
        fn no(_: win32.HWND) callconv(.winapi) win32.BOOL {
            return .FALSE;
        }
    };
    app.is_window_arranged = arranged.yes;
    try std.testing.expect(!try app.performAction(target, .resize_window, .{ .width = 300, .height = 200 }));
    try std.testing.expectEqual(0, app.requests.items.len);
    app.is_window_arranged = arranged.no;
    try std.testing.expect(try app.performAction(target, .resize_window, .{ .width = 300, .height = 200 }));
    app.requests.clearRetainingCapacity();
    app.is_window_arranged = null;

    // A closing terminal drops its own, and a window that is no longer
    // at a size of its own when run comes is left as it is.
    try std.testing.expect(try app.performAction(target, .resize_window, .{ .width = 400, .height = 0 }));
    app.forgetClosing(&pane.core_surface);
    try std.testing.expect(app.requests.items[0] == .dropped);
    app.requests.clearRetainingCapacity();
    try std.testing.expect(try app.performAction(target, .resize_window, .{ .width = 400, .height = 0 }));
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWMAXIMIZED);
    const maximized = try windowRect(window.hwnd);
    app.createRequested();
    try std.testing.expectEqual(maximized, try windowRect(window.hwnd));
    _ = win32.ShowWindow(window.hwnd, win32.SW_RESTORE);

    // Not in a split.
    const other = try testPane(&app, window);
    window.tab().tree.deinit();
    window.tab().tree = try testRow(alloc, &.{ pane, other });
    try std.testing.expect(!try app.performAction(target, .resize_window, .{ .width = 300, .height = 200 }));
}

test "win32: reset_window_size waits for run and gives the window a new one's size" {
    // As on macOS: maximized with `maximize`, or else the size
    // `window-width` and `window-height` ask for; nothing with neither, or
    // for a window covering its monitor. The terminals are laid out again,
    // so it is recorded and made by createRequested.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    const target: apprt.Target = .{ .surface = &pane.core_surface };
    const scale = try pane.getContentScale();

    // No size to go back to.
    try std.testing.expect(!try app.performAction(target, .reset_window_size, {}));

    // The size `window-width` and `window-height` ask for: recorded, not
    // made; then the client area takes it.
    pane.initial_size = .{ .width = 320, .height = 180 };
    const before = try clientRect(window.hwnd);
    try std.testing.expect(try app.performAction(target, .reset_window_size, {}));
    try std.testing.expectEqual(before, try clientRect(window.hwnd));
    app.createRequested();
    // The terminal's grid, beside which its scroll bar goes.
    const sized = try clientRect(window.hwnd);
    try std.testing.expect(ScrollBar.width(pane) > 0);
    try std.testing.expectEqual(Window.scaledSize(320, scale.x), (try clientRect(pane.hwnd)).right);
    try std.testing.expectEqual(Window.scaledSize(320, scale.x) + ScrollBar.width(pane), sized.right);
    try std.testing.expectEqual(Window.scaledSize(180, scale.x), sized.bottom);

    // A maximized window is restored and given it, though it was
    // resized after, which is what it would be restored to.
    const resized = win32.SWP_NOMOVE | win32.SWP_NOZORDER | win32.SWP_NOACTIVATE;
    _ = win32.SetWindowPos(window.hwnd, null, 0, 0, 500, 400, resized);
    try std.testing.expect(!std.meta.eql(sized, try clientRect(window.hwnd)));
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWMAXIMIZED);
    try std.testing.expect(try app.performAction(target, .reset_window_size, {}));
    app.createRequested();
    try std.testing.expect(!win32.IsZoomed(window.hwnd).toBool());
    try std.testing.expectEqual(sized, try clientRect(window.hwnd));

    // And so is a snapped one (IsWindowArranged).
    _ = win32.SetWindowPos(window.hwnd, null, 0, 0, 500, 400, resized);
    app.is_window_arranged = struct {
        fn f(_: win32.HWND) callconv(.winapi) win32.BOOL {
            return .TRUE;
        }
    }.f;
    try std.testing.expect(try app.performAction(target, .reset_window_size, {}));
    app.createRequested();
    try std.testing.expectEqual(sized, try clientRect(window.hwnd));
    app.is_window_arranged = null;

    // Not for a window covering its monitor.
    window.toggleFullscreen();
    try std.testing.expect(!try app.performAction(target, .reset_window_size, {}));
    window.toggleFullscreen();

    // With `maximize`, maximized.
    app.config.maximize = true;
    try std.testing.expect(try app.performAction(target, .reset_window_size, {}));
    app.createRequested();
    try std.testing.expect(win32.IsZoomed(window.hwnd).toBool());

    // A closing terminal drops its own.
    try std.testing.expect(try app.performAction(target, .reset_window_size, {}));
    app.forgetClosing(&pane.core_surface);
    try std.testing.expect(app.requests.items[0] == .dropped);
}

test "win32: a terminal's copy writes its HTML and its text, the HTML alone, the text alone after a prompt, and fails for what it cannot hold" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);

    const clipboard = @import("clipboard.zig");
    const saved = try clipboard.readClipboardText(alloc, pane.hwnd);
    defer if (saved) |text| {
        writeClipboard(alloc, pane.hwnd, .text(text)) catch {};
        alloc.free(text);
    };

    // `copy_to_clipboard:mixed`, the default: the core's text, then its
    // HTML (Surface.zig `copySelectionToClipboards`).
    try pane.setClipboard(.standard, &.{
        .{ .mime = "text/plain", .data = "red" },
        .{ .mime = "text/html", .data = "<div style=\"color: red;\">red</div>" },
    }, false);
    try clipboard.expectClipboard(pane.hwnd, "red", "<div style=\"color: red;\">red</div>");

    // Of two of a kind, the first.
    try pane.setClipboard(.standard, &.{
        .{ .mime = "text/html", .data = "<div>first</div>" },
        .{ .mime = "text/plain", .data = "first" },
        .{ .mime = "text/html", .data = "<div>second</div>" },
        .{ .mime = "text/plain", .data = "second" },
    }, false);
    try clipboard.expectClipboard(pane.hwnd, "first", "<div>first</div>");

    // `copy_to_clipboard:html`: the HTML alone.
    try pane.setClipboard(.standard, &.{
        .{ .mime = "text/html", .data = "<div>html</div>" },
    }, false);
    try clipboard.expectClipboard(pane.hwnd, null, "<div>html</div>");

    // Text in this runtime's own spelling of its type, which `isTextMime`
    // takes too. (`:plain` and an OSC 52 write give "text/plain", as the
    // first write here does.)
    try pane.setClipboard(.standard, &.{.{ .mime = clipboard.text_mime, .data = "plain" }}, false);
    try clipboard.expectClipboard(pane.hwnd, "plain", null);

    // A write that asks first writes the text alone, and with no text,
    // fails without asking.
    const Prompt = struct {
        var boxes: usize = 0;
        fn box(_: ?win32.HWND, _: win32.LPCWSTR, _: win32.UINT) c_int {
            boxes += 1;
            return win32.IDOK;
        }
    };
    const message_box = &@import("dialog.zig").test_message_box;
    message_box.* = &Prompt.box;
    defer message_box.* = null;
    try pane.setClipboard(.standard, &.{
        .{ .mime = "text/plain", .data = "asked" },
        .{ .mime = "text/html", .data = "<div>asked</div>" },
    }, true);
    try std.testing.expectEqual(1, Prompt.boxes);
    try clipboard.expectClipboard(pane.hwnd, "asked", null);
    try std.testing.expectError(
        error.NothingWritable,
        pane.setClipboard(.standard, &.{.{ .mime = "text/html", .data = "<div>asked</div>" }}, true),
    );
    try std.testing.expectEqual(1, Prompt.boxes);
    try clipboard.expectClipboard(pane.hwnd, "asked", null);
    try pane.setClipboard(.standard, &.{.{ .mime = clipboard.text_mime, .data = "plain" }}, false);

    // Nothing this runtime can hold fails the write and leaves the
    // clipboard as it was: a type with no format, and data that is not what
    // its type says. A write to the selection clipboard, which Windows has
    // not, leaves it too.
    try std.testing.expectError(
        error.NothingWritable,
        pane.setClipboard(.standard, &.{.{ .mime = "application/x-unknown", .data = "x" }}, false),
    );
    try std.testing.expectError(
        error.NothingWritable,
        pane.setClipboard(.standard, &.{.{ .mime = "image/png", .data = "png" }}, false),
    );
    try pane.setClipboard(.selection, &.{.{ .mime = "text/html", .data = "<div>x</div>" }}, false);
    try clipboard.expectClipboard(pane.hwnd, "plain", null);
}

test "win32: copy_title_to_clipboard copies the terminal's title, if it has one" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    const target: apprt.Target = .{ .surface = &pane.core_surface };

    // Put back whatever text the clipboard held, as the clipboard's own
    // test does.
    const readClipboardText = @import("clipboard.zig").readClipboardText;
    const saved = try readClipboardText(alloc, pane.hwnd);
    defer if (saved) |text| {
        writeClipboard(alloc, pane.hwnd, .text(text)) catch {};
        alloc.free(text);
    };
    try writeClipboard(alloc, pane.hwnd, .text("before"));

    // None yet, then an empty one: no effect.
    try std.testing.expect(!try app.performAction(target, .copy_title_to_clipboard, {}));
    _ = pane.setTitle("");
    try std.testing.expect(!try app.performAction(target, .copy_title_to_clipboard, {}));
    {
        const text = (try readClipboardText(alloc, pane.hwnd)) orelse return error.TestUnexpectedResult;
        defer alloc.free(text);
        try std.testing.expectEqualStrings("before", text);
    }

    _ = pane.setTitle("vim café");
    try std.testing.expect(try app.performAction(target, .copy_title_to_clipboard, {}));
    {
        const text = (try readClipboardText(alloc, pane.hwnd)) orelse return error.TestUnexpectedResult;
        defer alloc.free(text);
        try std.testing.expectEqualStrings("vim café", text);
    }

    // The title shown, as GTK copies its effective title: the one the user
    // gave the terminal in its title prompt.
    try testAnswer(try testPrompt(&app, pane, .surface), "mine", win32.IDOK);
    try std.testing.expect(try app.performAction(target, .copy_title_to_clipboard, {}));
    const text = (try readClipboardText(alloc, pane.hwnd)) orelse return error.TestUnexpectedResult;
    defer alloc.free(text);
    try std.testing.expectEqualStrings("mine", text);
}

test "win32: files dropped on a terminal paste their paths, quoted for its shell, freed always, unless a prompt is open" {
    const alloc = std.testing.allocator;
    const drop = @import("drop.zig");
    const u = std.unicode.utf8ToUtf16LeStringLiteral;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    const b = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ a, b });
    window.tab().focused = a;

    // What each drop would paste, on which terminal, and whether it asks.
    const Dropped = struct {
        var on: ?*Surface = null;
        var buf: [128]u8 = undefined;
        var len: usize = 0;
        var asked = false;
        var count: usize = 0;
        fn seen(surface: *Surface, pasted: []const u8, ask: bool) void {
            on = surface;
            len = @min(pasted.len, buf.len);
            @memcpy(buf[0..len], pasted[0..len]);
            asked = ask;
            count += 1;
        }
        fn text() []const u8 {
            return buf[0..len];
        }
    };
    Surface.test_dropped = &Dropped.seen;
    defer Surface.test_dropped = null;
    const freed = Surface.test_drops_freed;
    const names: []const []const u16 = &.{ u("C:\\a $b"), u("C:\\c") };

    // To the terminal the files are dropped on, for its own shell, without
    // asking for a shell Ghostty knows.
    a.shell = .powershell;
    b.shell = .bash;
    _ = win32.SendMessageW(a.hwnd, win32.WM_DROPFILES, @intFromPtr(try drop.testDrop(names)), 0);
    try std.testing.expectEqual(1, Dropped.count);
    try std.testing.expect(Dropped.on == a);
    try std.testing.expectEqualStrings("'C:\\a $b' C:\\c", Dropped.text());
    try std.testing.expect(!Dropped.asked);
    _ = win32.SendMessageW(b.hwnd, win32.WM_DROPFILES, @intFromPtr(try drop.testDrop(names)), 0);
    try std.testing.expectEqual(2, Dropped.count);
    try std.testing.expect(Dropped.on == b);
    try std.testing.expectEqualStrings("C:\\\\a\\ \\$b C:\\\\c", Dropped.text());
    try std.testing.expect(!Dropped.asked);

    // For one it does not know, the `$` its double quotes leave a POSIX
    // shell to expand asks first.
    b.shell = null;
    _ = win32.SendMessageW(b.hwnd, win32.WM_DROPFILES, @intFromPtr(try drop.testDrop(names)), 0);
    try std.testing.expectEqual(3, Dropped.count);
    try std.testing.expectEqualStrings("\"C:\\a $b\" \"C:\\c\"", Dropped.text());
    try std.testing.expect(Dropped.asked);
    try std.testing.expectEqual(freed + 3, Surface.test_drops_freed);

    // Not while a prompt is open, nor with no name to paste, nor with no
    // drop; each drop freed even so.
    app.prompt_depth = 1;
    _ = win32.SendMessageW(a.hwnd, win32.WM_DROPFILES, @intFromPtr(try drop.testDrop(names)), 0);
    app.prompt_depth = 0;
    try std.testing.expectEqual(freed + 4, Surface.test_drops_freed);
    const bad = [_]u16{ 'C', ':', '\\', 0xD800 };
    _ = win32.SendMessageW(a.hwnd, win32.WM_DROPFILES, @intFromPtr(try drop.testDrop(&.{&bad})), 0);
    try std.testing.expectEqual(freed + 5, Surface.test_drops_freed);
    try std.testing.expectEqual(0, win32.SendMessageW(a.hwnd, win32.WM_DROPFILES, 0, 0));
    try std.testing.expectEqual(freed + 5, Surface.test_drops_freed);
    try std.testing.expectEqual(3, Dropped.count);
}

test "win32: a paste event lists the types the clipboard holds, and an empty or held clipboard is none" {
    const alloc = std.testing.allocator;
    const clipboard = @import("clipboard.zig");
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{pane});
    window.tab().focused = pane;
    const saved = try clipboard.TestSaved.save(pane.hwnd);
    defer saved.restore(pane.hwnd);

    // What each request completes with, where a test's terminal has no
    // core to complete it.
    const Listed = struct {
        var buf: [256]u8 = undefined;
        var len: usize = 0;
        var count: usize = 0;
        var listing = false;
        fn complete(_: *Surface, state: apprt.ClipboardRequest, done: CoreSurface.CompleteClipboard) Surface.TestClipboardError!void {
            count += 1;
            listing = state == .list and done.contents.len == 0;
            len = 0;
            for (done.available) |mime| {
                if (len + mime.len + 1 > buf.len) break;
                @memcpy(buf[len..][0..mime.len], mime);
                buf[len + mime.len] = ' ';
                len += mime.len + 1;
            }
        }
        fn text() []const u8 {
            return buf[0..len];
        }
    };
    Surface.test_clipboard_core = &Listed.complete;
    defer Surface.test_clipboard_core = null;

    // Each type a program could read, the text first, as GTK and macOS
    // list theirs; and a file list, which has no text.
    try clipboard.writeClipboard(alloc, pane.hwnd, .of(&.{
        .{ .mime = "text/html", .data = "<b>h</b>" },
        .{ .mime = "text/plain", .data = "t" },
    }, false));
    try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .list = .standard }));
    try std.testing.expectEqual(1, Listed.count);
    try std.testing.expect(Listed.listing);
    try std.testing.expectEqualStrings("text/plain text/html ", Listed.text());
    try clipboard.testPut(pane.hwnd, &.{}, &.{std.unicode.utf8ToUtf16LeStringLiteral("C:\\a")});
    try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .list = .standard }));
    try std.testing.expectEqual(2, Listed.count);
    try std.testing.expectEqualStrings("text/uri-list ", Listed.text());

    // An empty clipboard, and one another program holds open, are no paste
    // event, so a performable paste binding passes its key on.
    try clipboard.testPut(pane.hwnd, &.{}, &.{});
    try std.testing.expectEqual(.unavailable, try pane.clipboardRequest(.standard, .{ .list = .standard }));
    try clipboard.writeClipboard(alloc, pane.hwnd, .text("t"));
    {
        const holder = try clipboard.TestHolder.start();
        defer holder.release();
        try std.testing.expectEqual(.unavailable, try pane.clipboardRequest(.standard, .{ .list = .standard }));
    }
    try std.testing.expectEqual(2, Listed.count);
}

/// For tests: a Kitty clipboard read as the stream handler makes one
/// (`StreamHandler.kittyClipboardRead`), the request and all it names in
/// one arena, which whoever consumes it frees (`KittyRead.destroy`).
fn testKittyRead(
    alloc: Allocator,
    location: apprt.Clipboard,
    mimes: []const []const u8,
    list: bool,
) !*apprt.ClipboardRequest.KittyRead {
    var arena: std.heap.ArenaAllocator = .init(alloc);
    errdefer arena.deinit();
    const a = arena.allocator();
    const req = try a.create(apprt.ClipboardRequest.KittyRead);
    const owned = try a.alloc([:0]const u8, mimes.len);
    for (mimes, owned) |mime, *m| m.* = try a.dupeSentinel(u8, mime, 0);
    const id = try a.dupe(u8, "kc");
    // The arena goes in last, so that it holds every allocation above.
    req.* = .{
        .arena = arena,
        .location = location,
        .mimes = owned,
        .list = list,
        .id = id,
        .pw = "",
        .name = "",
        .granted = false,
        .terminator = .st,
    };
    return req;
}

/// For tests: a Kitty clipboard write of `text`, as `testKittyRead` makes
/// a read (`StreamHandler.kittyClipboardWrite`).
fn testKittyWrite(alloc: Allocator, location: apprt.Clipboard, text: []const u8) !*apprt.ClipboardRequest.KittyWrite {
    return testKittyWriteOf(alloc, location, &.{.{ .mime = "text/plain", .data = text }});
}

/// For tests: a part of a Kitty clipboard write (`testKittyWriteOf`).
const TestPart = struct { mime: []const u8, data: []const u8 };

/// For tests: a Kitty clipboard write of `parts`, each copied into its
/// arena.
fn testKittyWriteOf(
    alloc: Allocator,
    location: apprt.Clipboard,
    parts: []const TestPart,
) !*apprt.ClipboardRequest.KittyWrite {
    var arena: std.heap.ArenaAllocator = .init(alloc);
    errdefer arena.deinit();
    const a = arena.allocator();
    const req = try a.create(apprt.ClipboardRequest.KittyWrite);
    const contents = try a.alloc(apprt.ClipboardContent, parts.len);
    for (parts, contents) |part, *c| c.* = .{
        .mime = try a.dupeSentinel(u8, part.mime, 0),
        .data = try a.dupeSentinel(u8, part.data, 0),
    };
    const id = try a.dupe(u8, "kc");
    req.* = .{
        .arena = arena,
        .location = location,
        .contents = contents,
        .id = id,
        .pw = "",
        .name = "",
        .granted = false,
        .terminator = .st,
    };
    return req;
}

/// For tests: `pane`'s answer to the Kitty request `state`, freed here, as
/// the core frees it, unless the runtime took it (`.started`). A request
/// the runtime took when it should have left it is then a failed
/// expectation, not a second free that crashes the test.
fn testKittyLeft(pane: *Surface, location: apprt.Clipboard, state: apprt.ClipboardRequest) !apprt.ClipboardReadResult {
    const left = struct {
        fn free(s: apprt.ClipboardRequest) void {
            switch (s) {
                inline .kitty_read, .kitty_write => |req| req.destroy(),
                else => unreachable,
            }
        }
    }.free;
    const result = pane.clipboardRequest(location, state) catch |err| {
        left(state);
        return err;
    };
    if (result != .started) left(state);
    return result;
}

/// For tests: what stands in for the core in a Kitty clipboard request,
/// where a test's terminal has none (`Surface.test_clipboard_core`,
/// `Surface.test_clipboard_deny`). As the core does under an `ask` policy,
/// it answers `error.UnauthorizedPaste` to an unconfirmed request when
/// `ask`, leaving the request alive; every other completion, and every
/// denial, consumes the request, freeing it, then fails with `fail` if
/// set. A request consumed twice, or never, fails the test's allocator.
const TestKittyCore = struct {
    var ask = false;
    var fail: ?Surface.TestClipboardError = null;
    var asked: usize = 0;
    var completed: usize = 0;
    var denied: usize = 0;
    var confirmed = false;
    var remembered = false;
    var buf: [256]u8 = undefined;
    var len: usize = 0;

    fn reset() void {
        ask = false;
        fail = null;
        asked = 0;
        completed = 0;
        denied = 0;
        confirmed = false;
        remembered = false;
        len = 0;
    }

    fn complete(_: *Surface, state: apprt.ClipboardRequest, done: CoreSurface.CompleteClipboard) Surface.TestClipboardError!void {
        if (ask and !done.confirmed) {
            asked += 1;
            return error.UnauthorizedPaste;
        }
        completed += 1;
        confirmed = done.confirmed;
        remembered = done.remember;
        len = 0;
        for (done.contents) |c| {
            add(c.mime);
            add("=");
            add(c.data);
            add(" ");
        }
        for (done.available) |mime| {
            add(mime);
            add(" ");
        }
        consume(state);
        if (fail) |err| return err;
    }

    fn deny(_: *Surface, state: apprt.ClipboardRequest) void {
        denied += 1;
        consume(state);
    }

    fn consume(state: apprt.ClipboardRequest) void {
        switch (state) {
            .kitty_read => |kitty| kitty.destroy(),
            .kitty_write => |kitty| kitty.destroy(),
            else => unreachable,
        }
    }

    fn add(s: []const u8) void {
        const n = @min(s.len, buf.len - len);
        @memcpy(buf[len..][0..n], s[0..n]);
        len += n;
    }

    /// What the last completion served, "mime=data " for each type, then
    /// each type listed.
    fn served() []const u8 {
        return buf[0..len];
    }
};

/// For tests: the Kitty clipboard prompt (`ClipboardDialog.test_run`). It
/// records what the dialog shows (`first`), checks the box to remember if
/// `check` and the box is there, picks the part at `pick` if set, as the
/// list would, and records the dialog again (`picked`), then answers
/// `answer` as the button's click would, or leaves it unanswered when
/// null, as the close button would. While it is up it finds whether
/// another program could open the clipboard, then writes `changed` to it,
/// as a program could.
const TestKittyPrompt = struct {
    const ClipboardDialog = @import("ClipboardDialog.zig");

    var answer: ?c_int = win32.IDCANCEL;
    var check = false;
    var pick: ?usize = null;
    var boxes: usize = 0;
    var hwnd: ?win32.HWND = null;
    /// Run while the prompt is up, after any pick, before it is answered.
    var during: ?*const fn () void = null;
    var first: View = .{};
    var picked: View = .{};
    /// What it shows after `during` ran.
    var after: View = .{};
    var open = false;
    var changed = false;

    fn reset(owner: win32.HWND) void {
        answer = win32.IDCANCEL;
        check = false;
        pick = null;
        boxes = 0;
        hwnd = owner;
        during = null;
        forget();
    }

    fn forget() void {
        first = .{};
        picked = .{};
        after = .{};
        open = false;
        changed = false;
    }

    /// What the dialog shows: the heading, the part's name, or the one
    /// picked, how many the list holds, the one preview shown and its text,
    /// what a write leaves out, whether the box is offered, which button
    /// Enter presses, the title bar's mode, and an image's pixels where
    /// they are drawn.
    const View = struct {
        caption: Text = .{},
        allow: Text = .{},
        deny: Text = .{},
        heading: Text = .{},
        part: Text = .{},
        count: isize = 0,
        shown: ?c_int = null,
        /// How many previews are shown, which is always one.
        previews: usize = 0,
        preview: Text = .{},
        unwritten: ?Text = null,
        offered: bool = false,
        default: isize = 0,
        /// The title bar's mode, as DWM reads it back; null if it cannot.
        dark: ?bool = null,
        /// The image drawn: the pixel a quarter of the way into it, and
        /// one of the face around it.
        quarter: ?win32.COLORREF = null,
        face: ?win32.COLORREF = null,
        /// Whether drawing it left the DC's stretch mode and brush origin
        /// as they were.
        restored: ?bool = null,

        fn of(dialog: win32.HWND) View {
            const parts = win32.GetDlgItem(dialog, ClipboardDialog.id_parts);
            var v: View = .{
                .caption = .of(dialog),
                .allow = .of(win32.GetDlgItem(dialog, win32.IDOK)),
                .deny = .of(win32.GetDlgItem(dialog, win32.IDCANCEL)),
                .heading = .of(win32.GetDlgItem(dialog, ClipboardDialog.id_heading)),
                .part = .of(parts),
                .count = if (parts) |p| win32.SendMessageW(p, win32.CB_GETCOUNT, 0, 0) else 0,
                .offered = win32.GetDlgItem(dialog, ClipboardDialog.id_remember) != null,
                .default = win32.SendMessageW(dialog, win32.DM_GETDEFID, 0, 0),
            };
            var dark: win32.BOOL = .FALSE;
            if (win32.DwmGetWindowAttribute(dialog, win32.DWMWA_USE_IMMERSIVE_DARK_MODE, &dark, @sizeOf(win32.BOOL)) >= 0) {
                v.dark = dark.toBool();
            }
            for ([_]c_int{ ClipboardDialog.id_text, ClipboardDialog.id_image, ClipboardDialog.id_none }) |id| {
                const control = win32.GetDlgItem(dialog, id) orelse continue;
                if (!shown(control)) continue;
                v.previews += 1;
                v.shown = id;
                v.preview = .of(control);
            }
            if (win32.GetDlgItem(dialog, ClipboardDialog.id_unwritten)) |c| v.unwritten = .of(c);
            if (v.shown == ClipboardDialog.id_image) v.drawn(dialog);
            return v;
        }

        /// Draw the image into a bitmap as the dialog draws it into its
        /// control (WM_DRAWITEM), read two of its pixels, and see that the
        /// DC was given back as it came.
        fn drawn(self: *View, dialog: win32.HWND) void {
            const image = win32.GetDlgItem(dialog, ClipboardDialog.id_image) orelse return;
            var rect: win32.RECT = undefined;
            if (!win32.GetClientRect(image, &rect).toBool()) return;
            const screen = win32.GetDC(null) orelse return;
            defer _ = win32.ReleaseDC(null, screen);
            const dc = win32.CreateCompatibleDC(screen) orelse return;
            defer _ = win32.DeleteDC(dc);
            const bitmap = win32.CreateCompatibleBitmap(screen, rect.right, rect.bottom) orelse return;
            defer _ = win32.DeleteObject(bitmap);
            const old = win32.SelectObject(dc, bitmap);
            defer if (old) |o| {
                _ = win32.SelectObject(dc, o);
            };
            var item: win32.DRAWITEMSTRUCT = .{
                // ODT_STATIC, ODA_DRAWENTIRE.
                .CtlType = 5,
                .CtlID = ClipboardDialog.id_image,
                .itemID = 0,
                .itemAction = 1,
                .itemState = 0,
                .hwndItem = image,
                .hDC = dc,
                .rcItem = rect,
                .itemData = 0,
            };
            // An origin of its own, which drawing must not leave at 0,0.
            _ = win32.SetBrushOrgEx(dc, 3, 3, null);
            const mode = win32.GetStretchBltMode(dc);
            _ = win32.SendMessageW(dialog, win32.WM_DRAWITEM, ClipboardDialog.id_image, @bitCast(@intFromPtr(&item)));
            var origin: win32.POINT = undefined;
            self.restored = mode != 0 and win32.GetStretchBltMode(dc) == mode and
                win32.GetBrushOrgEx(dc, &origin).toBool() and origin.x == 3 and origin.y == 3;
            const at = ClipboardDialog.fit(rect, 2, 2);
            self.quarter = win32.GetPixel(dc, at.left + @divTrunc(at.right - at.left, 4), at.top + @divTrunc(at.bottom - at.top, 4));
            self.face = win32.GetPixel(dc, 0, 0);
        }
    };

    /// A control's text, its first `buf.len` units.
    const Text = struct {
        buf: [512]u16 = undefined,
        len: usize = 0,

        fn of(control: ?win32.HWND) Text {
            var t: Text = .{};
            const c = control orelse return t;
            t.len = @intCast(@max(0, win32.GetWindowTextW(c, &t.buf, t.buf.len)));
            return t;
        }

        fn expect(self: *const Text, want: []const u16) !void {
            try std.testing.expectEqualSlices(u16, want, self.buf[0..self.len]);
        }
    };

    fn run(dialog: win32.HWND) void {
        boxes += 1;
        first = .of(dialog);
        if (check) if (win32.GetDlgItem(dialog, ClipboardDialog.id_remember)) |box| {
            _ = win32.SendMessageW(box, win32.BM_SETCHECK, @intCast(win32.BST_CHECKED), 0);
        };
        if (pick) |i| if (win32.GetDlgItem(dialog, ClipboardDialog.id_parts)) |list| {
            // CB_SETCURSEL sends no CBN_SELCHANGE; a click on the list does.
            _ = win32.SendMessageW(list, win32.CB_SETCURSEL, i, 0);
            const notify: win32.WPARAM = @as(win32.WPARAM, win32.CBN_SELCHANGE) << 16 | ClipboardDialog.id_parts;
            _ = win32.SendMessageW(dialog, win32.WM_COMMAND, notify, @bitCast(@intFromPtr(list)));
            picked = .of(dialog);
        };
        if (during) |d| {
            d();
            after = .of(dialog);
        }
        const clipboard = @import("clipboard.zig");
        open = if (clipboard.TestHolder.start()) |holder| open: {
            holder.release();
            break :open true;
        } else |_| false;
        changed = if (writeClipboard(std.testing.allocator, hwnd.?, .text("changed"))) |_| true else |_| false;
        if (answer) |id| _ = win32.SendMessageW(dialog, win32.WM_COMMAND, @intCast(id), 0);
    }

    /// That the last prompt asked `want`, Deny the button Enter presses,
    /// with the clipboard free for other programs to open and change.
    fn expectAsked(want: win32.LPCWSTR) !void {
        defer forget();
        // GTK's heading and buttons, in the language in use.
        var words: Question = .{};
        try first.caption.expect(std.mem.span(words.one("Authorize Clipboard Access")));
        try first.allow.expect(std.mem.span(words.one("Allow")));
        try first.deny.expect(std.mem.span(words.one("Deny")));
        try first.heading.expect(std.mem.span(want));
        try std.testing.expectEqual(@as(isize, win32.DC_HASDEFID) << 16 | win32.IDCANCEL, first.default);
        try std.testing.expectEqual(1, first.previews);
        try std.testing.expect(open);
        try std.testing.expect(changed);
    }
};

test "win32: a Kitty clipboard read serves what was read, asking first, and answers once" {
    var question: Question = .{};
    const alloc = std.testing.allocator;
    const clipboard = @import("clipboard.zig");
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{pane});
    window.tab().focused = pane;
    const saved = try clipboard.TestSaved.save(pane.hwnd);
    defer saved.restore(pane.hwnd);

    TestKittyCore.reset();
    Surface.test_clipboard_core = &TestKittyCore.complete;
    defer Surface.test_clipboard_core = null;
    Surface.test_clipboard_deny = &TestKittyCore.deny;
    defer Surface.test_clipboard_deny = null;
    TestKittyPrompt.reset(pane.hwnd);
    const ClipboardDialog = @import("ClipboardDialog.zig");
    ClipboardDialog.test_run = &TestKittyPrompt.run;
    defer ClipboardDialog.test_run = null;
    const read_prompt = clipboard.clipboardPrompt(.kitty_read, &question);

    // Unasked, each type asked for under the name asked, and the listing.
    try writeClipboard(alloc, pane.hwnd, .of(&.{
        .{ .mime = "text/html", .data = "<b>h</b>" },
        .{ .mime = "text/plain", .data = "before" },
    }, false));
    {
        const req = try testKittyRead(alloc, .standard, &.{ "text/html", "text/plain" }, true);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
    }
    try std.testing.expectEqual(1, TestKittyCore.completed);
    try std.testing.expect(!TestKittyCore.confirmed);
    try std.testing.expectEqualStrings(
        "text/html=<b>h</b> text/plain=before text/plain text/html ",
        TestKittyCore.served(),
    );
    try std.testing.expectEqual(0, TestKittyPrompt.boxes);

    // The listing alone is served, with no type, or a type the clipboard
    // does not hold.
    for ([_][]const []const u8{ &.{}, &.{"image/png"} }) |mimes| {
        const req = try testKittyRead(alloc, .standard, mimes, true);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
        try std.testing.expectEqualStrings("text/plain text/html ", TestKittyCore.served());
    }
    try std.testing.expectEqual(3, TestKittyCore.completed);

    // Asked, and allowed: what was read before the prompt is served, though
    // the clipboard changed while it was up, and the clipboard was closed
    // before it, so another program could open it.
    TestKittyCore.ask = true;
    TestKittyPrompt.answer = win32.IDOK;
    {
        const req = try testKittyRead(alloc, .standard, &.{"text/plain"}, false);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
    }
    try TestKittyPrompt.first.preview.expect(std.unicode.utf8ToUtf16LeStringLiteral("before"));
    try TestKittyPrompt.expectAsked(read_prompt);
    try std.testing.expectEqual(1, TestKittyPrompt.boxes);
    try std.testing.expectEqual(1, TestKittyCore.asked);
    try std.testing.expectEqual(4, TestKittyCore.completed);
    try std.testing.expect(TestKittyCore.confirmed);
    try std.testing.expectEqualStrings("text/plain=before ", TestKittyCore.served());
    try clipboard.expectClipboard(pane.hwnd, "changed", null);

    // Asked, and denied: denied once, never completed.
    TestKittyPrompt.answer = win32.IDCANCEL;
    {
        const req = try testKittyRead(alloc, .standard, &.{"text/plain"}, false);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
    }
    try std.testing.expectEqual(2, TestKittyPrompt.boxes);
    try std.testing.expectEqual(1, TestKittyCore.denied);
    try std.testing.expectEqual(4, TestKittyCore.completed);

    // A completion that fails after consuming the request, unasked and
    // after Allow, is logged, not returned: the core would answer it again.
    TestKittyCore.fail = error.OutOfMemory;
    TestKittyPrompt.answer = win32.IDOK;
    for ([_]bool{ false, true }) |ask| {
        TestKittyCore.ask = ask;
        const req = try testKittyRead(alloc, .standard, &.{"text/plain"}, false);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
    }
    try std.testing.expectEqual(6, TestKittyCore.completed);
    try std.testing.expectEqual(1, TestKittyCore.denied);
    TestKittyCore.fail = null;

    // Nothing read and nothing listed is left to the core, which answers it
    // with nothing, asking nobody: a type the clipboard does not hold, and
    // an empty clipboard, its listing too. So is a primary selection, which
    // Windows has not (ENOSYS); and a clipboard another program holds open
    // is an error (EIO). The core frees each of these. Under an `ask`
    // policy, so a prompt would show one was asked.
    TestKittyCore.ask = true;
    const boxes = TestKittyPrompt.boxes;
    try clipboard.testPut(pane.hwnd, &.{}, &.{});
    for ([_]bool{ false, true }) |list| {
        const req = try testKittyRead(alloc, .standard, &.{"text/plain"}, list);
        try std.testing.expectEqual(.unavailable, try testKittyLeft(pane, .standard, .{ .kitty_read = req }));
    }
    try writeClipboard(alloc, pane.hwnd, .text("t"));
    {
        const req = try testKittyRead(alloc, .standard, &.{"image/png"}, false);
        try std.testing.expectEqual(.unavailable, try testKittyLeft(pane, .standard, .{ .kitty_read = req }));
    }
    {
        const req = try testKittyRead(alloc, .primary, &.{"text/plain"}, true);
        try std.testing.expectEqual(.unsupported, try testKittyLeft(pane, .primary, .{ .kitty_read = req }));
    }
    {
        const req = try testKittyRead(alloc, .standard, &.{"text/plain"}, true);
        const holder = try clipboard.TestHolder.start();
        defer holder.release();
        try std.testing.expectError(error.Win32CallFailed, testKittyLeft(pane, .standard, .{ .kitty_read = req }));
    }
    try std.testing.expectEqual(boxes, TestKittyPrompt.boxes);
    try std.testing.expectEqual(6, TestKittyCore.completed);
    try std.testing.expectEqual(1, TestKittyCore.denied);
}

test "win32: a Kitty clipboard write asks first, as a write, and answers once" {
    var question: Question = .{};
    const alloc = std.testing.allocator;
    // In a language of the user's, where a build has them.
    const i18n = internal_os.i18n;
    const catalog = try @import("../../os/i18n_catalog.zig").write(alloc, &.{
        .{ "Authorize Clipboard Access", "Zugriff erlauben" },
        .{ "Allow", "Erlauben" },
        .{ "Deny", "Nicht erlauben" },
    });
    defer alloc.free(catalog);
    if (comptime i18n.windows.embedded) try i18n.windows.testUse(catalog);
    defer if (comptime i18n.windows.embedded) i18n.windows.testUse(null) catch unreachable;
    const clipboard = @import("clipboard.zig");
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{pane});
    window.tab().focused = pane;
    const saved = try clipboard.TestSaved.save(pane.hwnd);
    defer saved.restore(pane.hwnd);

    TestKittyCore.reset();
    Surface.test_clipboard_core = &TestKittyCore.complete;
    defer Surface.test_clipboard_core = null;
    Surface.test_clipboard_deny = &TestKittyCore.deny;
    defer Surface.test_clipboard_deny = null;
    TestKittyPrompt.reset(pane.hwnd);
    const ClipboardDialog = @import("ClipboardDialog.zig");
    ClipboardDialog.test_run = &TestKittyPrompt.run;
    defer ClipboardDialog.test_run = null;

    // A write carries what it writes, which the core writes once allowed.
    // Unasked, then asked and allowed, then asked and denied.
    {
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try std.testing.expectEqual(1, TestKittyCore.completed);
    try std.testing.expect(!TestKittyCore.confirmed);
    try std.testing.expectEqualStrings("", TestKittyCore.served());
    try std.testing.expectEqual(0, TestKittyPrompt.boxes);

    TestKittyCore.ask = true;
    TestKittyPrompt.answer = win32.IDOK;
    {
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try TestKittyPrompt.expectAsked(clipboard.clipboardPrompt(.kitty_write, &question));
    try std.testing.expectEqual(2, TestKittyCore.completed);
    try std.testing.expect(TestKittyCore.confirmed);

    TestKittyPrompt.answer = win32.IDCANCEL;
    {
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try std.testing.expectEqual(2, TestKittyPrompt.boxes);
    try std.testing.expectEqual(1, TestKittyCore.denied);
    try std.testing.expectEqual(2, TestKittyCore.completed);

    // A completion that fails after consuming the write is logged, not
    // returned; a write to the primary selection is left to the core.
    TestKittyCore.ask = false;
    TestKittyCore.fail = error.OutOfMemory;
    {
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try std.testing.expectEqual(3, TestKittyCore.completed);
    {
        const req = try testKittyWrite(alloc, .primary, "w");
        try std.testing.expectEqual(.unsupported, try testKittyLeft(pane, .primary, .{ .kitty_write = req }));
    }
    try std.testing.expectEqual(3, TestKittyCore.completed);
    try std.testing.expectEqual(2, TestKittyPrompt.boxes);
}

test "win32: the Kitty clipboard prompt shows each part, escaped, and remembers only an Allow with a password" {
    var question: Question = .{};
    const alloc = std.testing.allocator;
    const clipboard = @import("clipboard.zig");
    const ClipboardDialog = @import("ClipboardDialog.zig");
    const W = std.unicode.utf8ToUtf16LeStringLiteral;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{pane});
    window.tab().focused = pane;
    const saved = try clipboard.TestSaved.save(pane.hwnd);
    defer saved.restore(pane.hwnd);

    TestKittyCore.reset();
    TestKittyCore.ask = true;
    Surface.test_clipboard_core = &TestKittyCore.complete;
    defer Surface.test_clipboard_core = null;
    Surface.test_clipboard_deny = &TestKittyCore.deny;
    defer Surface.test_clipboard_deny = null;
    TestKittyPrompt.reset(pane.hwnd);
    ClipboardDialog.test_run = &TestKittyPrompt.run;
    defer ClipboardDialog.test_run = null;
    const P = TestKittyPrompt;

    // A read of two types: listed by name and size, the first shown, the
    // text with its override escaped, then the other picked. With no
    // password there is no box to remember, checked or not.
    try writeClipboard(alloc, pane.hwnd, .of(&.{
        .{ .mime = "text/html", .data = "<b>h</b>" },
        .{ .mime = "text/plain", .data = "a\u{202E}b" },
    }, false));
    P.answer = win32.IDOK;
    P.check = true;
    P.pick = 1;
    {
        const req = try testKittyRead(alloc, .standard, &.{ "text/plain", "text/html" }, false);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
    }
    try std.testing.expectEqual(2, P.first.count);
    try P.first.part.expect(W("text/plain (5 bytes)"));
    try std.testing.expectEqual(@as(?c_int, ClipboardDialog.id_text), P.first.shown);
    try P.first.preview.expect(W("a\\u{202E}b"));
    try std.testing.expect(!P.first.offered);
    try std.testing.expect(P.first.unwritten == null);
    try P.picked.part.expect(W("text/html (8 bytes)"));
    try std.testing.expectEqual(1, P.picked.previews);
    try P.picked.preview.expect(W("<b>h</b>"));
    try P.expectAsked(clipboard.clipboardPrompt(.kitty_read, &question));
    try std.testing.expect(TestKittyCore.confirmed);
    try std.testing.expect(!TestKittyCore.remembered);

    // With a password the box is offered: Allow with it checked keeps a
    // session grant, without it does not, and Deny never does.
    P.pick = null;
    for ([_]struct { bool, c_int }{ .{ true, win32.IDOK }, .{ false, win32.IDOK }, .{ true, win32.IDCANCEL } }) |c| {
        P.check = c[0];
        P.answer = c[1];
        const completed = TestKittyCore.completed;
        const denied = TestKittyCore.denied;
        const req = try testKittyRead(alloc, .standard, &.{"text/plain"}, false);
        req.pw = "pw";
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_read = req }));
        try std.testing.expect(P.first.offered);
        // One part, what the last prompt wrote: its name, no list.
        try std.testing.expectEqual(0, P.first.count);
        try P.first.part.expect(W("text/plain (7 bytes)"));
        if (c[1] == win32.IDOK) {
            try std.testing.expectEqual(completed + 1, TestKittyCore.completed);
            try std.testing.expectEqual(c[0], TestKittyCore.remembered);
        } else {
            try std.testing.expectEqual(completed, TestKittyCore.completed);
            try std.testing.expectEqual(denied + 1, TestKittyCore.denied);
        }
    }

    // A write: a PNG drawn over the dialog's face, a type Windows has no
    // format for named as left out, its name escaped, and a PNG too large
    // to decode, picked, shown as its size.
    var large = clipboard.test_png.*;
    std.mem.writeInt(u32, large[16..20], 4096, .big);
    std.mem.writeInt(u32, large[20..24], 4096, .big);
    P.check = false;
    P.answer = win32.IDOK;
    P.pick = 2;
    {
        const req = try testKittyWriteOf(alloc, .standard, &.{
            .{ .mime = "image/png", .data = clipboard.test_png },
            .{ .mime = "application/x-\u{202E}a", .data = "x" },
            .{ .mime = "image/png", .data = &large },
        });
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try std.testing.expectEqual(3, P.first.count);
    try std.testing.expectEqual(@as(?c_int, ClipboardDialog.id_image), P.first.shown);
    // Opaque red, and the face around it.
    try std.testing.expectEqual(@as(?win32.COLORREF, 0x0000FF), P.first.quarter);
    try std.testing.expectEqual(@as(?win32.COLORREF, win32.GetSysColor(win32.COLOR_BTNFACE)), P.first.face);
    try std.testing.expectEqual(@as(?bool, true), P.first.restored);
    const unwritten = P.first.unwritten orelse return error.TestUnexpectedResult;
    try unwritten.expect(W("Not written, Windows has no clipboard format for: application/x-\\u{202E}a"));
    try std.testing.expectEqual(@as(?c_int, ClipboardDialog.id_none), P.picked.shown);
    {
        var buf: [64]u8 = undefined;
        const want = try std.fmt.bufPrint(&buf, "No preview available\r\n{d} bytes", .{large.len});
        var wide: [64]u16 = undefined;
        const n = try std.unicode.utf8ToUtf16Le(&wide, want);
        try P.picked.preview.expect(wide[0..n]);
    }
    try P.expectAsked(clipboard.clipboardPrompt(.kitty_write, &question));

    // A write of as many parts as the core commits, its types and then the
    // aliases that name new ones, lists every one: the last, the one
    // written as text, is there to pick. One more is denied unasked.
    {
        const max = terminal.kitty.clipboard.max_write_mimes + terminal.kitty.clipboard.max_write_aliases;
        var names: [max + 1][24]u8 = undefined;
        var parts: [max + 1]TestPart = undefined;
        for (&parts, &names, 0..) |*part, *name, i| part.* = .{
            .mime = std.fmt.bufPrint(name, "application/x-{d}", .{i}) catch unreachable,
            .data = "x",
        };
        parts[max - 1] = .{ .mime = "text/plain", .data = "landed" };
        P.pick = max - 1;
        const req = try testKittyWriteOf(alloc, .standard, parts[0..max]);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
        try std.testing.expectEqual(max, P.first.count);
        try P.picked.part.expect(W("text/plain (6 bytes)"));
        try P.picked.preview.expect(W("landed"));
        try P.expectAsked(clipboard.clipboardPrompt(.kitty_write, &question));

        const boxes = P.boxes;
        const denied = TestKittyCore.denied;
        const more = try testKittyWriteOf(alloc, .standard, &parts);
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = more }));
        try std.testing.expectEqual(denied + 1, TestKittyCore.denied);
        try std.testing.expectEqual(boxes, P.boxes);
    }

    // An empty write, which clears the clipboard, shows the empty text it
    // writes.
    P.pick = null;
    {
        const req = try testKittyWriteOf(alloc, .standard, &.{});
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try P.first.part.expect(W("text/plain (0 bytes)"));
    try std.testing.expectEqual(@as(?c_int, ClipboardDialog.id_text), P.first.shown);
    try P.first.preview.expect(W(""));

    // Unanswered is Deny; so is a prompt that cannot be shown, and one
    // asked for while the windows close, which shows nothing.
    P.answer = null;
    {
        const denied = TestKittyCore.denied;
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
        try std.testing.expectEqual(denied + 1, TestKittyCore.denied);
    }
    P.answer = win32.IDOK;
    const boxes = P.boxes;
    {
        ClipboardDialog.test_fail = true;
        defer ClipboardDialog.test_fail = false;
        const denied = TestKittyCore.denied;
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
        try std.testing.expectEqual(denied + 1, TestKittyCore.denied);
    }
    {
        app.terminating = true;
        defer app.terminating = false;
        const denied = TestKittyCore.denied;
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
        try std.testing.expectEqual(denied + 1, TestKittyCore.denied);
    }
    try std.testing.expectEqual(boxes, P.boxes);
}

test "win32: a Kitty clipboard prompt's title bar follows its window's" {
    const alloc = std.testing.allocator;
    const clipboard = @import("clipboard.zig");
    const ClipboardDialog = @import("ClipboardDialog.zig");
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    app.config.@"window-theme" = .dark;
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    window.applyTheme();
    try std.testing.expect(window.dark_frame);
    const pane = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{pane});
    window.tab().focused = pane;
    const saved = try clipboard.TestSaved.save(pane.hwnd);
    defer saved.restore(pane.hwnd);

    TestKittyCore.reset();
    TestKittyCore.ask = true;
    Surface.test_clipboard_core = &TestKittyCore.complete;
    defer Surface.test_clipboard_core = null;
    Surface.test_clipboard_deny = &TestKittyCore.deny;
    defer Surface.test_clipboard_deny = null;
    TestKittyPrompt.reset(pane.hwnd);
    ClipboardDialog.test_run = &TestKittyPrompt.run;
    defer ClipboardDialog.test_run = null;
    const P = TestKittyPrompt;
    var question: Question = .{};

    // A new configuration while the prompt is up re-themes it with the
    // frame.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"window-theme" = .light;
    const light = struct {
        var app_: *App = undefined;
        var config: *const Config = undefined;
        var done = false;
        fn change() void {
            done = app_.performAction(.app, .config_change, .{ .config = config }) catch false;
        }
    };
    light.app_ = &app;
    light.config = &changed;
    light.done = false;
    P.during = &light.change;
    {
        const req = try testKittyWrite(alloc, .standard, "w");
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try std.testing.expect(light.done);
    try std.testing.expect(!window.dark_frame);
    try std.testing.expectEqual(@as(?bool, true), P.first.dark);
    try std.testing.expectEqual(@as(?bool, false), P.after.dark);
    try P.expectAsked(clipboard.clipboardPrompt(.kitty_write, &question));
    // Closed, it is forgotten.
    try std.testing.expect(window.clipboard_prompt == null);
}

test "win32: a Kitty clipboard prompt that can allocate nothing lists each part in its place and still answers" {
    var question: Question = .{};
    const alloc = std.testing.allocator;
    const clipboard = @import("clipboard.zig");
    const ClipboardDialog = @import("ClipboardDialog.zig");
    const W = std.unicode.utf8ToUtf16LeStringLiteral;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{pane});
    window.tab().focused = pane;
    const saved = try clipboard.TestSaved.save(pane.hwnd);
    defer saved.restore(pane.hwnd);

    TestKittyCore.reset();
    TestKittyCore.ask = true;
    Surface.test_clipboard_core = &TestKittyCore.complete;
    defer Surface.test_clipboard_core = null;
    Surface.test_clipboard_deny = &TestKittyCore.deny;
    defer Surface.test_clipboard_deny = null;
    TestKittyPrompt.reset(pane.hwnd);
    ClipboardDialog.test_run = &TestKittyPrompt.run;
    defer ClipboardDialog.test_run = null;
    const P = TestKittyPrompt;

    // No name, escaped text or list of what a write leaves out can be made.
    var failing: std.testing.FailingAllocator = .init(alloc, .{ .fail_index = 0 });
    ClipboardDialog.test_alloc = failing.allocator();
    defer ClipboardDialog.test_alloc = null;

    // Each part still has its entry, named by its place and size, and the
    // one picked is the one shown, as its size. Allow still allows.
    P.answer = win32.IDOK;
    P.pick = 1;
    {
        const completed = TestKittyCore.completed;
        const req = try testKittyWriteOf(alloc, .standard, &.{
            .{ .mime = "text/plain", .data = "abc" },
            .{ .mime = "application/x-a", .data = "abcdefgh" },
        });
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
        try std.testing.expectEqual(completed + 1, TestKittyCore.completed);
    }
    try std.testing.expectEqual(2, P.first.count);
    try P.first.part.expect(W("Part 1 (3 bytes)"));
    try P.first.preview.expect(W("No preview available\r\n3 bytes"));
    try P.picked.part.expect(W("Part 2 (8 bytes)"));
    try P.picked.preview.expect(W("No preview available\r\n8 bytes"));
    const unwritten = P.first.unwritten orelse return error.TestUnexpectedResult;
    try unwritten.expect(W("Some types are not written: Windows has no clipboard format for them"));
    try P.expectAsked(clipboard.clipboardPrompt(.kitty_write, &question));

    // One part, named the same way.
    P.pick = null;
    {
        const req = try testKittyWriteOf(alloc, .standard, &.{.{ .mime = "text/plain", .data = "abcd" }});
        try std.testing.expectEqual(.started, try pane.clipboardRequest(.standard, .{ .kitty_write = req }));
    }
    try std.testing.expectEqual(0, P.first.count);
    try P.first.part.expect(W("Part 1 (4 bytes)"));
    try P.expectAsked(clipboard.clipboardPrompt(.kitty_write, &question));
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expectEqual(0, failing.allocations);
}

/// For tests: `pane`'s title prompt for `which`, opened as a binding opens
/// it: the action, then `run`'s requests (`createRequested`).
fn testPrompt(app: *App, pane: *Surface, which: apprt.action.PromptTitle) !win32.HWND {
    try std.testing.expect(try app.performAction(.{ .surface = &pane.core_surface }, .prompt_title, which));
    app.createRequested();
    return pane.window.title_prompt.hwnd orelse error.TestUnexpectedResult;
}

/// For tests: a title prompt's field.
fn testField(dialog: win32.HWND) !win32.HWND {
    return win32.GetDlgItem(dialog, TitleDialog.edit_id) orelse error.TestUnexpectedResult;
}

/// For tests: put `text` in a title prompt's field, then press `button`
/// (IDOK or IDCANCEL), as a click on it sends.
fn testAnswer(dialog: win32.HWND, comptime text: []const u8, button: c_int) !void {
    _ = win32.SetWindowTextW(try testField(dialog), L(text));
    _ = win32.SendMessageW(dialog, win32.WM_COMMAND, @intCast(button), 0);
}

/// For tests: `hwnd`'s text is `want`.
fn expectText(comptime want: []const u8, hwnd: win32.HWND) !void {
    var buf: [128]u16 = undefined;
    const n = win32.GetWindowTextW(hwnd, &buf, buf.len);
    try std.testing.expectEqualSlices(u16, std.unicode.utf8ToUtf16LeStringLiteral(want), buf[0..@intCast(n)]);
}

test "win32: the title prompt's labels are the user's language's, and each fits its control" {
    const i18n = internal_os.i18n;
    if (comptime !i18n.windows.embedded) return error.SkipZigTest;
    const locales = @import("../../os/i18n_locales.zig").locales;
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    const target: apprt.Target = .{ .surface = &pane.core_surface };

    defer i18n.windows.testUse(null) catch unreachable;
    var cut: usize = 0;
    for (locales, 0..) |locale, i| {
        errdefer std.debug.print("locale={s}\n", .{locale});
        try i18n.windows.testUseLocale(i);
        try std.testing.expect(try app.performAction(target, .prompt_title, .surface));
        app.createRequested();
        const prompt = window.title_prompt.hwnd orelse return error.TestUnexpectedResult;
        defer TitleDialog.close(window);

        // What each shows is the catalog's.
        const ok = win32.GetDlgItem(prompt, win32.IDOK) orelse return error.TestUnexpectedResult;
        const cancel = win32.GetDlgItem(prompt, win32.IDCANCEL) orelse return error.TestUnexpectedResult;
        const note = win32.GetDlgItem(prompt, TitleDialog.note_id) orelse return error.TestUnexpectedResult;
        var want: [256]u16 = undefined;
        var got: [256]u16 = undefined;
        inline for (.{
            .{ prompt, "Change Terminal Title" },
            .{ ok, "OK" },
            .{ cancel, "Cancel" },
            .{ note, "Leave blank to restore the default title." },
        }) |case| {
            const n = try std.unicode.utf8ToUtf16Le(&want, std.mem.span(i18n._(case[1])));
            const len: usize = @intCast(win32.GetWindowTextW(case[0], &got, got.len));
            try std.testing.expectEqualSlices(u16, want[0..n], got[0..len]);
        }

        // And none is cut: the note in its line, a button's label inside
        // its frame. The clipboard prompt's buttons are as wide and in
        // the same font, so theirs are measured here too.
        // Every language is measured before any fails the test, so that
        // one run names them all.
        const before = cut;
        if (!try labelFits(&app, note, "Leave blank to restore the default title.", 0)) cut += 1;
        inline for (.{ "OK", "Cancel", "Allow", "Deny" }) |msgid| {
            if (!try labelFits(&app, ok, msgid, 8)) cut += 1;
        }
        if (cut != before) std.debug.print("locale={s}\n", .{locale});
    }
    try std.testing.expectEqual(0, cut);
}

/// For tests: `msgid` in the language in use, drawn in `control`'s font,
/// is no wider than `control` less `frame` pixels at 96 DPI. One that is
/// wider is printed with both widths.
fn labelFits(app: *const App, control: win32.HWND, comptime msgid: [:0]const u8, frame: c_int) !bool {
    const hdc = win32.GetDC(control) orelse return error.TestUnexpectedResult;
    defer _ = win32.ReleaseDC(control, hdc);
    const font: usize = @bitCast(win32.SendMessageW(control, win32.WM_GETFONT, 0, 0));
    try std.testing.expect(font != 0);
    const old = win32.SelectObject(hdc, @ptrFromInt(font));
    defer if (old) |o| {
        _ = win32.SelectObject(hdc, o);
    };
    var wide: [256]u16 = undefined;
    const n = try std.unicode.utf8ToUtf16Le(&wide, std.mem.span(internal_os.i18n._(msgid)));
    var r: win32.RECT = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
    _ = win32.DrawTextW(hdc, &wide, @intCast(n), &r, win32.DT_SINGLELINE | win32.DT_CALCRECT);
    var client: win32.RECT = undefined;
    try std.testing.expect(win32.GetClientRect(control, &client).toBool());
    const room = client.right - @divTrunc(frame * @as(c_int, @intCast(Window.dpiOf(app, control))), 96);
    if (r.right > room) {
        std.debug.print("{s}: {} px of text in {} px\n", .{ msgid, r.right, room });
        return false;
    }
    return true;
}

test "win32: prompt_title waits for run, and the terminal's title from it shows over the program's" {
    // The dialog takes the keyboard focus from the terminal, so the action
    // is recorded and the dialog opened by createRequested. OK sets the
    // terminal's own title, which OSC titles do not replace; an empty one
    // shows the program's latest again; Cancel changes nothing. The core's
    // title stays the program's.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    try std.testing.expect(pane.setTitle("cmd"));
    const target: apprt.Target = .{ .surface = &pane.core_surface };

    // Not for the app.
    try std.testing.expect(!try app.performAction(.app, .prompt_title, .surface));
    try std.testing.expectEqual(0, app.requests.items.len);

    // Recorded, and opened by run.
    try std.testing.expect(try app.performAction(target, .prompt_title, .surface));
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());
    app.createRequested();
    const dialog = window.title_prompt.hwnd orelse return error.TestUnexpectedResult;
    // Modal to its window, and not on screen while the window is not;
    // GTK's heading, and the field holds the title shown.
    try std.testing.expect(!win32.IsWindowEnabled(window.hwnd).toBool());
    try std.testing.expect(!win32.IsWindowVisible(dialog).toBool());
    try expectText("Change Terminal Title", dialog);
    try expectText("cmd", try testField(dialog));

    // Asked again while it is open: it stays as it is.
    try std.testing.expect(try app.performAction(target, .prompt_title, .tab));
    app.createRequested();
    try std.testing.expect(window.title_prompt.hwnd == dialog);
    try expectText("Change Terminal Title", dialog);

    // OK: the terminal's title is the user's, the window takes input
    // again, and the core still reads the program's.
    try testAnswer(dialog, "mine", win32.IDOK);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(!win32.IsWindow(dialog).toBool());
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());
    try expectText("mine", window.hwnd);
    try std.testing.expectEqualStrings("mine", Window.tabTitle(window.tab()).?);
    try std.testing.expectEqualStrings("cmd", pane.getTitle().?);

    // An OSC title changes the program's, not what shows.
    try std.testing.expect(try app.performAction(target, .set_title, .{ .title = "osc" }));
    try expectText("mine", window.hwnd);
    try std.testing.expectEqualStrings("osc", pane.getTitle().?);

    // The field starts with the user's title; Cancel changes nothing.
    const again = try testPrompt(&app, pane, .surface);
    try expectText("mine", try testField(again));
    try testAnswer(again, "other", win32.IDCANCEL);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());
    try expectText("mine", window.hwnd);

    // Enter in the field is OK, as `run` dispatches it (`dispatch`, which
    // hands the dialog its messages); one for the terminal is not the
    // dialog's. Empty, it shows the program's latest title again.
    const third = try testPrompt(&app, pane, .surface);
    const field = try testField(third);
    var msg: win32.MSG = .{
        .hwnd = pane.hwnd,
        .message = win32.WM_KEYDOWN,
        .wParam = win32.VK_RETURN,
        .lParam = 0,
        .time = 0,
        .pt = .{ .x = 0, .y = 0 },
    };
    try std.testing.expect(!app.dialogMessage(&msg));
    try std.testing.expect(window.title_prompt.hwnd == third);
    _ = win32.SetWindowTextW(field, L(""));
    msg.hwnd = field;
    app.dispatch(&msg);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(pane.title_override == null);
    try expectText("osc", window.hwnd);
}

test "win32: a tab's title prompt names the tab, over its terminals' own titles" {
    // As GTK computes a tab's title: the tab's own, else its focused
    // terminal's own, else the program's.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;
    const b = try testTab(&app, window);
    const ta = window.tabOf(a).?;
    const tb = window.tabOf(b).?;
    try std.testing.expect(a.setTitle("vim"));
    try std.testing.expect(b.setTitle("cmd"));

    // The terminal's own title labels its tab.
    try testAnswer(try testPrompt(&app, a, .surface), "edit", win32.IDOK);
    try std.testing.expectEqualStrings("edit", Window.tabTitle(ta).?);

    // The tab's, which starts from that, shows over it.
    const dialog = try testPrompt(&app, a, .tab);
    try expectText("Change Tab Title", dialog);
    try expectText("edit", try testField(dialog));
    try testAnswer(dialog, "build", win32.IDOK);
    try std.testing.expectEqualStrings("build", ta.title_override.?);
    try std.testing.expectEqualStrings("edit", a.title_override.?);
    try expectText("build", window.hwnd);

    // Empty, it ends the tab's: the terminal's own shows again.
    const again = try testPrompt(&app, a, .tab);
    try expectText("build", try testField(again));
    try testAnswer(again, "", win32.IDOK);
    try std.testing.expect(ta.title_override == null);
    try expectText("edit", window.hwnd);

    // A hidden tab's: its label changes, the caption does not.
    try testAnswer(try testPrompt(&app, b, .tab), "logs", win32.IDOK);
    try std.testing.expectEqualStrings("logs", Window.tabTitle(tb).?);
    try expectText("edit", window.hwnd);
}

test "win32: a window's own title shows in its caption over every tab's, without the bell's prefix" {
    // GTK's window title override (`setTitleOverride`): set_window_title
    // titles the terminal's window, whichever tab shows, and leaves the
    // tabs' labels their own; an empty title ends it. The bell's prefix is
    // the tab's (`closureTitle` returns the override as it is). The title
    // stays with its window when a tab moves to a new one.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    Window.test_set_focus = &FocusSeen.seen;
    defer Window.test_set_focus = null;

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;
    const b = try testTab(&app, window);
    try std.testing.expect(a.setTitle("vim"));
    try std.testing.expect(b.setTitle("cmd"));
    const target: apprt.Target = .{ .surface = &a.core_surface };
    var buf: [64]u8 = undefined;

    try std.testing.expect(!try app.performAction(.app, .set_window_title, .{ .title = "x" }));

    // Over the shown tab's title, which neither a program's title nor the
    // tab's own then shows through; the tab's label keeps its own.
    try std.testing.expect(try app.performAction(target, .set_window_title, .{ .title = "proj" }));
    try std.testing.expectEqualStrings("proj", try windowText(window.hwnd, &buf));
    try std.testing.expect(try app.performAction(target, .set_title, .{ .title = "osc" }));
    try std.testing.expect(try app.performAction(target, .set_tab_title, .{ .title = "build" }));
    try std.testing.expectEqualStrings("proj", try windowText(window.hwnd, &buf));
    try std.testing.expectEqualStrings("build", Window.tabTitle(window.tab()).?);

    // No memory to store another: false, and the window keeps its title.
    var failing: std.testing.FailingAllocator = .init(alloc, .{ .fail_index = 0 });
    core_app.alloc = failing.allocator();
    try std.testing.expect(!try app.performAction(target, .set_window_title, .{ .title = "lost" }));
    core_app.alloc = alloc;
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expectEqualStrings("proj", window.title_override.?);
    try std.testing.expectEqualStrings("proj", try windowText(window.hwnd, &buf));

    // The other tab shown, and ringing: the window's title still, with no
    // prefix, which the tab's label has.
    window.selectTab(1);
    try std.testing.expect(window.tab().focused == b);
    try std.testing.expectEqualStrings("proj", try windowText(window.hwnd, &buf));
    try std.testing.expect(try testBell(&app, b));
    try std.testing.expect(b.bell_ringing);
    try std.testing.expectEqualStrings("proj", try windowText(window.hwnd, &buf));
    const label = try window.shownTitle(alloc, window.tab());
    defer alloc.free(label);
    try std.testing.expectEqualSlices(u16, std.unicode.utf8ToUtf16LeStringLiteral("🔔 cmd"), label);

    // Empty: the shown tab's title again, with its prefix.
    try std.testing.expect(try app.performAction(target, .set_window_title, .{ .title = "" }));
    try std.testing.expect(window.title_override == null);
    try std.testing.expectEqualStrings("🔔 cmd", try windowText(window.hwnd, &buf));

    // A tab moved to a new window: the title stays with this one.
    try std.testing.expect(try app.performAction(target, .set_window_title, .{ .title = "proj" }));
    try std.testing.expect(try app.performAction(.{ .surface = &b.core_surface }, .move_tab_to_new_window, {}));
    app.createRequested();
    try std.testing.expect(b.window != window);
    try std.testing.expect(b.window.title_override == null);
    try std.testing.expectEqualStrings("proj", window.title_override.?);
    try std.testing.expectEqualStrings("proj", try windowText(window.hwnd, &buf));
}

test "win32: the window's title prompt asks for its own title, and stays when the terminal that asked closes" {
    // GTK's `promptWindowTitle`: the field starts with the window's own
    // title, else its shown tab's; the dialog belongs to the window.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    testResize(window, 800, 300);
    const a = try testPane(&app, window);
    const b = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ a, b });
    window.tab().focused = a;
    try std.testing.expect(a.setTitle("vim"));

    // GTK's heading, and the shown tab's title.
    const dialog = try testPrompt(&app, a, .window);
    try expectText("Change Window Title", dialog);
    try expectText("vim", try testField(dialog));

    // The terminal that asked closes: the prompt stays, for the window.
    try std.testing.expect(a.destroy());
    try std.testing.expect(window.title_prompt.hwnd == dialog);
    try std.testing.expect(!win32.IsWindowEnabled(window.hwnd).toBool());

    // OK: the window's title, and neither the tab's nor a terminal's.
    try testAnswer(dialog, "proj", win32.IDOK);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());
    try std.testing.expectEqualStrings("proj", window.title_override.?);
    try expectText("proj", window.hwnd);
    try std.testing.expect(window.tab().title_override == null);
    try std.testing.expect(b.title_override == null);

    // It starts with the window's own title; Cancel changes nothing, and
    // an empty title ends it.
    const again = try testPrompt(&app, b, .window);
    try expectText("proj", try testField(again));
    try testAnswer(again, "other", win32.IDCANCEL);
    try expectText("proj", window.hwnd);
    const third = try testPrompt(&app, b, .window);
    try testAnswer(third, "", win32.IDOK);
    try std.testing.expect(window.title_override == null);
    try expectText("Ghostty", window.hwnd);
}

test "win32: a title prompt closes with its terminal, and never opens for a closing one" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    const a2 = try testPane(&app, window);
    const a3 = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ a, a2, a3 });
    window.tab().focused = a;

    // Asked for by a terminal that begins to close before run: dropped.
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .prompt_title, .surface));
    app.forgetClosing(&a.core_surface);
    try std.testing.expect(app.requests.items[0] == .dropped);
    app.createRequested();
    try std.testing.expect(window.title_prompt.hwnd == null);

    // Open when it begins to close: it closes, and its window takes input.
    const dialog = try testPrompt(&app, a, .surface);
    app.forgetClosing(&a.core_surface);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(!win32.IsWindow(dialog).toBool());
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());

    // Another terminal of the window closing leaves it open.
    const kept = try testPrompt(&app, a, .surface);
    app.forgetClosing(&a2.core_surface);
    try std.testing.expect(window.title_prompt.hwnd == kept);
    try std.testing.expect(!win32.IsWindowEnabled(window.hwnd).toBool());

    // Destroyed by anything but its own close, it lets go of the window.
    try std.testing.expect(win32.DestroyWindow(kept).toBool());
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());

    // A terminal torn down with no core, which never passes through
    // forgetClosing: its prompt closes as it is freed.
    const freed = try testPrompt(&app, a3, .surface);
    try std.testing.expect(a3.destroy());
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(!win32.IsWindow(freed).toBool());
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());

    // None opens for a terminal already closing, nor in a closing window.
    a2.requestClose();
    try std.testing.expect(try app.performAction(.{ .surface = &a2.core_surface }, .prompt_title, .surface));
    app.createRequested();
    try std.testing.expect(window.title_prompt.hwnd == null);
    window.requestClose();
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .prompt_title, .tab));
    app.createRequested();
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());
}

test "win32: a title prompt closes when its terminal's tab moves to a new window" {
    // It is modal to the window it opened over, which a move from another
    // window would leave disabled for a terminal no longer in it.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    testResize(window, 800, 300);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;
    const b = try testTab(&app, window);
    _ = try testTab(&app, window);

    const dialog = try testPrompt(&app, a, .surface);

    // Another tab's move leaves it.
    try std.testing.expect(try app.performAction(.{ .surface = &b.core_surface }, .move_tab_to_new_window, {}));
    app.createRequested();
    try std.testing.expectEqual(2, app.windows.items.len);
    try std.testing.expect(window.title_prompt.hwnd == dialog);
    try std.testing.expect(!win32.IsWindowEnabled(window.hwnd).toBool());

    // Its terminal's: it closes, and the window takes input again.
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .move_tab_to_new_window, {}));
    app.createRequested();
    try std.testing.expectEqual(3, app.windows.items.len);
    try std.testing.expect(a.window != window);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(!win32.IsWindow(dialog).toBool());
    try std.testing.expect(win32.IsWindowEnabled(window.hwnd).toBool());
}

test "win32: a frame is enabled only when neither a prompt nor its title prompt holds it" {
    // Three things hold a frame: a confirmation prompt (every frame but
    // its owner), MessageBoxW (its owner) and the frame's title prompt.
    // Whichever lets go last enables it. MessageBoxW itself is never
    // called here: it would block the test.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const f = try testFrame(&app);
    const a = try testPane(&app, f);
    f.tab().tree = try .init(alloc, a);
    f.tab().focused = a;
    const g = try testFrame(&app);
    const b = try testPane(&app, g);
    g.tab().tree = try .init(alloc, b);
    g.tab().focused = b;
    const enabled = struct {
        fn check(hwnd: win32.HWND) bool {
            return win32.IsWindowEnabled(hwnd).toBool();
        }
    }.check;

    // A prompt of the other window's opens over the title prompt, which
    // it disables too, and the title prompt closes first: the frame waits
    // for the prompt's end.
    const dialog = try testPrompt(&app, a, .surface);
    app.beginPrompt(g.hwnd);
    try std.testing.expect(!enabled(dialog));
    try std.testing.expect(!enabled(f.hwnd));
    try std.testing.expect(enabled(g.hwnd));
    app.forgetClosing(&a.core_surface);
    try std.testing.expect(f.title_prompt.hwnd == null);
    try std.testing.expect(!enabled(f.hwnd));
    app.endPrompt();
    try std.testing.expect(enabled(f.hwnd));
    try std.testing.expect(enabled(g.hwnd));

    // A prompt owned by the frame itself, which ends first: the title
    // prompt still holds the frame, even if MessageBoxW enabled its owner
    // on the way out, and takes input again.
    const again = try testPrompt(&app, a, .surface);
    app.beginPrompt(f.hwnd);
    try std.testing.expect(!enabled(again));
    try std.testing.expect(!enabled(f.hwnd));
    try std.testing.expect(!enabled(g.hwnd));
    _ = win32.EnableWindow(f.hwnd, .TRUE);
    app.endPrompt();
    try std.testing.expect(!enabled(f.hwnd));
    try std.testing.expect(enabled(again));
    try std.testing.expect(enabled(g.hwnd));
    try testAnswer(again, "t", win32.IDOK);
    try std.testing.expect(enabled(f.hwnd));
}

/// For tests: the window `Window.bringForward` last asked to make the
/// foreground window (`Window.test_foreground`).
const ForegroundSeen = struct {
    var last: ?win32.HWND = null;
    fn seen(hwnd: win32.HWND) void {
        last = hwnd;
    }
};

test "win32: a confirmation prompt over a title prompt's window is owned by the title prompt" {
    // So that MessageBoxW, which disables its owner and enables it again
    // with the activation as it returns, gives the keyboard back to the
    // title prompt, not to the frame the title prompt holds disabled.
    // MessageBoxW itself is never called here: it would block the test;
    // what it does to its owner is done by hand.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const f = try testFrame(&app);
    const a = try testPane(&app, f);
    f.tab().tree = try .init(alloc, a);
    f.tab().focused = a;
    const g = try testFrame(&app);
    const b = try testPane(&app, g);
    g.tab().tree = try .init(alloc, b);
    g.tab().focused = b;
    const enabled = struct {
        fn check(hwnd: win32.HWND) bool {
            return win32.IsWindowEnabled(hwnd).toBool();
        }
    }.check;

    // With no title prompt, a terminal's prompt is its frame's.
    try std.testing.expect(app.promptOwner(a.hwnd) == f.hwnd);

    // A terminal under a title prompt (an OSC 52 read asking): the title
    // prompt's; another window's terminal: its own frame's.
    const dialog = try testPrompt(&app, a, .surface);
    const owner = app.promptOwner(a.hwnd) orelse return error.TestUnexpectedResult;
    try std.testing.expect(owner == dialog);
    try std.testing.expect(app.promptOwner(b.hwnd) == g.hwnd);

    // The title prompt is left for MessageBoxW to disable; every frame is
    // held.
    app.beginPrompt(owner);
    try std.testing.expect(enabled(dialog));
    try std.testing.expect(!enabled(f.hwnd));
    try std.testing.expect(!enabled(g.hwnd));
    try std.testing.expect(!f.title_prompt.prompt_disabled);
    _ = win32.EnableWindow(dialog, .FALSE);
    _ = win32.EnableWindow(dialog, .TRUE);
    app.endPrompt();
    try std.testing.expect(enabled(dialog));
    try std.testing.expect(!enabled(f.hwnd));
    try std.testing.expect(enabled(g.hwnd));
    try testAnswer(dialog, "t", win32.IDOK);
    try std.testing.expect(enabled(f.hwnd));
}

test "win32: presenting a window with its title prompt open brings the prompt forward" {
    // goto_window, present_terminal and a toast's click present a window
    // (`Window.present`); the prompt is where the keyboard goes, and the
    // frame takes no input while it is open.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    Window.test_foreground = &ForegroundSeen.seen;
    defer Window.test_foreground = null;
    ForegroundSeen.last = null;

    const f = try testFrame(&app);
    const a = try testPane(&app, f);
    f.tab().tree = try .init(alloc, a);
    f.tab().focused = a;
    const g = try testFrame(&app);
    const b = try testPane(&app, g);
    g.tab().tree = try .init(alloc, b);
    g.tab().focused = b;

    const dialog = try testPrompt(&app, a, .surface);

    // goto_window from the other window.
    try std.testing.expect(try app.performAction(.{ .surface = &b.core_surface }, .goto_window, .next));
    app.createRequested();
    try std.testing.expect(ForegroundSeen.last == dialog);

    // present_terminal for the terminal under it.
    ForegroundSeen.last = null;
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .present_terminal, {}));
    try std.testing.expect(ForegroundSeen.last == dialog);

    // Once it is closed, the frame itself.
    try testAnswer(dialog, "", win32.IDCANCEL);
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .present_terminal, {}));
    try std.testing.expect(ForegroundSeen.last == f.hwnd);
}

test "win32: the key that closes a title prompt reaches its terminal as no release" {
    // Escape closes the prompt on its key-down, inside IsDialogMessageW;
    // the frame then gives its terminal the focus, and the key-up comes
    // there. The core never saw the press, so the release is withheld.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;

    const dialog = try testPrompt(&app, pane, .surface);
    const field = try testField(dialog);

    // Scan code 0x01 (Escape), extended Right arrow 0x4D: the scan slot
    // is lParam bits 16-24.
    const esc_down: win32.LPARAM = 0x0001_0001;
    const esc_up: win32.LPARAM = @bitCast(@as(usize, 0xC001_0001));
    const esc_slot = 0x001;
    const right_down: win32.LPARAM = 0x014D_0001;
    const vk_right: win32.WPARAM = 0x27;
    var msg: win32.MSG = .{
        .hwnd = field,
        .message = win32.WM_KEYDOWN,
        .wParam = vk_right,
        .lParam = right_down,
        .time = 0,
        .pt = .{ .x = 0, .y = 0 },
    };

    // A key the field keeps leaves the terminal's keys alone.
    app.dispatch(&msg);
    try std.testing.expect(window.title_prompt.hwnd == dialog);
    try std.testing.expectEqual(0, pane.ime.swallow_up.count());

    // Escape closes it, as `run` dispatches it.
    msg.wParam = win32.VK_ESCAPE;
    msg.lParam = esc_down;
    app.dispatch(&msg);
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(pane.ime.swallow_up.isSet(esc_slot));

    // Its release, through the terminal's own key handling, is withheld
    // before the core is reached (this pane has none to reach).
    pane.core_state = .live;
    defer pane.core_state = .none;
    _ = win32.SendMessageW(pane.hwnd, win32.WM_KEYUP, win32.VK_ESCAPE, esc_up);
    try std.testing.expect(!pane.ime.swallow_up.isSet(esc_slot));
}

