    try std.testing.expect(!win32.IsWindow(f.hwnd).toBool());
    try std.testing.expectEqual(0, fake.removed_on_thread_len);
    try std.testing.expectEqual(0, fake.removed_groups_len);
    try std.testing.expect(testTakeQuit());

    terminated = true;
    app.terminate();
}

test "win32: a title prompt takes its keys while a teardown waits for a thread" {
    // A teardown's wait pumps messages (`waitForThread`); Escape in the
    // prompt still cancels it there, as in `run`.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;

    const dialog = try testPrompt(&app, pane, .surface);
    try std.testing.expect(win32.PostMessageW(try testField(dialog), win32.WM_KEYDOWN, win32.VK_ESCAPE, 0x0001_0001).toBool());
    const Sleeper = struct {
        fn run() void {
            win32.Sleep(300);
        }
    };
    const thread = try std.Thread.spawn(.{}, Sleeper.run, .{});
    // No core here to tick: as inside a tick, the wait does not.
    app.ticking = true;
    app.waitForThread(thread.getHandle());
    app.ticking = false;
    thread.join();
    try std.testing.expect(window.title_prompt.hwnd == null);
    try std.testing.expect(!win32.IsWindow(dialog).toBool());
}

test "win32: a title prompt's title bar follows its window's" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    app.config.@"window-theme" = .dark;
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    window.applyTheme();
    try std.testing.expect(window.dark_frame);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;

    // Read back from DWM, which answers for the attribute it was given.
    const darkBar = struct {
        fn get(hwnd: win32.HWND) !bool {
            var value: win32.BOOL = .FALSE;
            if (win32.DwmGetWindowAttribute(hwnd, win32.DWMWA_USE_IMMERSIVE_DARK_MODE, &value, @sizeOf(win32.BOOL)) < 0) {
                return error.TestUnexpectedResult;
            }
            return value.toBool();
        }
    }.get;

    const dialog = try testPrompt(&app, pane, .surface);
    try std.testing.expect(try darkBar(dialog));

    // A new configuration re-themes it with the frame.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"window-theme" = .light;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(!window.dark_frame);
    try std.testing.expect(!try darkBar(dialog));
}

test "win32: toggle_window_decorations waits for run and takes the caption off or puts it back" {
    // The client area changes with the caption and the terminals are laid
    // out again, so the toggle is recorded and made by createRequested. As
    // on GTK a window keeps a setting of its own: the first toggle takes
    // the other one, the next goes back to `window-decoration`.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    const target: apprt.Target = .{ .surface = &pane.core_surface };
    const placed = try windowRect(window.hwnd);

    // Recorded, not made; then the caption comes off, the window keeps its
    // rect, and the terminal fills the larger client area.
    try std.testing.expect(try app.performAction(target, .toggle_window_decorations, {}));
    try std.testing.expectEqual(1, app.requests.items.len);
    try std.testing.expect(captioned(window.hwnd));
    const framed = try clientRect(window.hwnd);
    app.createRequested();
    try std.testing.expect(!captioned(window.hwnd));
    try std.testing.expectEqual(placed, try windowRect(window.hwnd));
    try std.testing.expect((try clientRect(window.hwnd)).bottom > framed.bottom);
    try std.testing.expectEqual(try clientRect(window.hwnd), try paneRect(window, pane));

    // Leaving fullscreen keeps it so; and a toggle while it covers the
    // monitor changes nothing there, but shows when it leaves.
    window.toggleFullscreen();
    window.toggleFullscreen();
    try std.testing.expect(!captioned(window.hwnd));
    window.toggleFullscreen();
    window.toggleDecorations();
    try std.testing.expect(!captioned(window.hwnd));
    window.toggleFullscreen();
    try std.testing.expect(captioned(window.hwnd));
    try std.testing.expectEqual(null, window.decoration);

    // With `none` from a new configuration, which `run` applies, the
    // caption comes off; then a toggle puts it back.
    var none: Config = try .default(alloc);
    defer none.deinit();
    none.@"window-decoration" = .none;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &none }));
    try std.testing.expect(captioned(window.hwnd));
    app.createRequested();
    try std.testing.expect(!captioned(window.hwnd));
    try std.testing.expect(try app.performAction(target, .toggle_window_decorations, {}));
    app.createRequested();
    try std.testing.expect(captioned(window.hwnd));

    // A closing terminal drops its own.
    try std.testing.expect(try app.performAction(target, .toggle_window_decorations, {}));
    app.forgetClosing(&pane.core_surface);
    try std.testing.expect(app.requests.items[0] == .dropped);
}

test "win32: a window without decorations is made without its caption" {
    // CreateWindowExW gives a frame its caption whatever style it asks for,
    // and the terminal is created at the frame's client area, so the caption
    // comes off before anything measures it.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    app.config.@"window-decoration" = .none;
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    try std.testing.expect(!captioned(window.hwnd));
    const thick: isize = win32.WS_THICKFRAME;
    try std.testing.expectEqual(thick, win32.GetWindowLongPtrW(window.hwnd, win32.GWL_STYLE) & thick);

    // The client area is the window less its sizing border, the same all
    // round, with no caption's height on top.
    const outer = try windowRect(window.hwnd);
    const client = try clientRect(window.hwnd);
    const border = @divExact((outer.right - outer.left) - client.right, 2);
    try std.testing.expectEqual((outer.bottom - outer.top) - 2 * border, client.bottom);
}

test "win32: a window without decorations maximizes to the work area" {
    // Windows maximizes a frame with no caption over its whole monitor,
    // the taskbar's place included. A framed window of the same class,
    // maximized by Windows, is the reference.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const reference = try testFrame(&app);
    _ = win32.ShowWindow(reference.hwnd, win32.SW_SHOWMAXIMIZED);
    const framed = try windowRect(reference.hwnd);
    const window = try testFrame(&app);
    window.toggleDecorations();
    try std.testing.expect(!captioned(window.hwnd));

    const info = try monitorOf(window.hwnd);
    const work = info.rcWork;
    const clientOnScreen = struct {
        fn f(hwnd: win32.HWND) !win32.RECT {
            const client = try clientRect(hwnd);
            var origin: win32.POINT = .{ .x = 0, .y = 0 };
            if (!win32.ScreenToClient(hwnd, &origin).toBool()) return error.TestUnexpectedResult;
            return .{
                .left = -origin.x,
                .top = -origin.y,
                .right = client.right - origin.x,
                .bottom = client.bottom - origin.y,
            };
        }
    }.f;

    // Maximized, its client area is the work area; and so restored from
    // minimized, as from the taskbar, and back from fullscreen.
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWMAXIMIZED);
    try std.testing.expectEqual(work, try clientOnScreen(window.hwnd));
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWMINNOACTIVE);
    _ = win32.SendMessageW(window.hwnd, win32.WM_SYSCOMMAND, win32.SC_RESTORE, 0);
    try std.testing.expect(win32.IsZoomed(window.hwnd).toBool());
    try std.testing.expectEqual(work, try clientOnScreen(window.hwnd));
    window.toggleFullscreen();
    window.toggleFullscreen();
    try std.testing.expect(win32.IsZoomed(window.hwnd).toBool());
    try std.testing.expectEqual(work, try clientOnScreen(window.hwnd));

    // Given its caption while maximized, it takes the reference's rect;
    // without it again, the work area again.
    window.toggleDecorations();
    try std.testing.expect(captioned(window.hwnd));
    try std.testing.expectEqual(framed, try windowRect(window.hwnd));
    window.toggleDecorations();
    try std.testing.expectEqual(work, try clientOnScreen(window.hwnd));

    // Toggled while it covers the monitor, each way: the same, once it
    // leaves.
    window.toggleFullscreen();
    window.toggleDecorations();
    window.toggleFullscreen();
    try std.testing.expect(captioned(window.hwnd));
    try std.testing.expectEqual(framed, try windowRect(window.hwnd));
    window.toggleFullscreen();
    window.toggleDecorations();
    window.toggleFullscreen();
    try std.testing.expect(!captioned(window.hwnd));
    try std.testing.expectEqual(work, try clientOnScreen(window.hwnd));

    // With no taskbar, or one that hides itself, the work area is the
    // whole monitor, which such a frame's client area covers maximized
    // whether it is kept to the work area or not.
    if (std.meta.eql(work, info.rcMonitor)) return error.SkipZigTest;
}

/// For tests: a stand-in for the taskbar's object, which keeps what a
/// button would show.
const TestTaskbar = struct {
    list: taskbar.ITaskbarList3 = .{ .vtable = &vtable },
    hwnd: ?win32.HWND = null,
    state: taskbar.State = .none,
    /// Out of 100, while the state shows one.
    value: ?u64 = null,
    calls: usize = 0,
    /// Every state set, in order.
    states: [32]taskbar.State = undefined,
    states_len: usize = 0,

    const vtable = vtable: {
        var v: taskbar.ITaskbarList3.VTable = undefined;
        const info = @typeInfo(taskbar.ITaskbarList3.VTable).@"struct";
        for (info.field_names, info.field_types) |name, T| {
            if (T == *const anyopaque) @field(v, name) = @ptrCast(&unused);
        }
        v.Release = release;
        v.HrInit = hrInit;
        v.SetProgressValue = setProgressValue;
        v.SetProgressState = setProgressState;
        break :vtable v;
    };

    fn unused() callconv(.winapi) void {
        unreachable;
    }

    fn release(_: *taskbar.ITaskbarList3) callconv(.winapi) std.os.windows.ULONG {
        return 1;
    }

    fn hrInit(_: *taskbar.ITaskbarList3) callconv(.winapi) win32.HRESULT {
        return 0;
    }

    fn setProgressState(list: *taskbar.ITaskbarList3, hwnd: win32.HWND, state: taskbar.State) callconv(.winapi) win32.HRESULT {
        const self: *TestTaskbar = @fieldParentPtr("list", list);
        self.calls += 1;
        self.hwnd = hwnd;
        self.state = state;
        if (!state.filled()) self.value = null;
        self.states[self.states_len] = state;
        self.states_len += 1;
        return 0;
    }

    fn setProgressValue(list: *taskbar.ITaskbarList3, hwnd: win32.HWND, done: u64, total: u64) callconv(.winapi) win32.HRESULT {
        const self: *TestTaskbar = @fieldParentPtr("list", list);
        self.calls += 1;
        self.hwnd = hwnd;
        self.value = done * 100 / total;
        return 0;
    }
};

test "win32: progress_report shows the focused terminal's progress on the taskbar button" {
    // Only once Explorer says the button exists, as ITaskbarList3 asks, and
    // only the focused terminal's, as Windows Terminal shows its focused
    // pane's.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    // A number of this test's own: Explorer's real one could reach a
    // frame another test shows.
    var fake: TestTaskbar = .{};
    app.taskbar_list = &fake.list;
    app.taskbar_created = win32.WM_APP + 0x100;

    const window = try testFrame(&app);
    const left = try testPane(&app, window);
    const right = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ left, right });
    window.tab().focused = left;
    const report = struct {
        fn f(a: *App, pane: *Surface, value: terminal.osc.Command.ProgressReport) !void {
            try std.testing.expect(try a.performAction(.{ .surface = &pane.core_surface }, .progress_report, value));
        }
    }.f;

    // Kept before the button exists, and shown once it does.
    try report(&app, left, .{ .state = .set, .progress = 40 });
    try std.testing.expectEqual(0, fake.calls);
    _ = win32.SendMessageW(window.hwnd, app.taskbar_created, 0, 0);
    try std.testing.expectEqual(@as(?win32.HWND, window.hwnd), fake.hwnd);
    try std.testing.expectEqual(.normal, fake.state);
    try std.testing.expectEqual(40, fake.value.?);

    // Another terminal's is shown once it has the focus: an error it
    // reported with no value, shown full; then the first one's again.
    const calls = fake.calls;
    try report(&app, right, .{ .state = .@"error" });
    try std.testing.expectEqual(calls, fake.calls);
    _ = Surface.wndProc(right.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expectEqual(.@"error", fake.state);
    try std.testing.expectEqual(100, fake.value.?);
    _ = Surface.wndProc(left.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expectEqual(.normal, fake.state);
    try std.testing.expectEqual(40, fake.value.?);

    // Not for the app.
    try std.testing.expect(!try app.performAction(.app, .progress_report, .{ .state = .set, .progress = 1 }));

    // A report lapses once it is 15 seconds old, not at a WM_TIMER that
    // was queued before it.
    const timer = @import("Surface.zig").progress_timer_id;
    _ = Surface.wndProc(left.hwnd, win32.WM_TIMER, timer, 0);
    try std.testing.expectEqual(.normal, fake.state);
    left.progress_expires = 0;
    _ = Surface.wndProc(left.hwnd, win32.WM_TIMER, timer, 0);
    try std.testing.expectEqual(.none, fake.state);
    try std.testing.expectEqual(taskbar.Progress{}, left.progress);

    // From an error or a pause to the indeterminate state, none comes
    // first, as Windows Terminal sets it, or the button keeps the old bar;
    // also when the focus moves from a paused terminal to such a one.
    try report(&app, left, .{ .state = .@"error", .progress = 50 });
    fake.states_len = 0;
    try report(&app, left, .{ .state = .indeterminate });
    try std.testing.expectEqualSlices(taskbar.State, &.{ .none, .indeterminate }, fake.states[0..fake.states_len]);
    try report(&app, right, .{ .state = .pause, .progress = 30 });
    _ = Surface.wndProc(right.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expectEqual(.paused, fake.state);
    fake.states_len = 0;
    _ = Surface.wndProc(left.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expectEqualSlices(taskbar.State, &.{ .none, .indeterminate }, fake.states[0..fake.states_len]);

    // Each window shows its own focused terminal's, which need not have
    // the keyboard focus: that is in the first window.
    const other = try testFrame(&app);
    const pane = try testPane(&app, other);
    other.tab().tree = try .init(alloc, pane);
    other.tab().focused = pane;
    _ = win32.SendMessageW(other.hwnd, app.taskbar_created, 0, 0);
    try report(&app, pane, .{ .state = .set, .progress = 70 });
    try std.testing.expect(!pane.focused);
    try std.testing.expectEqual(@as(?win32.HWND, other.hwnd), fake.hwnd);
    try std.testing.expectEqual(.normal, fake.state);
    try std.testing.expectEqual(70, fake.value.?);

    // Explorer restarted, and says the first window's button exists again:
    // it shows its progress again.
    fake.hwnd = null;
    fake.state = .none;
    _ = win32.SendMessageW(window.hwnd, app.taskbar_created, 0, 0);
    try std.testing.expectEqual(@as(?win32.HWND, window.hwnd), fake.hwnd);
    try std.testing.expectEqual(.indeterminate, fake.state);

    // With progress-style = false a report removes what was shown.
    try report(&app, left, .{ .state = .pause, .progress = 30 });
    try std.testing.expectEqual(.paused, fake.state);
    try std.testing.expectEqual(30, fake.value.?);
    app.config.@"progress-style" = false;
    try report(&app, left, .{ .state = .set, .progress = 50 });
    try std.testing.expectEqual(.none, fake.state);
}

test "win32: desktop_notification shows a toast for its terminal, which a click goes back to" {
    // As on macOS and GTK: a toast is in its terminal's group, which goes
    // when the terminal gains the focus or closes, and one shown while it
    // has the focus goes after three seconds (DesktopNotifications); a
    // click brings its terminal forward with the focus.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    var fake: toast.TestNotifier = .{};
    app.notifier = fake.notifier();

    const window = try testFrame(&app);
    const left = try testPane(&app, window);
    const right = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ left, right });
    _ = Surface.wndProc(left.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expect(left.setTitle("vim"));
    const notify = struct {
        fn f(a: *App, pane: *Surface, title: [:0]const u8) !void {
            try std.testing.expect(try a.performAction(
                .{ .surface = &pane.core_surface },
                .desktop_notification,
                .{ .title = title, .body = "done" },
            ));
        }
    }.f;

    // For a terminal without the focus: in its group, with no title of
    // its own to show under it, kept.
    try notify(&app, right, "build");
    try std.testing.expectEqual(1, fake.shown_len);
    try std.testing.expectEqual(right.notifications.id, fake.shown[0].group);
    try std.testing.expectEqual(null, fake.shown[0].attribution);
    try std.testing.expectEqual(0, right.notifications.expiring.items.len);

    // For the focused one: its title under it, and removed once three
    // seconds have passed, not at a WM_TIMER that comes before.
    try notify(&app, left, "test");
    try std.testing.expectEqual(left.notifications.id, fake.shown[1].group);
    try std.testing.expectEqualStrings("vim", fake.shown[1].attribution orelse "");
    try std.testing.expect(fake.shown[1].tag != fake.shown[0].tag);
    const timer = @import("desktop_notifications.zig").timer_id;
    _ = Surface.wndProc(left.hwnd, win32.WM_TIMER, timer, 0);
    try std.testing.expectEqual(0, fake.removed_len);
    try std.testing.expectEqual(1, left.notifications.expiring.items.len);
    left.notifications.expiring.items[0].at = 0;
    _ = Surface.wndProc(left.hwnd, win32.WM_TIMER, timer, 0);
    try std.testing.expectEqual(1, fake.removed_len);
    try std.testing.expectEqual([2]u64{ left.notifications.id, fake.shown[1].tag }, fake.removed[0]);

    // Gaining the focus removes a terminal's, once.
    _ = Surface.wndProc(right.hwnd, win32.WM_SETFOCUS, 0, 0);
    _ = Surface.wndProc(right.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expectEqual(1, fake.removed_groups_len);
    try std.testing.expectEqual(right.notifications.id, fake.removed_groups[0]);

    // A click on the first one's, as Windows reports it: the handler posts
    // it to the app's window, whose procedure gives that terminal the focus
    // and brings its frame to the front, shown as a real one is. One for a
    // terminal that is gone changes nothing.
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    const handler = try toast.Activated.create(app.msg_hwnd, WM_GHOSTTY_NOTIFICATION, left.notifications.id);
    _ = handler.vtable.Invoke(handler, null, null);
    _ = handler.vtable.Release(handler);
    var msg: win32.MSG = undefined;
    try std.testing.expect(win32.PeekMessageW(
        &msg,
        app.msg_hwnd,
        WM_GHOSTTY_NOTIFICATION,
        WM_GHOSTTY_NOTIFICATION,
        win32.PM_REMOVE,
    ).toBool());
    _ = App.wndProc(app.msg_hwnd, msg.message, msg.wParam, msg.lParam);
    try std.testing.expectEqual(left, window.tab().focused.?);
    const click = struct {
        fn f(a: *App, group: u64) void {
            const m = toast.groupMessage(group);
            _ = App.wndProc(a.msg_hwnd, WM_GHOSTTY_NOTIFICATION, m[0], m[1]);
        }
    }.f;
    click(&app, 12345);
    try std.testing.expectEqual(left, window.tab().focused.?);

    // Not for a terminal that is closing, nor one in a window closing,
    // nor while the app quits.
    right.closing = true;
    click(&app, right.notifications.id);
    try std.testing.expectEqual(left, window.tab().focused.?);
    right.closing = false;
    window.closing = true;
    click(&app, right.notifications.id);
    try std.testing.expectEqual(left, window.tab().focused.?);
    window.closing = false;
    app.terminating = true;
    click(&app, right.notifications.id);
    try std.testing.expectEqual(left, window.tab().focused.?);
    app.terminating = false;

    // Under a prompt, where the focus may not move, `run` makes it later.
    app.prompt_depth = 1;
    click(&app, right.notifications.id);
    try std.testing.expectEqual(left, window.tab().focused.?);
    app.prompt_depth = 0;
    app.applyPendingClick();
    try std.testing.expectEqual(right, window.tab().focused.?);

    // A zoom that hides the terminal ends first.
    window.tab().tree.zoom(window.tab().tree.locate(right).?);
    window.relayout();
    click(&app, left.notifications.id);
    try std.testing.expectEqual(left, window.tab().focused.?);
    try std.testing.expectEqual(null, window.tab().tree.zoomed);

    // Closing removes a terminal's.
    try notify(&app, left, "again");
    const removed = fake.removed_groups_len;
    const left_id = left.notifications.id;
    try std.testing.expect(left.destroy());
    try std.testing.expectEqual(removed + 1, fake.removed_groups_len);
    try std.testing.expectEqual(left_id, fake.removed_groups[removed]);

    // The app's own: no terminal's group.
    try std.testing.expect(try app.performAction(.app, .desktop_notification, .{ .title = "", .body = "app" }));
    try std.testing.expectEqual(0, fake.shown[fake.shown_len - 1].group);
}

test "win32: command_finished rings the bell or shows a toast for its terminal, as asked" {
    // GTK's rule (`Surface.commandFinishedReply`, tested alone in
    // Surface.zig) through the action: `unfocused` notifies only for a
    // terminal without the focus, a command must take longer than the
    // threshold, and the context menu's "Notify on Next Command Finish",
    // chosen as a user chooses it, asks for the next command alone, which
    // clears it, long enough or not; chosen, it sets the reverse of the
    // check it showed.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    var fake: toast.TestNotifier = .{};
    app.notifier = fake.notifier();
    Window.test_set_focus = &FocusSeen.seen;
    defer Window.test_set_focus = null;
    ContextMenu.test_track = &MenuSeen.track;
    defer ContextMenu.test_track = null;
    SearchBar.test_perform = &PaletteSeen.seen;
    defer SearchBar.test_perform = null;
    Surface.test_mouse_button = &MenuCore.answer;
    defer Surface.test_mouse_button = null;
    MenuSeen.reset();
    defer MenuSeen.reset();
    MenuCore.reset();
    PaletteSeen.reset(null);

    const window = try testFrame(&app);
    testResize(window, 400, 300);
    const left = try testPane(&app, window);
    const right = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ left, right });
    window.relayout();
    _ = Surface.wndProc(left.hwnd, win32.WM_SETFOCUS, 0, 0);

    app.config.@"notify-on-command-finish" = .unfocused;
    app.config.@"notify-on-command-finish-after" = .{ .duration = std.time.ns_per_s };
    app.config.@"notify-on-command-finish-action" = .{ .bell = true, .notify = true };
    const long: Config.Duration = .{ .duration = 2 * std.time.ns_per_s };
    const short: Config.Duration = .{ .duration = std.time.ns_per_s };
    const finish = struct {
        fn f(a: *App, pane: *Surface, code: ?u8, took: Config.Duration) !bool {
            return a.performAction(
                .{ .surface = &pane.core_surface },
                .command_finished,
                .{ .exit_code = code, .duration = took },
            );
        }
    }.f;
    const bells = App.test_bells;

    // Without the focus, long enough: the bell and a toast in the
    // terminal's group.
    try std.testing.expect(try finish(&app, right, 3, long));
    try std.testing.expectEqual(bells + 1, App.test_bells);
    try std.testing.expectEqual(1, fake.shown_len);
    try std.testing.expectEqualStrings("Command Failed", fake.shown[0].title);
    try std.testing.expectEqualStrings("Command took 2s and exited with code 3.", fake.shown[0].body);
    try std.testing.expectEqual(right.notifications.id, fake.shown[0].group);

    // With the focus, or not long enough: nothing, and handled.
    try std.testing.expect(try finish(&app, left, 0, long));
    try std.testing.expect(try finish(&app, right, 0, short));
    try std.testing.expectEqual(bells + 1, App.test_bells);
    try std.testing.expectEqual(1, fake.shown_len);

    // The menu's item, chosen on the focused terminal: set from then on,
    // it asks for its next command, which clears it.
    MenuSeen.choose = "Notify on Next Command Finish";
    testRightClick(left, 20, 30);
    try std.testing.expect(!MenuSeen.chosen_checked);
    try std.testing.expect(left.notify_next_command);
    try std.testing.expect(!right.notify_next_command);
    try std.testing.expectEqualStrings("", PaletteSeen.take());
    try std.testing.expect(try finish(&app, left, 0, long));
    try std.testing.expectEqual(bells + 2, App.test_bells);
    try std.testing.expectEqual(2, fake.shown_len);
    try std.testing.expectEqualStrings("Command Succeeded", fake.shown[1].title);
    try std.testing.expectEqual(left.notifications.id, fake.shown[1].group);
    try std.testing.expect(!left.notify_next_command);
    try std.testing.expect(try finish(&app, left, 0, long));
    try std.testing.expectEqual(2, fake.shown_len);

    // Spent by a command too quick to notify; and chosen again, shown
    // checked, it is taken back.
    testRightClick(left, 20, 30);
    try std.testing.expect(left.notify_next_command);
    try std.testing.expect(try finish(&app, left, 0, short));
    try std.testing.expect(!left.notify_next_command);
    try std.testing.expect(try finish(&app, left, 0, long));
    testRightClick(left, 20, 30);
    testRightClick(left, 20, 30);
    try std.testing.expect(MenuSeen.chosen_checked);
    try std.testing.expect(!left.notify_next_command);
    try std.testing.expect(try finish(&app, left, 0, long));
    try std.testing.expectEqual(bells + 2, App.test_bells);
    try std.testing.expectEqual(2, fake.shown_len);

    // The bell alone, and a toast alone, of which one that cannot be shown
    // is reported. No exit code: "Command Finished".
    app.config.@"notify-on-command-finish-action" = .{ .bell = true, .notify = false };
    try std.testing.expect(try finish(&app, right, 1, long));
    try std.testing.expectEqual(bells + 3, App.test_bells);
    try std.testing.expectEqual(2, fake.shown_len);
    app.config.@"notify-on-command-finish-action" = .{ .bell = false, .notify = true };
    try std.testing.expect(try finish(&app, right, null, long));
    try std.testing.expectEqual(bells + 3, App.test_bells);
    try std.testing.expectEqualStrings("Command Finished", fake.shown[2].title);
    try std.testing.expectEqualStrings("Command took 2s.", fake.shown[2].body);
    fake.fail = true;
    try std.testing.expect(!try finish(&app, right, 0, long));
    try std.testing.expectEqual(3, fake.shown_len);

    // The app runs no command.
    try std.testing.expect(!try app.performAction(.app, .command_finished, .{ .exit_code = 0, .duration = long }));

    // BEL rings the same bell.
    try std.testing.expect(try app.performAction(.{ .surface = &right.core_surface }, .ring_bell, {}));
    try std.testing.expectEqual(bells + 4, App.test_bells);

    // Set, then a command finishes while the menu is open, as its loop
    // ticks the app, and clears it: the item the menu shows checked,
    // chosen to uncheck it, leaves it clear rather than setting it again.
    testRightClick(left, 20, 30);
    try std.testing.expect(left.notify_next_command);
    const Meanwhile = struct {
        var app_: *App = undefined;
        var pane: *Surface = undefined;
        fn end() void {
            const done = app_.performAction(
                .{ .surface = &pane.core_surface },
                .command_finished,
                .{ .exit_code = 0, .duration = .{ .duration = 2 * std.time.ns_per_s } },
            ) catch @panic("command_finished failed");
            if (!done) @panic("command_finished not handled");
        }
    };
    Meanwhile.app_ = &app;
    Meanwhile.pane = left;
    MenuSeen.during = &Meanwhile.end;
    testRightClick(left, 20, 30);
    MenuSeen.during = null;
    try std.testing.expectEqual(4, fake.shown_len);
    try std.testing.expectEqual(left.notifications.id, fake.shown[3].group);
    try std.testing.expect(MenuSeen.chosen_checked);
    try std.testing.expect(!left.notify_next_command);
}

/// For tests: the core's `ring_bell` on `surface`, as BEL performs it.
fn testBell(app: *App, surface: *Surface) !bool {
    return app.performAction(.{ .surface = &surface.core_surface }, .ring_bell, {});
}

test "win32: a bell does what bell-features asks, each time it rings" {
    // GTK's `ring-bell` actions, for every bell, whether the terminal has
    // the focus or not: `system` beeps; `attention` flashes the window's
    // taskbar button, unless the window or a window it owns is in the
    // foreground, as GTK sets the urgency hint unless it is active;
    // `audio` plays `bell-audio-path`, required or optional, at
    // `bell-audio-volume` clamped to 0 to 1. The defaults flash alone. The
    // core rings only a terminal's.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    const Foreground = struct {
        var hwnd: ?win32.HWND = null;
        fn get() ?win32.HWND {
            return hwnd;
        }
    };
    Foreground.hwnd = null;
    App.test_get_foreground = &Foreground.get;
    defer App.test_get_foreground = null;
    App.test_flash = null;

    var tmp_dir = std.testing.tmpDir(.{});
    defer tmp_dir.cleanup();
    try tmp_dir.dir.writeFile(std.testing.io, .{ .sub_path = "bell.wav", .data = "" });
    try tmp_dir.dir.writeFile(std.testing.io, .{ .sub_path = "quiet.mp3", .data = "" });
    const dir = try tmp_dir.dir.realPathFileAlloc(std.testing.io, ".", alloc);
    defer alloc.free(dir);
    const loud_path = try std.fs.path.joinZ(alloc, &.{ dir, "bell.wav" });
    defer alloc.free(loud_path);
    const quiet_path = try std.fs.path.joinZ(alloc, &.{ dir, "quiet.mp3" });
    defer alloc.free(quiet_path);

    const window = try testFrame(&app);
    testResize(window, 400, 300);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    window.tab().focused = pane;
    window.relayout();
    const bells = App.test_bells;
    const beeps = App.test_beeps;
    const flashes = App.test_flashes;
    const played = media.test_record.plays;

    // The defaults: a flash each time, no beep, no sound. The flash
    // lasts until the window comes to the foreground.
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(bells + 2, App.test_bells);
    try std.testing.expectEqual(beeps, App.test_beeps);
    try std.testing.expectEqual(flashes + 2, App.test_flashes);
    try std.testing.expectEqual(played, media.test_record.plays);
    const flash = App.test_flash orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@sizeOf(win32.FLASHWINFO), flash.cbSize);
    try std.testing.expect(flash.hwnd == window.hwnd);
    try std.testing.expectEqual(win32.FLASHW_TRAY | win32.FLASHW_TIMERNOFG, flash.dwFlags);
    try std.testing.expectEqual(0, flash.uCount);

    // In the foreground, or a window it owns, as its prompts are: no
    // flash; another window there, or one another window owns: a flash.
    Foreground.hwnd = window.hwnd;
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(flashes + 2, App.test_flashes);
    const owned = win32.CreateWindowExW(0, L("STATIC"), L(""), win32.WS_POPUP, 0, 0, 10, 10, window.hwnd, null, app.hinstance, null) orelse
        return error.TestUnexpectedResult;
    defer _ = win32.DestroyWindow(owned);
    Foreground.hwnd = owned;
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(flashes + 2, App.test_flashes);
    Foreground.hwnd = app.msg_hwnd;
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(flashes + 3, App.test_flashes);
    const other = try testFrame(&app);
    const theirs = win32.CreateWindowExW(0, L("STATIC"), L(""), win32.WS_POPUP, 0, 0, 10, 10, other.hwnd, null, app.hinstance, null) orelse
        return error.TestUnexpectedResult;
    defer _ = win32.DestroyWindow(theirs);
    Foreground.hwnd = theirs;
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(flashes + 4, App.test_flashes);

    // A beep and a required sound, loud past 1, without attention.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"bell-features" = .{ .system = true, .audio = true, .attention = false };
    changed.@"bell-audio-path" = .{ .required = loud_path };
    changed.@"bell-audio-volume" = 1.7;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(beeps + 1, App.test_beeps);
    try std.testing.expectEqual(flashes + 4, App.test_flashes);
    try std.testing.expectEqual(played + 1, media.test_record.plays);
    try std.testing.expectEqualStrings(loud_path, media.test_record.lastPath());
    try std.testing.expect(media.test_record.required);
    try std.testing.expectEqual(1.0, media.test_record.volume);

    // An optional one, quiet past 0.
    changed.@"bell-audio-path" = .{ .optional = quiet_path };
    changed.@"bell-audio-volume" = -0.5;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(played + 2, media.test_record.plays);
    try std.testing.expectEqualStrings(quiet_path, media.test_record.lastPath());
    try std.testing.expect(!media.test_record.required);
    try std.testing.expectEqual(0.0, media.test_record.volume);

    // No path: no sound, the beep still.
    changed.@"bell-audio-path" = null;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(try testBell(&app, pane));
    try std.testing.expectEqual(played + 2, media.test_record.plays);
    try std.testing.expectEqual(beeps + 3, App.test_beeps);

    // The app's is not one the core sends.
    try std.testing.expect(!try app.performAction(.app, .ring_bell, {}));
    try std.testing.expectEqual(bells + 9, App.test_bells);
}

test "win32: a bell rings in a terminal without the focus until it has it or a button is pressed over it" {
    // GTK's `setBellRinging`: a bell, or a finished command's, sets a
    // terminal ringing only if it does not have the focus; the focus or
    // any button pressed over it stops it. While its tab's focused
    // terminal rings, with `bell-features` `title`, the tab's label and,
    // while it is shown, the window's caption have "🔔 " before its title,
    // the tab's own too, as GTK computes its tab's title.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    Window.test_set_focus = &FocusSeen.seen;
    defer Window.test_set_focus = null;

    const window = try testFrame(&app);
    testResize(window, 400, 300);
    const left = try testPane(&app, window);
    const right = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ left, right });
    window.tab().focused = left;
    window.relayout();
    _ = Surface.wndProc(left.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expect(left.setTitle("vim"));
    try std.testing.expect(right.setTitle("logs"));
    var buf: [64]u8 = undefined;
    const bells = App.test_bells;
    const shownIs = struct {
        fn f(w: *const Window, t: *const Tab, want: []const u8) !void {
            const a = std.testing.allocator;
            const title = try w.shownTitle(a, t);
            defer a.free(title);
            var utf8: [64]u8 = undefined;
            const n = try std.unicode.utf16LeToUtf8(&utf8, title);
            try std.testing.expectEqualStrings(want, utf8[0..n]);
        }
    }.f;

    // With the focus: the bell's actions alone.
    try std.testing.expect(try testBell(&app, left));
    try std.testing.expectEqual(bells + 1, App.test_bells);
    try std.testing.expect(!left.bell_ringing);

    // Without: it rings, in no title while its tab's focused terminal is
    // the other; the focus stops it.
    try std.testing.expect(try testBell(&app, right));
    try std.testing.expectEqual(bells + 2, App.test_bells);
    try std.testing.expect(right.bell_ringing);
    try std.testing.expect(!left.bell_ringing);
    try std.testing.expectEqualStrings("vim", try windowText(window.hwnd, &buf));
    try shownIs(window, window.tab(), "vim");
    _ = Surface.wndProc(left.hwnd, win32.WM_KILLFOCUS, 0, 0);
    _ = Surface.wndProc(right.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expect(!right.bell_ringing);
    try std.testing.expectEqualStrings("logs", try windowText(window.hwnd, &buf));

    // The frame lost the focus: its focused terminal rings, in the caption
    // and the label, again and again; the tab's own title, after it.
    _ = Surface.wndProc(right.hwnd, win32.WM_KILLFOCUS, 0, 0);
    try std.testing.expect(try testBell(&app, right));
    try std.testing.expect(right.bell_ringing);
    try std.testing.expectEqualStrings("🔔 logs", try windowText(window.hwnd, &buf));
    try shownIs(window, window.tab(), "🔔 logs");
    try std.testing.expect(try testBell(&app, right));
    try std.testing.expectEqualStrings("🔔 logs", try windowText(window.hwnd, &buf));
    try std.testing.expect(try app.performAction(.{ .surface = &right.core_surface }, .set_tab_title, .{ .title = "mine" }));
    try std.testing.expectEqualStrings("🔔 mine", try windowText(window.hwnd, &buf));
    try std.testing.expect(try app.performAction(.{ .surface = &right.core_surface }, .set_tab_title, .{ .title = "" }));
    try std.testing.expectEqualStrings("🔔 logs", try windowText(window.hwnd, &buf));

    // A release does not stop it; any press does.
    _ = Surface.wndProc(right.hwnd, win32.WM_LBUTTONUP, 0, testPoint(20, 30));
    try std.testing.expect(right.bell_ringing);
    _ = Surface.wndProc(right.hwnd, win32.WM_MBUTTONDOWN, 0, testPoint(20, 30));
    _ = Surface.wndProc(right.hwnd, win32.WM_MBUTTONUP, 0, testPoint(20, 30));
    try std.testing.expect(!right.bell_ringing);
    try std.testing.expectEqualStrings("logs", try windowText(window.hwnd, &buf));
    try std.testing.expect(try testBell(&app, right));
    try std.testing.expect(right.bell_ringing);
    _ = Surface.wndProc(right.hwnd, win32.WM_LBUTTONDOWN, 0, testPoint(20, 30));
    _ = Surface.wndProc(right.hwnd, win32.WM_LBUTTONUP, 0, testPoint(20, 30));
    try std.testing.expect(!right.bell_ringing);

    // A finished command's bell rings too.
    app.config.@"notify-on-command-finish" = .unfocused;
    app.config.@"notify-on-command-finish-after" = .{ .duration = std.time.ns_per_s };
    app.config.@"notify-on-command-finish-action" = .{ .bell = true, .notify = false };
    try std.testing.expect(try app.performAction(
        .{ .surface = &right.core_surface },
        .command_finished,
        .{ .exit_code = 0, .duration = .{ .duration = 2 * std.time.ns_per_s } },
    ));
    try std.testing.expect(right.bell_ringing);
    try std.testing.expectEqualStrings("🔔 logs", try windowText(window.hwnd, &buf));

    // Its tab hidden: in its label, not the caption, until shown again.
    const other = try testTab(&app, window);
    window.selectTab(1);
    try std.testing.expect(window.tab().focused == other);
    try std.testing.expectEqualStrings("Ghostty", try windowText(window.hwnd, &buf));
    try shownIs(window, window.tabOf(right).?, "🔔 logs");
    window.selectTab(0);
    try std.testing.expectEqualStrings("🔔 logs", try windowText(window.hwnd, &buf));

    // A configuration without `title`: in neither, while it still rings;
    // with it again, back.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"bell-features".title = false;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(right.bell_ringing);
    try std.testing.expectEqualStrings("logs", try windowText(window.hwnd, &buf));
    try shownIs(window, window.tab(), "logs");
    changed.@"bell-features".title = true;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expectEqualStrings("🔔 logs", try windowText(window.hwnd, &buf));

    // Its label is drawn again as it starts ringing.
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    window.relayout();
    const bar = window.bar.hwnd orelse return error.TestUnexpectedResult;
    try std.testing.expect(shown(bar));
    _ = Surface.wndProc(right.hwnd, win32.WM_SETFOCUS, 0, 0);
    _ = Surface.wndProc(right.hwnd, win32.WM_KILLFOCUS, 0, 0);
    try std.testing.expect(!right.bell_ringing);
    _ = win32.UpdateWindow(bar);
    try std.testing.expect(!win32.GetUpdateRect(bar, null, .FALSE).toBool());
    try std.testing.expect(try testBell(&app, right));
    try std.testing.expect(right.bell_ringing);
    try std.testing.expect(win32.GetUpdateRect(bar, null, .FALSE).toBool());
}

/// For tests: `surface`'s bell border shows in `window` over all of its
/// terminal, shaped to a line `line` pixels wide along its edges, and
/// passive.
fn expectBorderAt(window: *const Window, surface: *const Surface, line: i32) !void {
    const hwnd = surface.overlays.bell_border.hwnd orelse return error.TestUnexpectedResult;
    try std.testing.expect(shown(hwnd));
    try std.testing.expect(win32.GetAncestor(hwnd, win32.GA_PARENT) == window.hwnd);
    const pane = try paneClient(window, surface);
    try std.testing.expectEqual(pane, try childRect(window, hwnd));
    const w = pane.right - pane.left;
    const h = pane.bottom - pane.top;
    const rgn = win32.CreateRectRgn(0, 0, 0, 0) orelse return error.TestUnexpectedResult;
    defer _ = win32.DeleteObject(rgn);
    try std.testing.expect(win32.GetWindowRgn(hwnd, rgn) != win32.RGN_ERROR);
    const in = struct {
        fn f(r: win32.HRGN, x: i32, y: i32) bool {
            return win32.PtInRegion(r, x, y).toBool();
        }
    }.f;
    // Each edge's last pixel of line, and the first inside it.
    const mx = @divTrunc(w, 2);
    const my = @divTrunc(h, 2);
    try std.testing.expect(in(rgn, 0, 0) and in(rgn, w - 1, h - 1));
    try std.testing.expect(in(rgn, line - 1, my) and !in(rgn, line, my));
    try std.testing.expect(in(rgn, w - line, my) and !in(rgn, w - line - 1, my));
    try std.testing.expect(in(rgn, mx, line - 1) and !in(rgn, mx, line));
    try std.testing.expect(in(rgn, mx, h - line) and !in(rgn, mx, h - line - 1));
    try std.testing.expectEqual(win32.HTTRANSPARENT, win32.SendMessageW(hwnd, win32.WM_NCHITTEST, 0, 0));
}

test "win32: the bell border shows around a ringing terminal, under its other overlays, and follows it" {
    // GTK's and macOS's border, with `bell-features` `border`, while the
    // terminal rings: over all of it, macOS's 3 points wide, in its amber
    // over the terminal's background; the window shaped to the line, so
    // the terminal shows inside it. It is just above the read-only badge,
    // under the banner and the rest, as GTK stacks it; a resize, a new
    // scale, a zoom, a hidden tab and a move to a new window take it with
    // the terminal; a configuration turns it on or off while it rings.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    Window.test_set_focus = &FocusSeen.seen;
    defer Window.test_set_focus = null;
    Window.test_get_focus = &FocusSeen.current;
    defer Window.test_get_focus = null;
    FocusSeen.last = null;

    const window = try testFrame(&app);
    testResize(window, 900, 500);
    const a = try testPane(&app, window);
    const b = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ a, b });
    window.tab().focused = a;
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    window.relayout();

    // Off by default: a ring makes none.
    try std.testing.expect(try testBell(&app, a));
    try std.testing.expect(a.bell_ringing);
    try std.testing.expect(a.overlays.bell_border.hwnd == null);

    // A configuration with it, while it rings: shown, just above the
    // terminal, in amber over the background; not b's.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"bell-features".border = true;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try expectBorderAt(window, a, 3);
    const hwnd = a.overlays.bell_border.hwnd orelse return error.TestUnexpectedResult;
    try std.testing.expect(win32.GetWindow(a.hwnd, win32.GW_HWNDPREV) == hwnd);
    try std.testing.expect(b.overlays.bell_border.hwnd == null);
    {
        const printed = try Printed.of(hwnd);
        defer printed.deinit();
        try std.testing.expectEqual(win32.rgb(148, 124, 26), printed.at(0, 0));
        try std.testing.expectEqual(win32.rgb(148, 124, 26), printed.at(printed.width - 1, printed.height - 1));
    }

    // A new background: drawn again, over it. Dark still, so that the
    // frame's title bar, which repaints the overlays when it changes
    // (`Window.applyTheme`), stays as it was.
    _ = win32.UpdateWindow(hwnd);
    try std.testing.expect(!win32.GetUpdateRect(hwnd, null, .FALSE).toBool());
    changed.background = .{ .r = 0, .g = 0, .b = 0 };
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(win32.GetUpdateRect(hwnd, null, .FALSE).toBool());
    {
        const printed = try Printed.of(hwnd);
        defer printed.deinit();
        try std.testing.expectEqual(win32.rgb(128, 102, 0), printed.at(0, 0));
    }

    // Over the badge, under the banner, the preview and the key state,
    // and the search bar.
    try std.testing.expect(try testReadOnly(&app, a, .on));
    try std.testing.expect(try testChildExited(&app, a, 1));
    const url = "https://example.com/some/long/path/that/goes/on/past/the/middle/of/the/terminal";
    try std.testing.expect(try testLink(&app, a, url));
    try std.testing.expect(try testKeyTable(&app, a, .{ .activate = "nav" }));
    try expectBorderAt(window, a, 3);
    const badge = a.overlays.readonly.hwnd.?;
    try std.testing.expect(win32.GetWindow(a.hwnd, win32.GW_HWNDPREV) == badge);
    try std.testing.expect(win32.GetWindow(badge, win32.GW_HWNDPREV) == hwnd);
    try std.testing.expect(win32.GetWindow(hwnd, win32.GW_HWNDPREV) == a.overlays.child_exited.hwnd.?);
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .start_search, .{ .needle = "" }));
    app.applyPendingFocus();
    try std.testing.expect(above(window.hwnd, a.search_bar.hwnd.?, hwnd));
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .end_search, {}));
    app.applyPendingFocus();
    try std.testing.expect(try testLink(&app, a, ""));
    try std.testing.expect(try testKeyTable(&app, a, .deactivate));
    try std.testing.expect(try testReadOnly(&app, a, .off));

    // Resized, and zoomed: around all of the terminal still.
    testResize(window, 1000, 600);
    try expectBorderAt(window, a, 3);
    window.toggleZoom(a);
    try expectBorderAt(window, a, 3);
    try std.testing.expectEqual(try clientRect(window.hwnd), try paneRect(window, a));
    window.toggleZoom(a);
    try expectBorderAt(window, a, 3);
    window.toggleZoom(b);
    try std.testing.expect(!shown(hwnd));
    window.toggleZoom(b);
    try expectBorderAt(window, a, 3);

    // The other tab shown: hidden with the terminal; back, shown.
    _ = try testTab(&app, window);
    window.relayout();
    window.selectTab(1);
    try std.testing.expect(!shown(hwnd));
    window.selectTab(0);
    try expectBorderAt(window, a, 3);

    // The focus stops it, and hides it; a bell again shows it.
    _ = Surface.wndProc(a.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expect(!a.bell_ringing);
    try std.testing.expect(!shown(hwnd));
    _ = Surface.wndProc(a.hwnd, win32.WM_KILLFOCUS, 0, 0);
    try std.testing.expect(try testBell(&app, a));
    try expectBorderAt(window, a, 3);
    try std.testing.expect(a.overlays.bell_border.hwnd == hwnd);

    // Moved with its tab to a new window, and at twice the scale there.
    try std.testing.expect(try app.performAction(.{ .surface = &a.core_surface }, .move_tab_to_new_window, {}));
    app.createRequested();
    const moved = a.window;
    try std.testing.expect(moved != window);
    try std.testing.expect(a.overlays.bell_border.hwnd == hwnd);
    try expectBorderAt(moved, a, 3);
    const Dpi = struct {
        fn of(_: win32.HWND) callconv(.winapi) win32.UINT {
            return 192;
        }
    };
    app.get_dpi_for_window = &Dpi.of;
    var suggested = try windowRect(moved.hwnd);
    _ = win32.SendMessageW(moved.hwnd, win32.WM_DPICHANGED, 192 << 16 | 192, @bitCast(@intFromPtr(&suggested)));
    try expectBorderAt(moved, a, 6);

    // A configuration without it: hidden while it rings.
    changed.@"bell-features".border = false;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expect(a.bell_ringing);
    try std.testing.expect(!shown(hwnd));

    // It goes with its terminal.
    try std.testing.expect(a.destroy());
    try std.testing.expect(!win32.IsWindow(hwnd).toBool());
}

test "win32: a bell border whose window cannot be made, or was destroyed, or shaped, is made the next time it shows" {
    // CreateWindowExW fails when the process has used up its window
    // handles: the terminal rings without it, and the next bell after it
    // stopped makes it. One destroyed, as a frame that cannot take it
    // destroys it (`Overlays.reparent`), is made again, and shaped again.
    // One whose region cannot be made, as GDI's objects run out, is not
    // shown, as it would cover the terminal, until it can be.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    Window.test_set_focus = &FocusSeen.seen;
    defer Window.test_set_focus = null;

    const window = try testFrame(&app);
    testResize(window, 900, 500);
    const a = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{a});
    window.tab().focused = a;
    window.relayout();
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"bell-features".border = true;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));

    const NoWindow = struct {
        var asked: usize = 0;
        var class: []const u8 = "";
        fn make(c: []const u8) ?win32.HWND {
            asked += 1;
            class = c;
            return null;
        }
    };
    NoWindow.asked = 0;
    Overlays.test_make = &NoWindow.make;
    defer Overlays.test_make = null;

    try std.testing.expect(try testBell(&app, a));
    try std.testing.expect(a.bell_ringing);
    try std.testing.expect(a.overlays.bell_border.hwnd == null);
    try std.testing.expectEqual(1, NoWindow.asked);
    try std.testing.expectEqualStrings(BellBorder.class_name, NoWindow.class);
    _ = Surface.wndProc(a.hwnd, win32.WM_SETFOCUS, 0, 0);
    try std.testing.expectEqual(1, NoWindow.asked);

    Overlays.test_make = null;
    _ = Surface.wndProc(a.hwnd, win32.WM_KILLFOCUS, 0, 0);
    try std.testing.expect(try testBell(&app, a));
    try expectBorderAt(window, a, 3);

    _ = win32.DestroyWindow(a.overlays.bell_border.hwnd orelse return error.TestUnexpectedResult);
    try std.testing.expect(a.overlays.bell_border.hwnd == null);
    _ = Surface.wndProc(a.hwnd, win32.WM_SETFOCUS, 0, 0);
    _ = Surface.wndProc(a.hwnd, win32.WM_KILLFOCUS, 0, 0);
    try std.testing.expect(try testBell(&app, a));
    try expectBorderAt(window, a, 3);

    const NoRegion = struct {
        fn create(_: i32, _: i32, _: i32, _: i32) ?win32.HRGN {
            return null;
        }
    };
    BellBorder.test_create_rgn = &NoRegion.create;
    defer BellBorder.test_create_rgn = null;
    testResize(window, 800, 400);
    const hwnd = a.overlays.bell_border.hwnd orelse return error.TestUnexpectedResult;
    try std.testing.expect(a.bell_ringing);
    try std.testing.expect(!shown(hwnd));
    BellBorder.test_create_rgn = null;
    testResize(window, 900, 500);
    try expectBorderAt(window, a, 3);
}

test "win32: float_window keeps a window on top, or puts it back" {
    // On a desktop of its own (testOnOwnDesktop): what it reads, whether
    // the window is topmost, any program on its desktop can change.
    try testOnOwnDesktop(testFloatWindow, .{});
}

/// The float_window test, run by its test on a desktop of its own.
fn testFloatWindow() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const pane = try testPane(&app, window);
    window.tab().tree = try .init(alloc, pane);
    const target: apprt.Target = .{ .surface = &pane.core_surface };

    // It is made at once, inside the core's key callback, so neither the
    // window, shown as one that floats is, nor its terminal may hear of a
    // size or a focus change: only its place in the z-order changes.
    _ = win32.ShowWindow(window.hwnd, win32.SW_SHOWNOACTIVATE);
    const Seen = struct {
        var count: usize = 0;
        fn proc(code: c_int, wparam: win32.WPARAM, lparam: win32.LPARAM) callconv(.winapi) win32.LRESULT {
            if (code >= 0) {
                const sent: *const win32.CWPSTRUCT = @ptrFromInt(@as(usize, @bitCast(lparam)));
                switch (sent.message) {
                    win32.WM_SIZE, win32.WM_ACTIVATE, win32.WM_SETFOCUS, win32.WM_KILLFOCUS => count += 1,
                    else => {},
                }
            }
            return win32.CallNextHookEx(null, code, wparam, lparam);
        }
    };
    const hook = win32.SetWindowsHookExW(
        win32.WH_CALLWNDPROC,
        Seen.proc,
        null,
        std.os.windows.GetCurrentThreadId(),
    ) orelse return error.TestUnexpectedResult;
    defer _ = win32.UnhookWindowsHookEx(hook);

    try std.testing.expect(!window.isFloating());
    for ([_]struct { apprt.action.FloatWindow, bool }{
        .{ .toggle, true },
        .{ .toggle, false },
        .{ .on, true },
        .{ .on, true },
        .{ .off, false },
        .{ .off, false },
    }) |c| {
        try std.testing.expect(try app.performAction(target, .float_window, c[0]));
        try std.testing.expectEqual(c[1], window.isFloating());
    }
    try std.testing.expectEqual(0, Seen.count);
    // The hook does see a change of size.
    _ = win32.SetWindowPos(window.hwnd, null, 0, 0, 300, 150, win32.SWP_NOMOVE | win32.SWP_NOZORDER | win32.SWP_NOACTIVATE);
    try std.testing.expect(Seen.count > 0);

    // Covering the monitor and coming back keeps it floating.
    try std.testing.expect(try app.performAction(target, .float_window, .on));
    window.tab().focused = pane;
    window.toggleFullscreen();
    try std.testing.expect(window.isFloating());
    window.toggleFullscreen();
    try std.testing.expect(window.isFloating());

    // A window that does not float as asked although SetWindowPos succeeds
    // is not floated: a procedure that takes the change of z-order out of
    // WM_WINDOWPOSCHANGING stands here for whatever leaves it where it was.
    try std.testing.expect(try app.performAction(target, .float_window, .off));
    const Refuse = struct {
        var proc: ?win32.WNDPROC = null;
        fn wndProc(
            hwnd: win32.HWND,
            msg: win32.UINT,
            wparam: win32.WPARAM,
            lparam: win32.LPARAM,
        ) callconv(.winapi) win32.LRESULT {
            if (msg == win32.WM_WINDOWPOSCHANGING) {
                const pos: *win32.WINDOWPOS = @ptrFromInt(@as(usize, @bitCast(lparam)));
                pos.flags |= win32.SWP_NOZORDER;
            }
            return win32.CallWindowProcW(proc.?, hwnd, msg, wparam, lparam);
        }
    };
    const old = win32.SetWindowLongPtrW(window.hwnd, win32.GWLP_WNDPROC, @bitCast(@intFromPtr(&Refuse.wndProc)));
    Refuse.proc = @ptrFromInt(@as(usize, @bitCast(old)));
    defer _ = win32.SetWindowLongPtrW(window.hwnd, win32.GWLP_WNDPROC, old);
    try std.testing.expect(!try app.performAction(target, .float_window, .on));
}

/// For tests: the quick terminal's terminal, made as `Window.create`
/// makes one (`Window.test_create_pane`), or an error while `fail`, with
/// the area it would be made over (`area`); and what the quick terminal
/// does with it: the window `Window.present` brings forward
/// (`Window.test_foreground`), and what a quick terminal's terminal was
/// last told of whether it shows (`Surface.test_occlusion`); not another
/// window's, which a reloaded configuration lays out too. Its animation's
/// clock (`Window.test_quick_now`) stands still but for `tick`.
const TestQuick = struct {
    var fail: bool = false;
    var area: ?win32.RECT = null;
    var front: ?win32.HWND = null;
    var told: ?*Surface = null;
    var shows: bool = false;
    /// What GetForegroundWindow answers (`App.test_get_foreground`).
    var in_front: ?win32.HWND = null;
    /// Whether `watch` showed when a window was last given the foreground.
    var watch: ?win32.HWND = null;
    var watch_shown: bool = false;

    fn start() void {
        fail = false;
        area = null;
        front = null;
        told = null;
        in_front = null;
        watch = null;
        watch_topmost = null;
        answer = win32.IDCANCEL;
        Window.test_create_pane = &create;
        Window.test_foreground = &foreground;
        Surface.test_occlusion = &occlusion;
        App.test_get_foreground = &foregroundNow;
        Window.test_quick_now = 0;
        Window.test_quick_timer_fails = false;
        Window.test_quick_rgn = null;
    }

    fn stop() void {
        Window.test_create_pane = null;
        Window.test_foreground = null;
        Surface.test_occlusion = null;
        App.test_get_foreground = null;
        Window.test_quick_now = null;
        Window.test_quick_timer_fails = false;
        Window.test_quick_rgn = null;
    }

    /// The clock moved on by `ns` and the quick terminal's animation timer
    /// fired (WM_TIMER).
    fn tick(quick: *const Window, ns: u64) void {
        Window.test_quick_now = Window.test_quick_now.? + ns;
        _ = win32.SendMessageW(quick.hwnd, win32.WM_TIMER, Window.quick_timer_id, 0);
    }

    /// The quick terminal's animation, if one runs, carried to its end: an
    /// hour on, longer than any test's.
    fn settle(quick: *const Window) void {
        tick(quick, std.time.ns_per_hour);
    }

    /// The part of `quick` its window region lets show, in its window's
    /// coordinates, all zero if none; null with no region, all of it.
    fn region(quick: *const Window) !?win32.RECT {
        const rgn = win32.CreateRectRgn(0, 0, 0, 0) orelse return error.TestUnexpectedResult;
        defer _ = win32.DeleteObject(rgn);
        if (win32.GetWindowRgn(quick.hwnd, rgn) == win32.RGN_ERROR) return null;
        var box: win32.RECT = undefined;
        if (win32.GetRgnBox(rgn, &box) == win32.RGN_ERROR) return error.TestUnexpectedResult;
        return box;
    }

    /// `quick`'s alpha as a layered window, null if it is not one.
    fn alpha(quick: *const Window) !?u8 {
        if (!hasStyle(quick.hwnd, win32.GWL_EXSTYLE, win32.WS_EX_LAYERED)) return null;
        var value: u8 = 0;
        var flags: win32.DWORD = 0;
        if (!win32.GetLayeredWindowAttributes(quick.hwnd, null, &value, &flags).toBool()) return error.TestUnexpectedResult;
        try std.testing.expectEqual(win32.LWA_ALPHA, flags);
        return value;
    }

    /// `app`'s configuration reloaded as `changed`, as a reload performs
    /// it, then as `run` carries it out.
    fn reconfigure(app: *App, changed: *const Config) !void {
        try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = changed }));
        app.createRequested();
    }

    /// In place of CreateRectRgn (`Window.test_quick_rgn`): no region, as
    /// when GDI has run out of them.
    fn noRgn(left: i32, top: i32, right: i32, bottom: i32) ?win32.HRGN {
        _ = .{ left, top, right, bottom };
        return null;
    }

    fn foregroundNow() ?win32.HWND {
        return in_front;
    }

    /// `foregroundNow`, but none once that window is hidden, as Windows
    /// gives the foreground to another window as it hides the one in front.
    fn foregroundShown() ?win32.HWND {
        const hwnd = in_front orelse return null;
        return if (win32.IsWindowVisible(hwnd).toBool()) hwnd else null;
    }

    fn create(w: *Window, _: Surface.Options) anyerror!*Surface {
        if (fail) return error.TestQuickTerminal;
        area = w.layoutArea();
        const pane = try testPane(w.app, w);
        // `App.newWindow` makes it the app's.
        _ = w.app.surfaces.pop();
        return pane;
    }

    fn foreground(hwnd: win32.HWND) void {
        front = hwnd;
        if (watch) |w| watch_shown = win32.IsWindowVisible(w).toBool();
    }

    /// Another program's window, as the quick terminal sees one: shown,
    /// and neither one of the app's nor owned by one.
    fn foreign() !win32.HWND {
        const hwnd = win32.CreateWindowExW(0, L("STATIC"), null, win32.WS_POPUP, 0, 0, 10, 10, null, null, null, null) orelse
            return error.TestUnexpectedResult;
        _ = win32.ShowWindow(hwnd, win32.SW_SHOWNOACTIVATE);
        return hwnd;
    }

    /// A hidden window `window` owns, as it owns its prompts.
    fn owned(window: *const Window) !win32.HWND {
        return win32.CreateWindowExW(0, L("STATIC"), null, win32.WS_POPUP, 0, 0, 10, 10, window.hwnd, null, null, null) orelse
            error.TestUnexpectedResult;
    }

    /// `quick` loses the activation to `to`, or to a window Windows does
    /// not name (WM_ACTIVATE).
    fn deactivate(quick: *const Window, to: ?win32.HWND) void {
        const lparam: win32.LPARAM = if (to) |hwnd| @bitCast(@intFromPtr(hwnd)) else 0;
        _ = win32.SendMessageW(quick.hwnd, win32.WM_ACTIVATE, win32.WA_INACTIVE, lparam);
    }

    /// Whether `quick` posted itself the message that hides it as it lost
    /// the activation; carried out if it did, and the animation it starts
    /// carried to its end (`settle`).
    fn autohide(quick: *const Window) bool {
        if (!posted(quick)) return false;
        settle(quick);
        return true;
    }

    /// `autohide`, with the animation left to run.
    fn posted(quick: *const Window) bool {
        var msg: win32.MSG = undefined;
        if (!win32.PeekMessageW(&msg, quick.hwnd, WM_GHOSTTY_QUICK_HIDE, WM_GHOSTTY_QUICK_HIDE, win32.PM_REMOVE).toBool()) return false;
        _ = win32.DispatchMessageW(&msg);
        return true;
    }

    /// Hide the shown `quick` by a toggle while it is in front, with no
    /// window given the foreground yet.
    fn hideInFront(app: *App, quick: *const Window) !void {
        in_front = quick.hwnd;
        front = null;
        try toggle(app);
        try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    }

    /// A normal window beside the quick terminal, as the app has one
    /// unless a global keybind opens one: alone, with neither, a toggle
    /// closes it rather than hide it (`App.quickAlone`).
    fn beside(app: *App) !void {
        _ = try testFrame(app);
    }

    /// `window`, a test's frame (`testFrame`), closed by its WM_CLOSE with
    /// nothing to ask, and torn down. `run` would go on to
    /// `closeStrandedQuick`, which the test calls.
    fn closeFrame(app: *App, window: *Window) !void {
        _ = win32.SendMessageW(window.hwnd, win32.WM_CLOSE, 0, 0);
        tearDown();
        try std.testing.expect(std.mem.indexOfScalar(*Window, app.windows.items, window) == null);
    }

    /// The teardowns posted so far carried out, as `run` would dispatch
    /// them: of terminals (`Surface.destroyPosted`) and of windows
    /// (`Window.destroyPosted`).
    fn tearDown() void {
        var msg: win32.MSG = undefined;
        while (win32.PeekMessageW(&msg, null, WM_GHOSTTY_DESTROY, WM_GHOSTTY_DESTROY, win32.PM_REMOVE).toBool()) {
            _ = win32.DispatchMessageW(&msg);
        }
    }

    fn occlusion(surface: *Surface, visible: bool) void {
        if (!surface.window.quick) return;
        told = surface;
        shows = visible;
    }

    /// `toggle_quick_terminal`, as a binding performs it, then as `run`
    /// carries it out, and the animation it starts carried to its end
    /// (`settle`).
    fn toggle(app: *App) !void {
        try begin(app);
        if (app.quick) |quick| settle(quick);
    }

    /// `toggle`, with the animation left to run.
    fn begin(app: *App) !void {
        try std.testing.expect(try app.performAction(.app, .toggle_quick_terminal, {}));
        try std.testing.expectEqual(1, app.requests.items.len);
        app.createRequested();
        try std.testing.expectEqual(0, app.requests.items.len);
    }

    /// Where the quick terminal, `quick`, goes now with no monitors
    /// standing in (`TestMonitors`): on the primary monitor's work area,
    /// at the frame's DPI.
    fn place(app: *const App, quick: *const Window) !win32.RECT {
        const primary = win32.MonitorFromPoint(.{ .x = 0, .y = 0 }, win32.MONITOR_DEFAULTTOPRIMARY) orelse
            return error.TestUnexpectedResult;
        var info: win32.MONITORINFO = std.mem.zeroes(win32.MONITORINFO);
        info.cbSize = @sizeOf(win32.MONITORINFO);
        if (!win32.GetMonitorInfoW(primary, &info).toBool()) return error.TestUnexpectedResult;
        return Window.quickPlace(
            app.config.@"quick-terminal-position",
            app.config.@"quick-terminal-size",
            info.rcWork,
            Window.dpiOf(app, quick.hwnd),
        );
    }

    fn hasStyle(hwnd: win32.HWND, which: c_int, bits: win32.DWORD) bool {
        const want: isize = bits;
        return win32.GetWindowLongPtrW(hwnd, which) & want == want;
    }

    /// Half of the animation's default 0.2 s, and the share of the way it
    /// has gone by then: CSS's ease-in, cubic-bezier(0.42, 0, 1, 1), at
    /// 0.5, solved apart from `Window.easeIn`, by halving in Python to
    /// double precision.
    const half = std.time.ns_per_s / 10;
    const eased = 0.31535681257253945;

    /// What of a `width` x `height` quick terminal at `position` shows when
    /// `share` of it does, in its window's coordinates: a band along that
    /// edge, as deep as the share of it rounded up to a whole pixel.
    fn band(position: Config.QuickTerminalPosition, width: i32, height: i32, share: f64) win32.RECT {
        const deep = struct {
            fn f(size: i32, s: f64) i32 {
                return @intFromFloat(@ceil(@as(f64, @floatFromInt(size)) * s));
            }
        }.f;
        return switch (position) {
            .top => .{ .left = 0, .top = 0, .right = width, .bottom = deep(height, share) },
            .bottom => .{ .left = 0, .top = height - deep(height, share), .right = width, .bottom = height },
            .left => .{ .left = 0, .top = 0, .right = deep(width, share), .bottom = height },
            .right => .{ .left = width - deep(width, share), .top = 0, .right = width, .bottom = height },
            .center => unreachable,
        };
    }

    /// The owner of the last prompt `dialog.messageBox` would have shown
    /// (`dialog.test_message_box`), its text and buttons, whether it
    /// showed then, and whether `watch_topmost` was always on top then;
    /// answered with `answer`, Cancel unless a test says otherwise.
    var asked: ?win32.HWND = null;
    /// A copy: the prompt's own text is gone once it is answered.
    var asked_text: [600]u16 = undefined;
    var asked_len: usize = 0;
    var asked_buttons: win32.UINT = 0;
    var asked_shown: bool = false;
    var watch_topmost: ?win32.HWND = null;
    var asked_topmost: bool = false;
    var answer: c_int = win32.IDCANCEL;

    fn ask(owner: ?win32.HWND, prompt: win32.LPCWSTR, buttons: win32.UINT) c_int {
        asked = owner;
        const said = std.mem.span(prompt);
        asked_len = @min(said.len, asked_text.len);
        @memcpy(asked_text[0..asked_len], said[0..asked_len]);
        asked_buttons = buttons;
        asked_shown = if (owner) |hwnd| win32.IsWindowVisible(hwnd).toBool() else false;
        if (watch_topmost) |hwnd| asked_topmost = hasStyle(hwnd, win32.GWL_EXSTYLE, win32.WS_EX_TOPMOST);
        return answer;
    }

    /// That the last prompt asked `text`, with `default` (MB_DEFBUTTON1
    /// or MB_DEFBUTTON2) the button Enter presses.
    fn expectAsked(text: win32.LPCWSTR, default: win32.UINT) !void {
        try std.testing.expectEqualSlices(u16, std.mem.span(text), asked_text[0..asked_len]);
        try std.testing.expectEqual(default, asked_buttons & win32.MB_DEFMASK);
    }

    /// The quick terminal shown whole by a toggle and hidden by the next,
    /// each at once, with no step of an animation.
    fn atOnce(app: *App) !void {
        try begin(app);
        const quick = app.quick orelse return error.TestUnexpectedResult;
        try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expect((try region(quick)) == null);
        try std.testing.expect((try alpha(quick)) == null);
        try begin(app);
        try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expect((try region(quick)) == null);
    }
};

/// For the toggle_visibility tests: what GetForegroundWindow answers
/// (`App.test_get_foreground`), and the toggle as a binding performs it.
const TestVisibility = struct {
    var in_front: ?win32.HWND = null;

    fn foregroundNow() ?win32.HWND {
        return in_front;
    }

    /// `toggle_visibility`, recorded as the core performs it for the app,
    /// then carried out as `run` carries it out, with `front` in the
    /// foreground.
    fn toggle(app: *App, front: ?win32.HWND) !void {
        in_front = front;
        try std.testing.expect(try app.performAction(.app, .toggle_visibility, {}));
        try std.testing.expectEqual(1, app.requests.items.len);
        app.createRequested();
        try std.testing.expectEqual(0, app.requests.items.len);
    }

    fn minimized(window: *const Window) bool {
        return win32.IsIconic(window.hwnd).toBool();
    }
};

test "win32: toggle_visibility minimizes the windows that show, then shows those it hid" {
    // On a desktop of its own (testOnOwnDesktop): it shows its windows,
    // minimizes and restores them, away from the user's desktop.
    try testOnOwnDesktop(testToggleVisibility, .{});
}

/// The toggle_visibility test, run by its test on a desktop of its own.
fn testToggleVisibility() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    // With no window it hid left to show, the toggle asks the core for
    // the last focused terminal (`fallbackOwner`).
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    App.test_get_foreground = &TestVisibility.foregroundNow;
    defer App.test_get_foreground = null;
    Window.test_foreground = &ForegroundSeen.seen;
    defer Window.test_foreground = null;
    ForegroundSeen.last = null;
    const toggle = TestVisibility.toggle;
    const minimized = TestVisibility.minimized;

    // Two windows that show, one not shown yet, and one the user
    // minimized.
    var windows: [4]*Window = undefined;
    var panes: [4]*Surface = undefined;
    for (&windows, &panes) |*w, *p| {
        w.* = try testFrame(&app);
        p.* = try testPane(&app, w.*);
        w.*.tab().tree = try .init(alloc, p.*);
        try std.testing.expectEqual(.no, w.*.hidden);
    }
    const a = windows[0];
    const b = windows[1];
    const unshown = windows[2];
    const users = windows[3];
    _ = win32.ShowWindow(a.hwnd, win32.SW_SHOWNOACTIVATE);
    _ = win32.ShowWindow(b.hwnd, win32.SW_SHOWNOACTIVATE);
    _ = win32.ShowWindow(users.hwnd, win32.SW_SHOWMINNOACTIVE);

    // With one in the foreground: those that show are minimized, and
    // remembered, the one in front as that; nothing comes forward.
    try toggle(&app, b.hwnd);
    try std.testing.expect(minimized(a));
    try std.testing.expect(minimized(b));
    try std.testing.expectEqual(.hidden, a.hidden);
    try std.testing.expectEqual(.front, b.hidden);
    try std.testing.expect(!win32.IsWindowVisible(unshown.hwnd).toBool());
    try std.testing.expectEqual(.no, unshown.hidden);
    try std.testing.expect(minimized(users));
    try std.testing.expectEqual(.no, users.hidden);
    try std.testing.expect(ForegroundSeen.last == null);

    // With none there: those it hid come back, the one that was in front
    // forward, and are no longer its own; the user's stays minimized and
    // the other hidden.
    try toggle(&app, null);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!minimized(b));
    try std.testing.expectEqual(.no, a.hidden);
    try std.testing.expectEqual(.no, b.hidden);
    try std.testing.expectEqual(b.hwnd, ForegroundSeen.last.?);
    try std.testing.expect(minimized(users));
    try std.testing.expect(!win32.IsWindowVisible(unshown.hwnd).toBool());

    // One that was maximized comes back maximized, in front or not.
    _ = win32.ShowWindow(b.hwnd, win32.SW_SHOWMAXIMIZED);
    for ([_]*Window{ a, b }) |front| {
        try toggle(&app, front.hwnd);
        try std.testing.expect(minimized(a));
        try std.testing.expect(minimized(b));
        try toggle(&app, null);
        try std.testing.expect(!minimized(a));
        try std.testing.expect(!minimized(b));
        try std.testing.expect(win32.IsZoomed(b.hwnd).toBool());
        try std.testing.expect(!win32.IsZoomed(a.hwnd).toBool());
    }
    _ = win32.ShowWindow(b.hwnd, win32.SW_SHOWNOACTIVATE);
    try std.testing.expect(!win32.IsZoomed(b.hwnd).toBool());

    // A window one of them owns, as a prompt, in the foreground: its
    // owner is the one in front.
    const prompt = try TestQuick.owned(a);
    defer _ = win32.DestroyWindow(prompt);
    try toggle(&app, prompt);
    try std.testing.expectEqual(.front, a.hidden);
    try std.testing.expectEqual(.hidden, b.hidden);
    try std.testing.expect(minimized(a));
    try std.testing.expect(minimized(b));

    // One the user restores meanwhile is the user's from then on:
    // minimized again by hand, the toggle leaves it so.
    _ = win32.ShowWindow(b.hwnd, win32.SW_RESTORE);
    try std.testing.expectEqual(.no, b.hidden);
    try std.testing.expectEqual(.front, a.hidden);
    _ = win32.ShowWindow(b.hwnd, win32.SW_SHOWMINNOACTIVE);
    try std.testing.expectEqual(.no, b.hidden);
    ForegroundSeen.last = null;
    try toggle(&app, null);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(minimized(b));
    try std.testing.expectEqual(a.hwnd, ForegroundSeen.last.?);

    // One hidden in front that is still hidden when another is: shown
    // with the rest, and the later one comes forward.
    _ = win32.ShowWindow(b.hwnd, win32.SW_RESTORE);
    try toggle(&app, a.hwnd);
    try std.testing.expectEqual(.front, a.hidden);
    try std.testing.expectEqual(.hidden, b.hidden);
    _ = win32.ShowWindow(b.hwnd, win32.SW_RESTORE);
    try toggle(&app, b.hwnd);
    try std.testing.expectEqual(.hidden, a.hidden);
    try std.testing.expectEqual(.front, b.hidden);
    try std.testing.expect(minimized(a));
    try std.testing.expect(minimized(b));
    ForegroundSeen.last = null;
    try toggle(&app, null);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!minimized(b));
    try std.testing.expectEqual(b.hwnd, ForegroundSeen.last.?);

    // Another program's window in the foreground, and none of its own
    // hidden: nothing is minimized, and the first window comes forward.
    const other = try TestQuick.foreign();
    defer _ = win32.DestroyWindow(other);
    ForegroundSeen.last = null;
    try toggle(&app, other);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!minimized(b));
    try std.testing.expectEqual(.no, a.hidden);
    try std.testing.expectEqual(.no, b.hidden);
    try std.testing.expectEqual(a.hwnd, ForegroundSeen.last.?);

    // Or the one the user was last in, restored if it was minimized, as
    // a request to bring it forward restores it (`Window.present`).
    try core_app.surfaces.append(alloc, panes[3]);
    core_app.focused_surface = &panes[3].core_surface;
    try toggle(&app, other);
    try std.testing.expect(!minimized(users));
    try std.testing.expectEqual(users.hwnd, ForegroundSeen.last.?);
    try std.testing.expectEqual(.no, users.hidden);
    core_app.focused_surface = null;

    // A minimized window of its own in the foreground, as Windows leaves
    // one there with no other window to activate, is not in front: the
    // toggle shows.
    _ = win32.ShowWindow(users.hwnd, win32.SW_SHOWMINNOACTIVE);
    ForegroundSeen.last = null;
    try toggle(&app, users.hwnd);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!minimized(b));
    try std.testing.expectEqual(a.hwnd, ForegroundSeen.last.?);

    // One that covers its monitor is hidden like any other, and comes
    // back covering it.
    a.toggleFullscreen();
    try std.testing.expect(a.fullscreen != null);
    const covering = try windowRect(a.hwnd);
    try toggle(&app, a.hwnd);
    try std.testing.expect(minimized(a));
    try std.testing.expect(minimized(b));
    try std.testing.expectEqual(.front, a.hidden);
    ForegroundSeen.last = null;
    try toggle(&app, null);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!minimized(b));
    try std.testing.expect(a.fullscreen != null);
    try std.testing.expectEqual(covering, try windowRect(a.hwnd));
    try std.testing.expectEqual(a.hwnd, ForegroundSeen.last.?);
}

test "win32: toggle_visibility hides the quick terminal with the windows, unless it is alone" {
    // On a desktop of its own (testOnOwnDesktop), as the quick terminal's
    // own tests.
    try testOnOwnDesktop(testToggleVisibilityQuick, .{});
}

/// The toggle_visibility test with a quick terminal, run by its test on a
/// desktop of its own.
fn testToggleVisibilityQuick() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    const minimized = TestVisibility.minimized;

    // `TestQuick`'s GetForegroundWindow, with the toggle carried out and
    // the quick terminal's animation, if it started one, carried to its
    // end.
    const toggle = struct {
        fn f(of: *App, front: ?win32.HWND) !void {
            TestQuick.in_front = front;
            TestQuick.front = null;
            try std.testing.expect(try of.performAction(.app, .toggle_visibility, {}));
            try std.testing.expectEqual(1, of.requests.items.len);
            of.createRequested();
            try std.testing.expectEqual(0, of.requests.items.len);
            if (of.quick) |q| TestQuick.settle(q);
        }
    }.f;

    // The quick terminal alone, in front: it stays, as its own toggle
    // would not hide it either, with nothing to show it again
    // (`quickAlone`).
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expect(app.quickAlone());
    try toggle(&app, quick.hwnd);
    try std.testing.expect(quick.quickShown());
    try std.testing.expectEqual(.no, quick.hidden);

    // With a window beside it, and itself in front: both go, the quick
    // terminal as its own toggle hides it, and it is the one to come
    // forward.
    const a = try testFrame(&app);
    const pa = try testPane(&app, a);
    a.tab().tree = try .init(alloc, pa);
    _ = win32.ShowWindow(a.hwnd, win32.SW_SHOWNOACTIVATE);
    try toggle(&app, quick.hwnd);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(.front, quick.hidden);
    try std.testing.expect(minimized(a));
    try std.testing.expectEqual(.hidden, a.hidden);
    try std.testing.expect(TestQuick.front == null);

    // Laid out while it is hidden, as a reload lays it out, it is still
    // the toggle's to show: only a window that is restored forgets.
    testResize(quick, 900, 500);
    try std.testing.expectEqual(.front, quick.hidden);

    try toggle(&app, null);
    try std.testing.expect(quick.quickShown());
    try std.testing.expectEqual(.no, quick.hidden);
    try std.testing.expect(!minimized(a));
    try std.testing.expectEqual(.no, a.hidden);
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);

    // With the window in front: both go again, and the window is the one
    // to come forward, after the quick terminal shows.
    try toggle(&app, a.hwnd);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(.hidden, quick.hidden);
    try std.testing.expect(minimized(a));
    try std.testing.expectEqual(.front, a.hidden);
    try toggle(&app, null);
    try std.testing.expect(quick.quickShown());
    try std.testing.expect(!minimized(a));
    try std.testing.expectEqual(a.hwnd, TestQuick.front.?);

    // Hidden by it, then shown by its own toggle: no longer this one's
    // to show; the window still is.
    try toggle(&app, quick.hwnd);
    try std.testing.expectEqual(.front, quick.hidden);
    TestQuick.in_front = null;
    try TestQuick.toggle(&app);
    try std.testing.expect(quick.quickShown());
    try std.testing.expectEqual(.no, quick.hidden);
    try std.testing.expectEqual(.hidden, a.hidden);
    try std.testing.expect(minimized(a));
    // Hidden again by its own, it stays hidden when the toggle shows.
    try TestQuick.toggle(&app);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(.no, quick.hidden);
    try toggle(&app, null);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    // The window comes forward: the first that shows, with none hidden
    // in front.
    try std.testing.expectEqual(a.hwnd, TestQuick.front.?);

    // Hidden already when the windows are, it is not the toggle's to
    // show.
    try toggle(&app, a.hwnd);
    try std.testing.expect(minimized(a));
    try std.testing.expectEqual(.no, quick.hidden);
    try toggle(&app, null);
    try std.testing.expect(!minimized(a));
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());

    // Hidden and still the foreground window, as with its terminal's
    // inspector in front: none of the windows in front shows, so the
    // toggle shows, and goes on showing.
    try toggle(&app, a.hwnd);
    try std.testing.expect(minimized(a));
    try toggle(&app, quick.hwnd);
    try std.testing.expect(!minimized(a));
    try toggle(&app, quick.hwnd);
    try std.testing.expect(!minimized(a));
}

test "win32: toggle_quick_terminal makes the quick terminal, then hides and shows it" {
    // On a desktop of its own (testOnOwnDesktop): it reads whether the
    // quick terminal is topmost, and keeps it off the user's desktop.
    try testOnOwnDesktop(testToggleQuick, .{});
}

/// The toggle_quick_terminal test, run by its test on a desktop of its own.
fn testToggleQuick() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();

    // A window opened before it.
    const a = try testFrame(&app);
    const pa = try testPane(&app, a);
    a.tab().tree = try .init(alloc, pa);

    // Recorded, as the core performs it inside a key callback, and made by
    // `run`: a pop-up with no frame and no taskbar button, at its place,
    // above every window that is not, brought forward.
    try std.testing.expect(try app.performAction(.app, .toggle_quick_terminal, {}));
    try std.testing.expect(app.quick == null);
    app.createRequested();
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expect(quick.quick);
    try std.testing.expectEqualSlices(*Window, &.{ a, quick }, app.windows.items);
    const pane = quick.tab().focused orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualSlices(*Surface, &.{ pa, pane }, app.surfaces.items);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(TestQuick.hasStyle(quick.hwnd, win32.GWL_STYLE, win32.WS_POPUP));
    try std.testing.expect(!captioned(quick.hwnd));
    try std.testing.expect(!TestQuick.hasStyle(quick.hwnd, win32.GWL_STYLE, win32.WS_THICKFRAME));
    try std.testing.expect(TestQuick.hasStyle(quick.hwnd, win32.GWL_EXSTYLE, win32.WS_EX_TOOLWINDOW));
    try std.testing.expect(quick.isFloating());
    const place = try TestQuick.place(&app, quick);
    try std.testing.expectEqual(place, try windowRect(quick.hwnd));
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);
    try std.testing.expectEqual(pane, TestQuick.told.?);
    try std.testing.expect(TestQuick.shows);
    // Its terminal is made at its size, which the core starts from: the
    // frame is made at its place, not at CW_USEDEFAULT.
    try std.testing.expectEqual(win32.RECT{
        .left = 0,
        .top = 0,
        .right = place.right - place.left,
        .bottom = place.bottom - place.top,
    }, TestQuick.area.?);

    // Only its terminals have the variable that says so, as on GTK.
    {
        var base = try global.environMap();
        defer base.deinit();
        var in_quick = try pane.defaultTermioEnv();
        defer in_quick.deinit();
        var in_a = try pa.defaultTermioEnv();
        defer in_a.deinit();
        try std.testing.expectEqualStrings("1", in_quick.get("GHOSTTY_QUICK_TERMINAL").?);
        try std.testing.expectEqualDeep(base.get("GHOSTTY_QUICK_TERMINAL"), in_a.get("GHOSTTY_QUICK_TERMINAL"));
    }

    // goto_window leaves it out: from the other window there is nowhere
    // to go, and with a third, it goes round past it.
    try std.testing.expect(!try app.performAction(.{ .surface = &pa.core_surface }, .goto_window, .next));
    try std.testing.expectEqual(0, app.requests.items.len);
    const b = try testFrame(&app);
    try std.testing.expectEqual(b, app.windowBeside(a, .next).?);
    try std.testing.expectEqual(b, app.windowBeside(a, .previous).?);
    try std.testing.expectEqual(a, app.windowBeside(b, .next).?);
    try std.testing.expectEqual(a, app.windowBeside(b, .previous).?);
    // From it: the windows either side of its place.
    try std.testing.expectEqual(a, app.windowBeside(quick, .next).?);
    try std.testing.expectEqual(b, app.windowBeside(quick, .previous).?);

    // Hidden, with its terminal kept, which is told it no longer shows;
    // its command palette closes. Made as large as the palette's own test
    // makes its window, for the palette to fit at any DPI.
    testResize(quick, 1000, 700);
    try std.testing.expect(try app.performAction(.{ .surface = &pane.core_surface }, .toggle_command_palette, {}));
    app.createRequested();
    try std.testing.expect(quick.palette.hwnd != null);
    TestQuick.front = null;
    try TestQuick.toggle(&app);
    try std.testing.expect(quick.palette.hwnd == null);
    try std.testing.expectEqual(quick, app.quick.?);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(pane, TestQuick.told.?);
    try std.testing.expect(!TestQuick.shows);
    try std.testing.expect(TestQuick.front == null);
    try std.testing.expectEqual(3, app.windows.items.len);

    // Nothing laid out while it is hidden tells its terminal it shows: a
    // reloaded configuration's frames (`redecorate`), or a move, which
    // the frame hears of (WM_SIZE). Shown again where it goes now, above
    // the rest, whatever moved it meanwhile.
    try app.requests.append(alloc, .redecorate);
    app.createRequested();
    _ = win32.SetWindowPos(quick.hwnd, win32.HWND_NOTOPMOST, 30, 40, 50, 60, win32.SWP_NOACTIVATE);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(!quick.isFloating());
    try std.testing.expect(!TestQuick.shows);
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(quick, app.quick.?);
    try std.testing.expectEqual(pane, quick.tab().focused.?);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(quick.isFloating());
    try std.testing.expectEqual(try TestQuick.place(&app, quick), try windowRect(quick.hwnd));
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);
    try std.testing.expect(TestQuick.shows);

    // Its title prompt closes as it hides: hiding a window leaves the
    // windows it owns on screen.
    const dialog = try testPrompt(&app, pane, .surface);
    try TestQuick.toggle(&app);
    try std.testing.expect(!win32.IsWindow(dialog).toBool());
    try std.testing.expect(quick.title_prompt.hwnd == null);
    try TestQuick.toggle(&app);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());

    // Closed, it is forgotten, and the next toggle makes another.
    try std.testing.expect(win32.DestroyWindow(quick.hwnd).toBool());
    try std.testing.expect(app.quick == null);
    try std.testing.expectEqualSlices(*Window, &.{ a, b }, app.windows.items);
    try TestQuick.toggle(&app);
    const again = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expect(win32.IsWindowVisible(again.hwnd).toBool());
    try std.testing.expectEqual(3, app.windows.items.len);
}

test "win32: a quick terminal that cannot be made is said so, and the next toggle makes it" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickFails, .{});
}

/// The failed quick terminal test, run by its test on a desktop of its own.
fn testQuickFails() !void {
    const alloc = std.testing.allocator;
    // The failure's box has no window, so it asks the core for the last
    // focused terminal (`fallbackOwner`): there is none.
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    const Prompt = struct {
        var boxes: usize = 0;
        fn box(_: ?win32.HWND, _: win32.LPCWSTR, _: win32.UINT) c_int {
            boxes += 1;
            return win32.IDOK;
        }
    };
    const message_box = &@import("dialog.zig").test_message_box;
    message_box.* = &Prompt.box;
    defer message_box.* = null;

    // Its frame is destroyed again (`Window.discard`): nothing is left.
    TestQuick.fail = true;
    try TestQuick.toggle(&app);
    try std.testing.expect(app.quick == null);
    try std.testing.expectEqual(0, app.windows.items.len);
    try std.testing.expectEqual(0, app.surfaces.items.len);
    try std.testing.expectEqual(1, Prompt.boxes);

    // Nor with no monitor to make it on: no frame is made.
    TestQuick.fail = false;
    TestMonitors.start(&app);
    defer TestMonitors.stop();
    TestMonitors.none = true;
    try TestQuick.toggle(&app);
    try std.testing.expect(app.quick == null);
    try std.testing.expectEqual(0, app.windows.items.len);
    try std.testing.expectEqual(0, app.surfaces.items.len);
    try std.testing.expectEqual(2, Prompt.boxes);

    TestMonitors.none = false;
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(2, Prompt.boxes);
}

test "win32: the quick terminal keeps its place, its size and its frame" {
