/// The test of what leaves the quick terminal as it is, run by its test
/// on a desktop of its own.
fn testQuickKeepsPlace() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();

    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    const pane = quick.tab().focused orelse return error.TestUnexpectedResult;
    const target: apprt.Target = .{ .surface = &pane.core_surface };
    const rect = try windowRect(quick.hwnd);
    const style = win32.GetWindowLongPtrW(quick.hwnd, win32.GWL_STYLE);
    const ex_style = win32.GetWindowLongPtrW(quick.hwnd, win32.GWL_EXSTYLE);

    // Refused, so that the key reaches the terminal, and nothing is
    // recorded; reset_window_size although the core gave the terminal a
    // size of its own, which is kept, as a tab can move to another window.
    try std.testing.expect(try app.performAction(target, .initial_size, .{ .width = 300, .height = 200 }));
    try std.testing.expect(!try app.performAction(target, .toggle_maximize, {}));
    try std.testing.expect(!try app.performAction(target, .toggle_fullscreen, .native));
    try std.testing.expect(!try app.performAction(target, .toggle_window_decorations, {}));
    try std.testing.expect(!try app.performAction(target, .reset_window_size, {}));
    try std.testing.expect(!try app.performAction(target, .resize_window, .{ .width = 300, .height = 200 }));
    try std.testing.expectEqual(0, app.requests.items.len);
    // It floats while it shows, whatever float_window asks.
    try std.testing.expect(!try app.performAction(target, .float_window, .off));
    try std.testing.expect(quick.isFloating());

    // Nor do the window's own, which run for every window: a reloaded
    // configuration's frame (`redecorate`) among them.
    quick.toggleFullscreen();
    quick.toggleMaximize();
    quick.toggleDecorations();
    try app.requests.append(alloc, .redecorate);
    app.createRequested();
    try std.testing.expect(quick.fullscreen == null);
    try std.testing.expect(quick.decoration == null);
    try std.testing.expectEqual(style, win32.GetWindowLongPtrW(quick.hwnd, win32.GWL_STYLE));
    try std.testing.expectEqual(ex_style, win32.GetWindowLongPtrW(quick.hwnd, win32.GWL_EXSTYLE));
    try std.testing.expectEqual(rect, try windowRect(quick.hwnd));
}

/// For tests: two monitors the VM does not have, which `Window.quickWork`
/// asks of in place of Windows (`Window.test_monitor`): `a`, the primary,
/// with the taskbar at its foot, and `b` right of it and higher, with its
/// own at its top, at `b_dpi`. A window's DPI is that of the monitor its
/// centre is on (`App.get_dpi_for_window`), as per-monitor DPI makes it.
/// With the hook (`proc`) set, the quick terminal, `frame`, is sent the
/// WM_DPICHANGED Windows sends once a move has taken it onto a monitor
/// with another DPI than `frame_dpi`, with its rect scaled about its
/// centre for the rect Windows suggests. What its terminals were last told
/// of their DPI is `scale` (`Surface.test_scale_changed`). While `none`,
/// no monitor can be read.
const TestMonitors = struct {
    var none = false;
    var a: win32.MONITORINFO = undefined;
    var b: win32.MONITORINFO = undefined;
    var b_dpi: win32.UINT = 144;
    var frame: ?win32.HWND = null;
    var frame_dpi: win32.UINT = 96;
    var dpi_changes: usize = 0;
    var scale: ?u16 = null;

    const on_a: win32.POINT = .{ .x = 800, .y = 450 };
    const on_b: win32.POINT = .{ .x = 2500, .y = 300 };

    /// With the pointer on `a`.
    fn start(app: *App) void {
        a = info(
            .{ .left = 0, .top = 0, .right = 1600, .bottom = 900 },
            .{ .left = 0, .top = 0, .right = 1600, .bottom = 860 },
        );
        b = info(
            .{ .left = 1600, .top = -200, .right = 3520, .bottom = 880 },
            .{ .left = 1600, .top = -170, .right = 3520, .bottom = 880 },
        );
        none = false;
        b_dpi = 144;
        frame = null;
        frame_dpi = 96;
        dpi_changes = 0;
        scale = null;
        Window.test_monitor = &answer;
        Surface.test_scale_changed = &scaled;
        Dividers.test_cursor_pos = on_a;
        app.get_dpi_for_window = &dpiOf;
    }

    fn stop() void {
        Window.test_monitor = null;
        Surface.test_scale_changed = null;
        Dividers.test_cursor_pos = null;
    }

    fn info(monitor: win32.RECT, work: win32.RECT) win32.MONITORINFO {
        var v: win32.MONITORINFO = std.mem.zeroes(win32.MONITORINFO);
        v.cbSize = @sizeOf(win32.MONITORINFO);
        v.rcMonitor = monitor;
        v.rcWork = work;
        return v;
    }

    fn within(r: win32.RECT, pt: win32.POINT) bool {
        return pt.x >= r.left and pt.x < r.right and pt.y >= r.top and pt.y < r.bottom;
    }

    /// As MonitorFromPoint answers: the monitor the point is on, or, for
    /// a point on neither, the primary for MONITOR_DEFAULTTOPRIMARY and
    /// otherwise the nearer, taken to be the one on its side of their edge.
    fn answer(at: win32.POINT, flags: win32.DWORD) ?win32.MONITORINFO {
        if (none) return null;
        if (within(a.rcMonitor, at)) return a;
        if (within(b.rcMonitor, at)) return b;
        return if (flags == win32.MONITOR_DEFAULTTOPRIMARY or at.x < b.rcMonitor.left) a else b;
    }

    fn dpiAt(hwnd: win32.HWND) win32.UINT {
        var r: win32.RECT = undefined;
        if (!win32.GetWindowRect(hwnd, &r).toBool()) return 96;
        const centre: win32.POINT = .{
            .x = r.left + @divTrunc(r.right - r.left, 2),
            .y = r.top + @divTrunc(r.bottom - r.top, 2),
        };
        return if (within(b.rcMonitor, centre)) b_dpi else 96;
    }

    fn dpiOf(hwnd: win32.HWND) callconv(.winapi) win32.UINT {
        return dpiAt(hwnd);
    }

    fn scaled(surface: *Surface, dpi: u16) void {
        if (surface.window.quick) scale = dpi;
    }

    fn proc(code: c_int, wparam: win32.WPARAM, lparam: win32.LPARAM) callconv(.winapi) win32.LRESULT {
        if (code >= 0) {
            const sent: *const win32.CWPRETSTRUCT = @ptrFromInt(@as(usize, @bitCast(lparam)));
            if (frame) |hwnd| if (sent.hwnd == hwnd and sent.message == win32.WM_WINDOWPOSCHANGED) {
                const now = dpiAt(hwnd);
                var r: win32.RECT = undefined;
                if (now != frame_dpi and win32.GetWindowRect(hwnd, &r).toBool()) {
                    const was: i32 = @intCast(frame_dpi);
                    frame_dpi = now;
                    dpi_changes += 1;
                    const w = @divTrunc((r.right - r.left) * @as(i32, @intCast(now)), was);
                    const h = @divTrunc((r.bottom - r.top) * @as(i32, @intCast(now)), was);
                    const cx = r.left + @divTrunc(r.right - r.left, 2);
                    const cy = r.top + @divTrunc(r.bottom - r.top, 2);
                    var suggested: win32.RECT = .{
                        .left = cx - @divTrunc(w, 2),
                        .top = cy - @divTrunc(h, 2),
                        .right = cx - @divTrunc(w, 2) + w,
                        .bottom = cy - @divTrunc(h, 2) + h,
                    };
                    const dpi: win32.WPARAM = now;
                    _ = win32.SendMessageW(hwnd, win32.WM_DPICHANGED, dpi << 16 | dpi, @bitCast(@intFromPtr(&suggested)));
                }
            };
        }
        return win32.CallNextHookEx(null, code, wparam, lparam);
    }
};

test "win32: the quick terminal goes on the monitor its screen names, and stays on it while it shows" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickScreen, .{});
}

/// The test of the quick terminal's monitor, run by its test on a desktop
/// of its own.
fn testQuickScreen() !void {
    const RECT = win32.RECT;
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);
    TestMonitors.start(&app);
    defer TestMonitors.stop();

    // `main`, the default: the primary monitor's work area, at its DPI,
    // wherever the pointer is.
    Dividers.test_cursor_pos = TestMonitors.on_b;
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));

    // `mouse`: the work area of the pointer's monitor, below its taskbar,
    // at the DPI the move there gave the frame, 144: its terminal is told
    // so, and it is 600 deep, where 96 DPI's would be 400.
    try TestQuick.toggle(&app);
    app.config.@"quick-terminal-screen" = .mouse;
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -170, .right = 3520, .bottom = 430 }, try windowRect(quick.hwnd));
    try std.testing.expectEqual(144, TestMonitors.scale.?);

    // While it shows, a work area that changes, and displays that change,
    // place it again on the monitor it is on, not the pointer's: here the
    // taskbar going to the foot, then a monitor made wider.
    Dividers.test_cursor_pos = TestMonitors.on_a;
    TestMonitors.b.rcWork = .{ .left = 1600, .top = -200, .right = 3520, .bottom = 840 };
    _ = win32.SendMessageW(quick.hwnd, win32.WM_SETTINGCHANGE, win32.SPI_SETWORKAREA, 0);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -200, .right = 3520, .bottom = 400 }, try windowRect(quick.hwnd));
    TestMonitors.b.rcMonitor = .{ .left = 1600, .top = -200, .right = 4160, .bottom = 1240 };
    TestMonitors.b.rcWork = .{ .left = 1600, .top = -200, .right = 4160, .bottom = 1200 };
    _ = win32.SendMessageW(quick.hwnd, win32.WM_DISPLAYCHANGE, 32, 0);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -200, .right = 4160, .bottom = 400 }, try windowRect(quick.hwnd));

    // Hidden, it is left where it is until it shows, then goes where the
    // pointer is, at 96 DPI again.
    try TestQuick.toggle(&app);
    TestMonitors.b.rcWork = .{ .left = 1600, .top = 0, .right = 4160, .bottom = 1200 };
    _ = win32.SendMessageW(quick.hwnd, win32.WM_SETTINGCHANGE, win32.SPI_SETWORKAREA, 0);
    _ = win32.SendMessageW(quick.hwnd, win32.WM_DISPLAYCHANGE, 32, 0);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -200, .right = 4160, .bottom = 400 }, try windowRect(quick.hwnd));
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));
    try std.testing.expectEqual(96, TestMonitors.scale.?);

    // `macos-menu-bar`, which Windows has not: the primary's, as `main`.
    try TestQuick.toggle(&app);
    app.config.@"quick-terminal-screen" = .@"macos-menu-bar";
    Dividers.test_cursor_pos = TestMonitors.on_b;
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));

    // With no monitor to read, it shows where it was, above the rest.
    try TestQuick.toggle(&app);
    TestMonitors.none = true;
    try TestQuick.toggle(&app);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(quick.isFloating());
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));
}

test "win32: the quick terminal takes its place at its monitor's DPI, as that changes" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickDpi, .{});
}

/// The test of the quick terminal's DPI, run by its test on a desktop of
/// its own.
fn testQuickDpi() !void {
    const RECT = win32.RECT;
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);
    TestMonitors.start(&app);
    defer TestMonitors.stop();
    app.config.@"quick-terminal-screen" = .mouse;

    // Made on the pointer's monitor, at its DPI from the first: its
    // terminal is made at the size it has there.
    Dividers.test_cursor_pos = TestMonitors.on_b;
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1920, .bottom = 600 }, TestQuick.area.?);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -170, .right = 3520, .bottom = 430 }, try windowRect(quick.hwnd));

    // With the WM_DPICHANGED Windows sends as the frame arrives on a
    // monitor with another DPI, inside the move: once each way, the
    // terminal told the new DPI, the frame at its place at it.
    TestMonitors.frame = quick.hwnd;
    TestMonitors.frame_dpi = 144;
    const hook = win32.SetWindowsHookExW(
        win32.WH_CALLWNDPROCRET,
        TestMonitors.proc,
        null,
        std.os.windows.GetCurrentThreadId(),
    ) orelse return error.TestUnexpectedResult;
    defer _ = win32.UnhookWindowsHookEx(hook);
    try TestQuick.toggle(&app);
    Dividers.test_cursor_pos = TestMonitors.on_a;
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(1, TestMonitors.dpi_changes);
    try std.testing.expectEqual(96, TestMonitors.scale.?);
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));
    try TestQuick.toggle(&app);
    Dividers.test_cursor_pos = TestMonitors.on_b;
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(2, TestMonitors.dpi_changes);
    try std.testing.expectEqual(144, TestMonitors.scale.?);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -170, .right = 3520, .bottom = 430 }, try windowRect(quick.hwnd));

    // Its monitor's scale changed while it shows, as Windows tells it,
    // with a suggested rect that is not its place, on the other monitor
    // here, as the pointer is: it takes its place at the new DPI on the
    // monitor it is on, 800 deep, its terminal told first.
    Dividers.test_cursor_pos = TestMonitors.on_a;
    TestMonitors.b_dpi = 192;
    TestMonitors.frame_dpi = 192;
    var suggested: RECT = .{ .left = 10, .top = 10, .right = 110, .bottom = 110 };
    _ = win32.SendMessageW(quick.hwnd, win32.WM_DPICHANGED, 192 << 16 | 192, @bitCast(@intFromPtr(&suggested)));
    try std.testing.expectEqual(192, TestMonitors.scale.?);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -170, .right = 3520, .bottom = 630 }, try windowRect(quick.hwnd));
    try std.testing.expectEqual(2, TestMonitors.dpi_changes);
}

test "win32: a reloaded configuration places a shown quick terminal again, and a hidden one as it shows" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickReload, .{});
}

/// The test of the quick terminal's reloaded place, run by its test on a
/// desktop of its own.
fn testQuickReload() !void {
    const RECT = win32.RECT;
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);
    TestMonitors.start(&app);
    defer TestMonitors.stop();

    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));

    // Its new position and size, from `run` (`redecorate`), not inside the
    // core frame the reload comes in.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"quick-terminal-position" = .bottom;
    changed.@"quick-terminal-size" = .{ .primary = .{ .percentage = 50 } };
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    try std.testing.expectEqual(RECT{ .left = 0, .top = 0, .right = 1600, .bottom = 400 }, try windowRect(quick.hwnd));
    app.createRequested();
    try std.testing.expectEqual(RECT{ .left = 0, .top = 430, .right = 1600, .bottom = 860 }, try windowRect(quick.hwnd));

    // `mouse` leaves it on the monitor it is on while it shows.
    Dividers.test_cursor_pos = TestMonitors.on_b;
    changed.@"quick-terminal-screen" = .mouse;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    app.createRequested();
    try std.testing.expectEqual(RECT{ .left = 0, .top = 430, .right = 1600, .bottom = 860 }, try windowRect(quick.hwnd));

    // Hidden, it waits for its next show, then takes it on the pointer's
    // monitor: half the width there at its DPI, and all its height.
    try TestQuick.toggle(&app);
    changed.@"quick-terminal-position" = .left;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    app.createRequested();
    try std.testing.expectEqual(RECT{ .left = 0, .top = 430, .right = 1600, .bottom = 860 }, try windowRect(quick.hwnd));
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(RECT{ .left = 1600, .top = -170, .right = 2560, .bottom = 880 }, try windowRect(quick.hwnd));
}

test "win32: a toggle gives the foreground back to the window the quick terminal came from" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickReturn, .{});
}

/// The test of the quick terminal's focus return, run by its test on a
/// desktop of its own.
fn testQuickReturn() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    const other = try TestQuick.foreign();
    defer _ = win32.DestroyWindow(other);
    const a = try testFrame(&app);

    // Shown over another program's window, and hidden while it is in
    // front: the foreground goes back to that window, while it still
    // shows, so while Ghostty may still give it.
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    TestQuick.watch = quick.hwnd;
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expectEqual(other, TestQuick.front.?);
    try std.testing.expect(TestQuick.watch_shown);

    // Over one of Ghostty's own windows, here a shown one the other frame
    // owns, as a prompt: nothing to give back, as macOS gives it back only
    // to another app.
    const ours = try TestQuick.owned(a);
    defer _ = win32.DestroyWindow(ours);
    _ = win32.ShowWindow(ours, win32.SW_SHOWNOACTIVATE);
    TestQuick.in_front = ours;
    try TestQuick.toggle(&app);
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expect(TestQuick.front == null);

    // Hidden while another window is in front, the user having gone
    // there: the foreground stays where it is.
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    TestQuick.front = null;
    try TestQuick.toggle(&app);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(TestQuick.front == null);

    // With a window it owns in front, its title prompt: given back.
    try TestQuick.toggle(&app);
    const pane = quick.tab().focused orelse return error.TestUnexpectedResult;
    const dialog = try testPrompt(&app, pane, .surface);
    TestQuick.in_front = dialog;
    TestQuick.front = null;
    try TestQuick.toggle(&app);
    try std.testing.expectEqual(other, TestQuick.front.?);

    // A window that has closed since, or is minimized, is left as it is.
    const gone = try TestQuick.foreign();
    TestQuick.in_front = gone;
    try TestQuick.toggle(&app);
    try std.testing.expect(win32.DestroyWindow(gone).toBool());
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expect(TestQuick.front == null);
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    _ = win32.ShowWindow(other, win32.SW_SHOWMINNOACTIVE);
    try std.testing.expect(win32.IsIconic(other).toBool());
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expect(TestQuick.front == null);
    _ = win32.ShowWindow(other, win32.SW_SHOWNOACTIVATE);

    // The activation lost to a window it owns, to another program's or to
    // one Windows does not name keeps the window to give back; lost to
    // another of Ghostty's, it is forgotten, as macOS forgets the app it
    // came from once its own app keeps the activation.
    const owned = try TestQuick.owned(quick);
    defer _ = win32.DestroyWindow(owned);
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    TestQuick.deactivate(quick, owned);
    TestQuick.deactivate(quick, other);
    TestQuick.deactivate(quick, null);
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expectEqual(other, TestQuick.front.?);
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    TestQuick.deactivate(quick, a.hwnd);
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expect(TestQuick.front == null);
}

test "win32: with autohide the quick terminal hides as it loses the activation" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickAutohide, .{});
}

/// The quick terminal's autohide test, run by its test on a desktop of its
/// own.
fn testQuickAutohide() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    const other = try TestQuick.foreign();
    defer _ = win32.DestroyWindow(other);
    const a = try testFrame(&app);

    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    const owned = try TestQuick.owned(quick);
    defer _ = win32.DestroyWindow(owned);

    // Off, as it is on Windows unless set: it stays.
    TestQuick.deactivate(quick, other);
    try std.testing.expect(!TestQuick.autohide(quick));
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());

    // On from a reloaded configuration, read as it loses the activation:
    // hidden once that change is over, its terminal told, and with no
    // foreground given back, the user having chosen where it went.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"quick-terminal-autohide" = true;
    try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &changed }));
    app.createRequested();
    TestQuick.front = null;
    TestQuick.deactivate(quick, other);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(TestQuick.autohide(quick));
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect(!TestQuick.shows);
    try std.testing.expect(TestQuick.front == null);

    // Hidden, it has no activation to lose: nothing is posted.
    TestQuick.deactivate(quick, other);
    try std.testing.expect(!TestQuick.autohide(quick));

    // Lost to a window Windows does not name, or to another of Ghostty's,
    // as GTK hides its own for any window: hidden.
    try TestQuick.toggle(&app);
    TestQuick.deactivate(quick, null);
    try std.testing.expect(TestQuick.autohide(quick));
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try TestQuick.toggle(&app);
    TestQuick.in_front = a.hwnd;
    TestQuick.deactivate(quick, a.hwnd);
    try std.testing.expect(TestQuick.autohide(quick));
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());

    // Lost to a window it owns, as a prompt: it stays, as macOS keeps its
    // quick terminal while a sheet is up.
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    TestQuick.in_front = owned;
    TestQuick.deactivate(quick, owned);
    try std.testing.expect(!TestQuick.autohide(quick));
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());

    // Back with it, or with a window it owns, before the message comes:
    // it stays.
    TestQuick.deactivate(quick, other);
    TestQuick.in_front = quick.hwnd;
    try std.testing.expect(TestQuick.autohide(quick));
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    TestQuick.deactivate(quick, other);
    TestQuick.in_front = owned;
    try std.testing.expect(TestQuick.autohide(quick));
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
}

test "win32: the quick terminal is uncovered from its edge as it shows, and covered back as it hides" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickUncover, .{});
}

/// The test of the quick terminal's animation at its edges, run by its
/// test on a desktop of its own.
fn testQuickUncover() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);

    // Over the default 0.2 s, as macOS's.
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    try std.testing.expectEqual(0.2, changed.@"quick-terminal-animation-duration");
    for ([_]Config.QuickTerminalPosition{ .top, .bottom, .left, .right }) |position| {
        changed.@"quick-terminal-position" = position;
        try TestQuick.reconfigure(&app, &changed);

        // Shown at its place at once, the first one as it is made, with
        // none of it let through yet.
        try TestQuick.begin(&app);
        const quick = app.quick orelse return error.TestUnexpectedResult;
        const place = try windowRect(quick.hwnd);
        try std.testing.expectEqual(try TestQuick.place(&app, quick), place);
        const width = place.right - place.left;
        const height = place.bottom - place.top;
        try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expectEqual(std.mem.zeroes(win32.RECT), (try TestQuick.region(quick)).?);

        // Halfway through its time, eased: a band along its edge, with the
        // window still at its place.
        TestQuick.tick(quick, TestQuick.half);
        try std.testing.expectEqual(TestQuick.band(position, width, height, TestQuick.eased), (try TestQuick.region(quick)).?);
        try std.testing.expectEqual(place, try windowRect(quick.hwnd));
        // At its end, whole: no region left, and not faded; and its timer
        // stopped, as KillTimer finds none to kill.
        TestQuick.tick(quick, TestQuick.half);
        try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expect((try TestQuick.region(quick)) == null);
        try std.testing.expect((try TestQuick.alpha(quick)) == null);
        try std.testing.expect(!win32.KillTimer(quick.hwnd, Window.quick_timer_id).toBool());
        // A step still in the queue after that changes nothing.
        TestQuick.tick(quick, TestQuick.half);
        try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expect((try TestQuick.region(quick)) == null);

        // Covered back the same way as it hides, from all of it, and on
        // screen, its terminal not told otherwise, until the end. A timer
        // steps it, which the test kills, as it steps it itself.
        try TestQuick.begin(&app);
        try std.testing.expect(win32.KillTimer(quick.hwnd, Window.quick_timer_id).toBool());
        try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expectEqual(TestQuick.band(position, width, height, 1), (try TestQuick.region(quick)).?);
        TestQuick.tick(quick, TestQuick.half);
        try std.testing.expectEqual(TestQuick.band(position, width, height, 1 - TestQuick.eased), (try TestQuick.region(quick)).?);
        try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expect(TestQuick.shows);
        TestQuick.tick(quick, TestQuick.half);
        try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
        try std.testing.expect(!TestQuick.shows);
        try std.testing.expect((try TestQuick.region(quick)) == null);
        TestQuick.tick(quick, TestQuick.half);
        try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    }
}

test "win32: a toggle partway through the quick terminal's animation turns it back from where it is" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickTurnBack, .{});
}

/// The test of the quick terminal's animation turned back, run by its test
/// on a desktop of its own.
fn testQuickTurnBack() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);
    const e = TestQuick.eased;

    // Hidden halfway in: from what shows, over the whole time again, as
    // macOS's animator turns back.
    try TestQuick.begin(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    const place = try windowRect(quick.hwnd);
    const width = place.right - place.left;
    const height = place.bottom - place.top;
    TestQuick.tick(quick, TestQuick.half);
    try TestQuick.begin(&app);
    try std.testing.expectEqual(TestQuick.band(.top, width, height, e), (try TestQuick.region(quick)).?);
    TestQuick.tick(quick, TestQuick.half);
    const back = e - e * e;
    try std.testing.expectEqual(TestQuick.band(.top, width, height, back), (try TestQuick.region(quick)).?);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());

    // Shown again before it is gone: in from there, and whole at the end.
    try TestQuick.begin(&app);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expectEqual(TestQuick.band(.top, width, height, back + (1 - back) * e), (try TestQuick.region(quick)).?);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.region(quick)) == null);

    // Out from whole and back in halfway, the same.
    try TestQuick.begin(&app);
    TestQuick.tick(quick, TestQuick.half);
    try TestQuick.begin(&app);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expectEqual(TestQuick.band(.top, width, height, (1 - e) + e * e), (try TestQuick.region(quick)).?);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.region(quick)) == null);
    try std.testing.expect(TestQuick.shows);
}

test "win32: a centered quick terminal fades in and out" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickFade, .{});
}

/// The test of the centered quick terminal's fade, run by its test on a
/// desktop of its own.
fn testQuickFade() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"quick-terminal-position" = .center;
    try TestQuick.reconfigure(&app, &changed);

    // In by its alpha as a layered window, from none of it, with no
    // region: it has no edge to come from.
    try TestQuick.begin(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(0, (try TestQuick.alpha(quick)).?);
    try std.testing.expect((try TestQuick.region(quick)) == null);
    // 255 of it eased halfway is 80.4.
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expectEqual(80, (try TestQuick.alpha(quick)).?);
    // Opaque at the end: no longer layered.
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.alpha(quick)) == null);

    // Out from all of it, 174.6 halfway; hidden at the end, and not
    // layered for the next show.
    try TestQuick.begin(&app);
    try std.testing.expectEqual(255, (try TestQuick.alpha(quick)).?);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expectEqual(175, (try TestQuick.alpha(quick)).?);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.alpha(quick)) == null);
}

test "win32: with no duration, or no way to animate, the quick terminal shows and hides at once" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickAtOnce, .{});
}

/// The test of the quick terminal with no animation, run by its test on a
/// desktop of its own.
fn testQuickAtOnce() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestQuick.start();
    defer TestQuick.stop();
    try TestQuick.beside(&app);
    var changed: Config = try .default(alloc);
    defer changed.deinit();

    // With 0, as the option says, or anything that is not a finite time
    // above 0, which its parser lets through.
    for ([_]f64{ 0, std.math.nan(f64), std.math.inf(f64), -1 }) |duration| {
        changed.@"quick-terminal-animation-duration" = duration;
        try TestQuick.reconfigure(&app, &changed);
        try TestQuick.atOnce(&app);
    }
    changed.@"quick-terminal-animation-duration" = 0.2;
    try TestQuick.reconfigure(&app, &changed);

    // With no timer to step it, or no region to start it from.
    Window.test_quick_timer_fails = true;
    try TestQuick.atOnce(&app);
    Window.test_quick_timer_fails = false;
    Window.test_quick_rgn = &TestQuick.noRgn;
    try TestQuick.atOnce(&app);

    // With no region for a step partway: whole from there as it shows,
    // and gone as it hides.
    Window.test_quick_rgn = null;
    const quick = app.quick orelse return error.TestUnexpectedResult;
    try TestQuick.begin(&app);
    Window.test_quick_rgn = &TestQuick.noRgn;
    TestQuick.tick(quick, TestQuick.half);
    Window.test_quick_rgn = null;
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.region(quick)) == null);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect((try TestQuick.region(quick)) == null);
    try TestQuick.begin(&app);
    Window.test_quick_rgn = &TestQuick.noRgn;
    TestQuick.tick(quick, TestQuick.half);
    Window.test_quick_rgn = null;
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.region(quick)) == null);
}

test "win32: the quick terminal on its way out is hidden no further, and owns no prompt" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickOnItsWayOut, .{});
}

/// The test of the quick terminal as it hides, run by its test on a
/// desktop of its own.
fn testQuickOnItsWayOut() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    core_app.focused_surface = null;
    TestQuick.start();
    defer TestQuick.stop();
    const other = try TestQuick.foreign();
    defer _ = win32.DestroyWindow(other);
    var changed: Config = try .default(alloc);
    defer changed.deinit();
    changed.@"quick-terminal-autohide" = true;
    try TestQuick.reconfigure(&app, &changed);

    // Made before another window, so the first of them.
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    const a = try testFrame(&app);
    try std.testing.expectEqualSlices(*Window, &.{ quick, a }, app.windows.items);

    // A prompt with no window of its own is its while it shows, and the
    // other window's once it is on its way out, which would take the
    // activation back from the box out of sight.
    try std.testing.expectEqual(quick.hwnd, app.promptOwner(null).?);
    try TestQuick.begin(&app);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(a.hwnd, app.promptOwner(null).?);

    // Its activation lost then, it has nothing more to hide: nothing is
    // posted.
    TestQuick.deactivate(quick, other);
    try std.testing.expect(!TestQuick.posted(quick));
    TestQuick.settle(quick);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());

    // An autohide posted while it showed, that comes once a toggle has
    // started to hide it, leaves that hide to end in its time.
    try TestQuick.toggle(&app);
    TestQuick.deactivate(quick, other);
    try TestQuick.begin(&app);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(TestQuick.posted(quick));
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
}

test "win32: the quick terminal's animation eases in as macOS's does" {
    // CSS's ease-in, cubic-bezier(0.42, 0, 1, 1), solved apart from it, by
    // halving in Python to double precision.
    try std.testing.expectEqual(0, Window.easeIn(0));
    try std.testing.expectEqual(1, Window.easeIn(1));
    try std.testing.expectApproxEqAbs(0.09346465071882484, Window.easeIn(0.25), 1e-12);
    try std.testing.expectApproxEqAbs(0.31535681257253945, Window.easeIn(0.5), 1e-12);
    try std.testing.expectApproxEqAbs(0.62186186917489, Window.easeIn(0.75), 1e-12);
    // Rising all the way, and held at its ends outside them and for NaN.
    var last: f64 = 0;
    for (1..101) |i| {
        const y = Window.easeIn(@as(f64, @floatFromInt(i)) / 100);
        try std.testing.expect(y > last);
        last = y;
    }
    try std.testing.expectEqual(0, Window.easeIn(-0.5));
    try std.testing.expectEqual(0, Window.easeIn(std.math.nan(f64)));
    try std.testing.expectEqual(1, Window.easeIn(2));
}

test "win32: a toast's click and the palette's jump show a hidden quick terminal, and turn back one on its way out" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickPresent, .{});
}

/// The test of a quick terminal brought forward, run by its test on a
/// desktop of its own.
fn testQuickPresent() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    core_app.focused_surface = null;
    TestQuick.start();
    defer TestQuick.stop();
    Window.test_set_focus = &FocusSeen.seen;
    defer Window.test_set_focus = null;
    Window.test_get_focus = &FocusSeen.current;
    defer Window.test_get_focus = null;
    FocusSeen.last = null;
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    const other = try TestQuick.foreign();
    defer _ = win32.DestroyWindow(other);
    // A normal window beside it, with a terminal whose command palette
    // jumps to the quick terminal's.
    const a = try testFrame(&app);
    testResize(a, 1000, 700);
    const b = try testPane(&app, a);
    a.tab().tree = try .init(alloc, b);
    a.tab().focused = b;
    a.relayout();
    // A toast's click, as Windows reports it (`App.notificationClicked`).
    const click = struct {
        fn f(on: *App, group: u64) void {
            const m = toast.groupMessage(group);
            _ = App.wndProc(on.msg_hwnd, WM_GHOSTTY_NOTIFICATION, m[0], m[1]);
        }
    }.f;

    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    const pane = quick.tab().focused orelse return error.TestUnexpectedResult;
    pane.title = try alloc.dupeSentinel(u8, "quick", 0);
    try TestQuick.toggle(&app);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());

    // Hidden, a click on a toast of one of its terminals shows it
    // (`Window.present`): at its place by its animation, its terminal told
    // and given the focus, and brought forward, the window it came over
    // remembered as a toggle remembers it.
    TestQuick.in_front = other;
    TestQuick.front = null;
    click(&app, pane.notifications.id);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(std.mem.zeroes(win32.RECT), (try TestQuick.region(quick)).?);
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);
    try std.testing.expect(TestQuick.shows);
    try std.testing.expect(FocusSeen.last == pane.hwnd);
    TestQuick.settle(quick);
    try std.testing.expectEqual(try TestQuick.place(&app, quick), try windowRect(quick.hwnd));
    try std.testing.expect((try TestQuick.region(quick)) == null);
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expectEqual(other, TestQuick.front.?);

    // Hidden, the command palette's jump to one of its terminals, from
    // another window's, shows it the same way.
    TestQuick.in_front = other;
    TestQuick.front = null;
    FocusSeen.last = null;
    try togglePalette(&app, b);
    paletteQuery(a, L("focus: quick"));
    try std.testing.expectEqual(1, paletteRows(a));
    try std.testing.expect(paletteEntry(a, 0).run.jump == pane);
    paletteKey(a, win32.VK_RETURN);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expectEqual(std.mem.zeroes(win32.RECT), (try TestQuick.region(quick)).?);
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);
    try std.testing.expect(FocusSeen.last == pane.hwnd);
    TestQuick.settle(quick);
    try std.testing.expect((try TestQuick.region(quick)) == null);
    try TestQuick.hideInFront(&app, quick);
    try std.testing.expectEqual(other, TestQuick.front.?);

    // Shown, it is only brought forward.
    TestQuick.in_front = other;
    try TestQuick.toggle(&app);
    TestQuick.front = null;
    click(&app, pane.notifications.id);
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);
    try std.testing.expect((try TestQuick.region(quick)) == null);

    // On its way out, it turns back from where it is.
    try TestQuick.begin(&app);
    TestQuick.tick(quick, TestQuick.half);
    TestQuick.front = null;
    click(&app, pane.notifications.id);
    try std.testing.expectEqual(quick.hwnd, TestQuick.front.?);
    TestQuick.tick(quick, TestQuick.half);
    const place = try windowRect(quick.hwnd);
    const e = TestQuick.eased;
    try std.testing.expectEqual(
        TestQuick.band(.top, place.right - place.left, place.bottom - place.top, (1 - e) + e * e),
        (try TestQuick.region(quick)).?,
    );
    TestQuick.settle(quick);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    try std.testing.expect((try TestQuick.region(quick)) == null);
}

test "win32: a hidden quick terminal shows before it asks whether to close, and owns no other question" {
    // On a desktop of its own, as the toggle's test (testOnOwnDesktop).
    try testOnOwnDesktop(testQuickCloseAsks, .{});
}

/// The test of a hidden quick terminal's questions, run by its test on a
/// desktop of its own.
fn testQuickCloseAsks() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    core_app.focused_surface = null;
    TestQuick.start();
    defer TestQuick.stop();
    const a = try testFrame(&app);
    const message_box = &@import("dialog.zig").test_message_box;
    message_box.* = &TestQuick.ask;
    defer message_box.* = null;
    defer Window.test_needs_confirm = false;

    try TestQuick.toggle(&app);
    const quick = app.quick orelse return error.TestUnexpectedResult;
    const pane = quick.tab().focused orelse return error.TestUnexpectedResult;
    try TestQuick.toggle(&app);

    // A question a program in it asks while it is hidden, as the core
    // asks one for a clipboard write with `clipboard-write = ask`: the
    // other window's, as a question with no window of its own is, which
    // the activation comes back to as it closes; it stays hidden. The
    // same on its way out. Its own once it shows.
    const write: []const apprt.ClipboardContent = &.{.{ .mime = "text/plain", .data = "x" }};
    TestQuick.answer = win32.IDCANCEL;
    TestQuick.asked = null;
    try pane.setClipboard(.standard, write, true);
    try std.testing.expectEqual(a.hwnd, TestQuick.asked.?);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
    try TestQuick.toggle(&app);
    try TestQuick.begin(&app);
    TestQuick.tick(quick, TestQuick.half);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());
    TestQuick.asked = null;
    try pane.setClipboard(.standard, write, true);
    try std.testing.expectEqual(a.hwnd, TestQuick.asked.?);
    TestQuick.settle(quick);
    try TestQuick.toggle(&app);
    TestQuick.asked = null;
    try pane.setClipboard(.standard, write, true);
    try std.testing.expectEqual(quick.hwnd, TestQuick.asked.?);
    try TestQuick.toggle(&app);

    // Asked to close while hidden (WM_CLOSE, as another program can send
    // it) with a process running: it shows first, by its animation, and
    // the question is its own, asked while it shows; cancelled, it stays,
    // shown.
    Window.test_needs_confirm = true;
    TestQuick.asked = null;
    TestQuick.answer = win32.IDCANCEL;
    _ = win32.SendMessageW(quick.hwnd, win32.WM_CLOSE, 0, 0);
    try std.testing.expectEqual(quick.hwnd, TestQuick.asked.?);
    try std.testing.expect(TestQuick.asked_shown);
    try std.testing.expect(!quick.closing);
    TestQuick.settle(quick);
    try std.testing.expect(win32.IsWindowVisible(quick.hwnd).toBool());

    // With nothing running there is nothing to ask: it closes as it is,
    // hidden.
    try TestQuick.toggle(&app);
    Window.test_needs_confirm = false;
    TestQuick.asked = null;
    _ = win32.SendMessageW(quick.hwnd, win32.WM_CLOSE, 0, 0);
    try std.testing.expect(TestQuick.asked == null);
    try std.testing.expect(quick.closing);
    try std.testing.expect(!win32.IsWindowVisible(quick.hwnd).toBool());
}

test "win32: the quick terminal does not cover a question another window asks" {
