    try std.testing.expect(win32.IsWindowEnabled(TestExport.inspector).toBool());
    try std.testing.expect(app.canReenterCore());
}

test "win32: an export's dialog goes on ticking the core, and no prompt inside it does" {
    // The dialog can stay open while the user looks for a folder, and a
    // terminal whose output filled the app mailbox meanwhile would stop
    // until it closed, where GTK's and the macOS app's save panels stop
    // none. `run` opens it outside any core frame, so a wakeup in its
    // loop ticks the core (`beginUnframedPrompt`). A prompt that may have
    // a core frame beneath it does not: one opened inside the dialog, as
    // a tick's clipboard question would be, nor any other.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    App.test_tick = &TestExport.tick;
    defer App.test_tick = null;

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;
    const target: apprt.Target = .{ .surface = &a.core_surface };
    defer TestExport.stop(a);
    try TestExport.start(&app, a);
    TestExport.probe = true;

    // Outside a modal loop the handler does not tick: `run` does, after
    // every message. Nor under an ordinary prompt.
    try std.testing.expectEqual(0, TestExport.wakeups());
    app.beginPrompt(null);
    try std.testing.expectEqual(0, TestExport.wakeups());
    app.endPrompt();
    // Nor the wakeup its end posts, taken here so that the dialog's count
    // is of its own.
    try std.testing.expectEqual(0, TestExport.wakeups());

    try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
    app.createRequested();
    try std.testing.expectEqual(1, TestExport.asks);
    try std.testing.expectEqual(1, TestExport.ticked);
    try std.testing.expectEqual(0, TestExport.nested_ticked);
    try std.testing.expectEqual(1, TestExport.ticked_after);
    // Input still reaches no terminal while it is open.
    try std.testing.expect(!TestExport.could_reenter);

    // The next prompt is an ordinary one again.
    app.beginPrompt(null);
    try std.testing.expectEqual(0, TestExport.wakeups());
    app.endPrompt();
}

test "win32: a Save dialog asked inside a window procedure or another prompt ticks nothing" {
    // Only `run` asks, outside any core frame. Asked inside one of our
    // window procedures, as a key's, where the core's callback may be
    // beneath it, the dialog is an ordinary prompt, whose loop ticks
    // nothing (`beginUnframedPrompt`). Nor inside another prompt, which
    // is as ordinary as before once the dialog closes. No procedure asks
    // today, so the count is raised here as each procedure raises it.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    App.test_tick = &TestExport.tick;
    defer App.test_tick = null;

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;
    const target: apprt.Target = .{ .surface = &a.core_surface };
    defer TestExport.stop(a);
    try TestExport.start(&app, a);
    TestExport.probe = true;

    {
        App.handler_depth += 1;
        defer App.handler_depth -= 1;
        try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
        app.createRequested();
    }
    try std.testing.expectEqual(1, TestExport.asks);
    try std.testing.expectEqual(0, TestExport.ticked);
    try std.testing.expectEqual(0, TestExport.ticked_after);

    app.beginPrompt(null);
    try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
    app.createRequested();
    try std.testing.expectEqual(2, TestExport.asks);
    try std.testing.expectEqual(0, TestExport.ticked);
    try std.testing.expectEqual(0, TestExport.wakeups());
    app.endPrompt();
}

test "win32: an export whose terminal closes first is dropped, and freed" {
    // The request owns the events until it is carried out: a terminal
    // closing first frees them (`forgetClosing`), and so does a quit
    // before `run` gets to it (`freeRequests`). The test's allocator
    // finds any left.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;
    const target: apprt.Target = .{ .surface = &a.core_surface };
    defer TestExport.stop(a);
    try TestExport.start(&app, a);

    try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
    app.forgetClosing(&a.core_surface);
    try std.testing.expect(app.requests.items[0] == .dropped);
    app.createRequested();
    try std.testing.expectEqual(0, TestExport.asks);

    // Never carried out: freed when the app ends, here by `testCleanup`.
    try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
    app.quit = true;
    app.createRequested();
    app.quit = false;
    try std.testing.expectEqual(0, TestExport.asks);
    try std.testing.expect(app.requests.items[0] == .export_io);
}

test "win32: an export's dialog that sees the app quit is the last request carried out" {
    // The dialog can stay open while the session ends, which only marks
    // the app to quit (`endSession`): it cannot be torn down under a
    // prompt. Nothing queued behind the dialog is carried out then, not a
    // move nor another export's dialog, and what is left is freed. The
    // test's allocator finds any left. Nor does the dialog's loop tick the
    // core any more, as `run` does not.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    App.test_tick = &TestExport.tick;
    defer App.test_tick = null;

    // a | b, with the focus on a, where a move right would take it to b.
    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    const b = try testPane(&app, window);
    window.tab().tree = try testRow(alloc, &.{ a, b });
    window.tab().focused = a;
    b.core_state = .live;
    defer b.core_state = .none;
    const target: apprt.Target = .{ .surface = &a.core_surface };
    defer TestExport.stop(a);
    try TestExport.start(&app, a);
    TestExport.quits = true;
    TestExport.probe = true;

    try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
    try app.requests.append(alloc, .{ .goto = .{ .from = &a.core_surface, .to = .right } });
    try std.testing.expect(try app.performAction(target, .export_terminal_io, .{ .contents = "Seq\tKind\tDescription\n" }));
    app.createRequested();
    app.quit = false;
    try std.testing.expectEqual(1, TestExport.asks);
    try std.testing.expectEqual(0, TestExport.ticked);
    try std.testing.expect(window.tab().focused == a);
    try std.testing.expectEqual(0, app.requests.items.len);
}

test "win32: a Save dialog asked once the app quits is answered Cancel, unshown" {
    // As once the windows close for good (`terminating`): the app is on
    // its way out, and nothing it asked would be done.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    defer testCleanup(&app);
    const Never = struct {
        var asks: usize = 0;
        fn ask(_: ?win32.HWND, _: SaveDialog.Spec) SaveDialog.Answer {
            asks += 1;
            return .cancelled;
        }
    };
    SaveDialog.test_ask = &Never.ask;
    defer SaveDialog.test_ask = null;
    const spec: SaveDialog.Spec = .{ .title = L("Title"), .name = L("name.txt"), .ok = L("Save") };

    app.quit = true;
    const quitting = SaveDialog.ask(&app, null, spec);
    app.quit = false;
    try std.testing.expect(quitting == .cancelled);
    app.terminating = true;
    const terminating = SaveDialog.ask(&app, null, spec);
    app.terminating = false;
    try std.testing.expect(terminating == .cancelled);
    try std.testing.expectEqual(0, Never.asks);
    try std.testing.expectEqual(0, app.prompt_depth);
}

test "win32: the command palette has a jump to each terminal that is not closing" {
    // GTK's and macOS's "Focus: <title>" entries, one per terminal of
    // every window, titled as each is shown (its title prompt's title over
    // the program's), with the configuration's commands.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);

    const window = try testFrame(&app);
    const other = try testFrame(&app);
    const a = try testPane(&app, window);
    const b = try testPane(&app, window);
    const c = try testPane(&app, other);
    const d = try testPane(&app, other);
    window.tab().tree = try testRow(alloc, &.{ a, b });
    other.tab().tree = try testRow(alloc, &.{ c, d });
    a.title = try alloc.dupeSentinel(u8, "shell", 0);
    b.title = try alloc.dupeSentinel(u8, "vim", 0);
    b.title_override = try alloc.dupeSentinel(u8, "notes", 0);
    d.closing = true;
    defer d.closing = false;

    var entries = try CommandPalette.forApp(&app, null);
    defer entries.deinit();
    var jumps: [4]?*Surface = .{ null, null, null, null };
    var titles: [4][]const u8 = undefined;
    var n: usize = 0;
    var commands: usize = 0;
    for (entries.items) |*e| switch (e.run) {
        .jump => |s| {
            jumps[n] = s;
            titles[n] = e.title;
            n += 1;
        },
        .action => commands += 1,
    };
    try std.testing.expectEqual(3, n);
    try std.testing.expect(commands > 50);
    // Sorted by title: notes, shell, Untitled.
    try std.testing.expectEqualStrings("Focus: notes", titles[0]);
    try std.testing.expect(jumps[0] == b);
    try std.testing.expectEqualStrings("Focus: shell", titles[1]);
    try std.testing.expect(jumps[1] == a);
    try std.testing.expectEqualStrings("Focus: Untitled", titles[2]);
    try std.testing.expect(jumps[2] == c);
}

/// For tests: the binding actions command palettes performed
/// (`SearchBar.test_perform`), as the configuration writes them, each
/// followed by ";", the terminal they were performed on, and whether a
/// palette was still open in `window` when one was.
const PaletteSeen = struct {
    var buf: [512]u8 = undefined;
    var len: usize = 0;
    var window: ?*Window = null;
    var on: ?*Surface = null;
    var open_then: bool = false;
    fn seen(surface: *Surface, action: input.Binding.Action) bool {
        on = surface;
        if (window) |w| {
            if (w.palette.hwnd != null) open_then = true;
        }
        const s = std.mem.print(buf[len..], "{f};", .{action}) catch return true;
        len += s.len;
        return true;
    }
    fn take() []const u8 {
        const s = buf[0..len];
        len = 0;
        return s;
    }
    fn reset(w: ?*Window) void {
        len = 0;
        window = w;
        on = null;
        open_then = false;
    }
};

/// For tests: toggle the command palette from `surface`, as a binding
/// does, and carry it out, as `run` does.
fn togglePalette(app: *App, surface: *Surface) !void {
    try std.testing.expect(try app.performAction(.{ .surface = &surface.core_surface }, .toggle_command_palette, {}));
    app.createRequested();
}

/// For tests: put `text` in `window`'s palette's field, as typing would.
fn paletteQuery(window: *Window, text: win32.LPCWSTR) void {
    _ = win32.SetWindowTextW(window.palette.edit.?, text);
}

fn paletteRows(window: *const Window) isize {
    return win32.SendMessageW(window.palette.list.?, win32.LB_GETCOUNT, 0, 0);
}

fn paletteSelected(window: *const Window) isize {
    return win32.SendMessageW(window.palette.list.?, win32.LB_GETCURSEL, 0, 0);
}

/// For tests: the entry on `window`'s palette's `row`.
fn paletteEntry(window: *const Window, row: usize) *const CommandPalette.Entry {
    const data = win32.SendMessageW(window.palette.list.?, win32.LB_GETITEMDATA, row, 0);
    return &window.palette.entries.?.items[@intCast(data)];
}

/// For tests: the client point of `window`'s palette's list in the middle
/// of `row`.
fn paletteRowPoint(window: *const Window, row: usize) win32.LPARAM {
    const h = win32.SendMessageW(window.palette.list.?, win32.LB_GETITEMHEIGHT, 0, 0);
    const y: i32 = @intCast(@as(isize, @intCast(row)) * h + @divTrunc(h, 2));
    return testPoint(20, y);
}

fn paletteKey(window: *const Window, vk: win32.WPARAM) void {
    _ = win32.SendMessageW(window.palette.edit.?, win32.WM_KEYDOWN, vk, 0);
}

