    try TestHotkeys.apply(&app, &.{"global:ctrl+a=new_window"});
    const id = TestHotkeys.idOf(TestHotkeys.take(), TestHotkeys.ctrl_a).?;
    TestHotkeys.press(&app, id, TestHotkeys.ctrl_a);
    var windows: usize = 0;
    for (app.requests.items) |request| switch (request) {
        .window => |parent| {
