}

test "win32: a global keybind's key-up reaches no terminal's core" {
    // Windows takes the key's press for the hotkey and sends its release
    // to the window that has the keyboard focus when the key comes up
    // (checked in the VM, 2026-11-02): the terminal in front at the
    // press, or one in a window the action has opened since. These panes
    // have no core surface, so a release that reached the core would
    // reach memory that is not one.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestHotkeys.install(&app);
    defer TestHotkeys.remove(&app);

    const window = try testFrame(&app);
    const a = try testPane(&app, window);
    window.tab().tree = try .init(alloc, a);
    window.tab().focused = a;

    const ctrl_a = TestHotkeys.ctrl_a;
    const alt_f9: Hotkeys.Combo = .{ .mods = win32.MOD_ALT | win32.MOD_NOREPEAT, .vk = 0x78 };
    try TestHotkeys.apply(&app, &.{ "global:ctrl+a=new_window", "global:alt+f9=new_tab" });
    const calls = TestHotkeys.take();
    const a_id = TestHotkeys.idOf(calls, ctrl_a).?;
    const f9_id = TestHotkeys.idOf(calls, alt_f9).?;

    // Scan codes 0x1E (A) and 0x43 (F9). A release sets lParam bits 30
    // and 31, and bit 29 with Alt held.
    const a_up: win32.LPARAM = @bitCast(@as(usize, 0xC01E_0001));
    const f9_up: win32.LPARAM = @bitCast(@as(usize, 0xE043_0001));
    const b_up: win32.LPARAM = @bitCast(@as(usize, 0xC030_0001));

    // The terminal in front at the press.
    TestHotkeys.press(&app, a_id, ctrl_a);
    try std.testing.expect(app.hotkey_up.isSet('A'));
    a.core_state = .live;
    _ = win32.SendMessageW(a.hwnd, win32.WM_KEYUP, 'A', a_up);
    a.core_state = .none;
    try std.testing.expect(!app.hotkey_up.isSet('A'));

    // A terminal in a window opened since, given the release as
    // WM_SYSKEYUP, with Alt held.
    TestHotkeys.press(&app, f9_id, alt_f9);
    const opened = try testFrame(&app);
    const b = try testPane(&app, opened);
    opened.tab().tree = try .init(alloc, b);
    opened.tab().focused = b;
    b.core_state = .live;
    _ = win32.SendMessageW(b.hwnd, win32.WM_SYSKEYUP, 0x78, f9_up);
    b.core_state = .none;
    try std.testing.expect(!app.hotkey_up.isSet(0x78));

    // Another key's release leaves it; a terminal with no core yet takes
    // it as well.
    TestHotkeys.press(&app, a_id, ctrl_a);
    _ = win32.SendMessageW(a.hwnd, win32.WM_KEYUP, 'B', b_up);
    try std.testing.expect(app.hotkey_up.isSet('A'));
    _ = win32.SendMessageW(a.hwnd, win32.WM_KEYUP, 'A', a_up);
    try std.testing.expect(!app.hotkey_up.isSet('A'));

    // A press dropped in a prompt was not seen either.
    const Inside = struct {
        var app_: *App = undefined;
        var id: c_int = 0;
        fn box(_: ?win32.HWND, _: win32.LPCWSTR, _: win32.UINT) c_int {
            TestHotkeys.press(app_, id, TestHotkeys.ctrl_a);
            return win32.IDOK;
        }
    };
    Inside.app_ = &app;
    Inside.id = a_id;
    core_app.focused_surface = null;
    const message_box = &@import("dialog.zig").test_message_box;
    message_box.* = &Inside.box;
    defer message_box.* = null;
    _ = TestHotkeys.takePerformed();
    notice(&app, null, L("Notice"));
    try std.testing.expectEqual(0, TestHotkeys.takePerformed().len);
    try std.testing.expect(app.hotkey_up.isSet('A'));
    a.core_state = .live;
    _ = win32.SendMessageW(a.hwnd, win32.WM_KEYUP, 'A', a_up);
    a.core_state = .none;
    try std.testing.expect(!app.hotkey_up.isSet('A'));

    // Once the release went to another program, the key's next press in
    // a terminal reaches the core, and so does its release.
    TestHotkeys.press(&app, a_id, ctrl_a);
    try std.testing.expect(!app.hotkeyRelease(win32.WM_KEYDOWN, 'A'));
    try std.testing.expect(!app.hotkeyRelease(win32.WM_KEYUP, 'A'));
}

test "win32: the app stays open with no window while a global keybind can open one" {
    // `quit-after-last-window-closed` is false by default here. `.start`
    // comes at launch and at the last window's close; with no delay set,
    // the timer expires at once, and `run` then quits.
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    TestHotkeys.install(&app);
    defer TestHotkeys.remove(&app);

    // No global keybind opens a window: the reload with no window arms
    // the timer, and so does `.start`.
    try TestHotkeys.apply(&app, &.{"global:ctrl+b=new_tab"});
    try std.testing.expectEqual(.expired, app.quit_timer);
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.expired, app.quit_timer);

    // A reload that registers one cancels the quit, and `.start` quits
    // nothing; as with a chain.
    try TestHotkeys.apply(&app, &.{"global:ctrl+a=new_window"});
    try std.testing.expectEqual(.off, app.quit_timer);
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.off, app.quit_timer);
    try TestHotkeys.apply(&app, &.{ "global:ctrl+b=new_tab", "chain=new_window" });
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.off, app.quit_timer);

    // The quick terminal's toggle makes one when there is none.
    try TestHotkeys.apply(&app, &.{"global:ctrl+b=new_tab"});
    try std.testing.expectEqual(.expired, app.quit_timer);
    try TestHotkeys.apply(&app, &.{"global:ctrl+b=toggle_quick_terminal"});
    try std.testing.expectEqual(.off, app.quit_timer);
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.off, app.quit_timer);

    // One that takes the last away arms it.
    try TestHotkeys.apply(&app, &.{"global:ctrl+b=new_tab"});
    try std.testing.expectEqual(.expired, app.quit_timer);

    // A hotkey another program holds cannot be pressed, until it is let
    // go.
    TestHotkeys.held = TestHotkeys.ctrl_a;
    try TestHotkeys.apply(&app, &.{"global:ctrl+a=new_window"});
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.expired, app.quit_timer);
    TestHotkeys.held = null;
    try TestHotkeys.apply(&app, &.{"global:ctrl+a=new_window"});
    try std.testing.expectEqual(.off, app.quit_timer);

    // A binding that is not global registers nothing.
    try TestHotkeys.apply(&app, &.{"ctrl+a=new_window"});
    try std.testing.expectEqual(.expired, app.quit_timer);

    // The configuration says to quit.
    {
        var config: Config = try .default(alloc);
        defer config.deinit();
        try config.keybind.parseCLI(config._arena.?.allocator(), "global:ctrl+a=new_window");
        config.@"quit-after-last-window-closed" = true;
        try std.testing.expect(try app.performAction(.app, .config_change, .{ .config = &config }));
    }
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.expired, app.quit_timer);

    // With a window open, a reload leaves the timer to the core, which
    // starts it when the last window closes.
    try TestHotkeys.apply(&app, &.{"global:ctrl+a=new_window"});
    try std.testing.expectEqual(.off, app.quit_timer);
    const f = try testFrame(&app);
    const pane = try testPane(&app, f);
    f.tab().tree = try .init(alloc, pane);
    f.tab().focused = pane;
    try TestHotkeys.apply(&app, &.{});
    try std.testing.expectEqual(.off, app.quit_timer);

    // `terminate` unregisters the hotkeys first, and the last terminal's
    // teardown after it starts the timer (`CoreApp.deleteSurface`): no
    // hotkey is left to keep the app open.
    try TestHotkeys.apply(&app, &.{"global:ctrl+a=new_window"});
    app.hotkeys.deinit(alloc, app.msg_hwnd);
    try std.testing.expect(try app.performAction(.app, .quit_timer, .start));
    try std.testing.expectEqual(.expired, app.quit_timer);
}

/// For tests: a pipe base, or class, no other test's has, nor another
/// test run's.
fn testIpcBase(buf: []u8) ![:0]const u8 {
    const Counter = struct {
        var next: std.atomic.Value(u32) = .init(0);
    };
    return std.fmt.bufPrintSentinel(buf, "ghostty-app-test-{d}-{d}", .{
        std.os.windows.GetCurrentProcessId(),
        Counter.next.fetchAdd(1, .monotonic),
    }, 0);
}

/// For tests: whether a pipe of `name` can be served, that is, whether
/// no instance serves it.
fn testIpcNameFree(name: [:0]const u16, identity: *const IpcServer.Identity, hwnd: win32.HWND) !bool {
    const server = IpcServer.start(std.testing.allocator, name, identity, hwnd, WM_GHOSTTY_IPC) catch |err| switch (err) {
        error.NameTaken => return false,
        else => return err,
    };
    server.stop();
    return true;
}

test "win32: the app answers an IPC request read once it quits as quitting" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    var app: App = undefined;
    try testApp(&app, &core_app);
    defer testCleanup(&app);
    defer _ = testTakeQuit();
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));

    const identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const base = try testIpcBase(&buf);
    app.serveIpc(&identity, base);
    const name = try IpcServer.pipeName(alloc, base, &identity);
    defer alloc.free(name);
    const bytes = try ipc.encodeRequest(alloc, .new_window, 0, &.{"--title=a"});
    defer alloc.free(bytes);

    // After a quit that came while the request waited: the loop sees its
    // WM_QUIT only once the messages posted before it are handled.
    var client: IpcServer.TestClient = .{ .name = name, .request = bytes };
    try client.start();
    IpcServer.testAwaitPost(app.msg_hwnd, WM_GHOSTTY_IPC) catch |err| {
        _ = client.finish() catch {};
        return err;
    };
    try std.testing.expect(try app.performAction(.app, .quit, {}));
    try std.testing.expectEqual(0, App.wndProc(app.msg_hwnd, WM_GHOSTTY_IPC, 0, 0));
    try std.testing.expectEqual(0, app.requests.items.len);
    try std.testing.expectEqual(ipc.Status.quitting, (try client.finish()).status);
}

test "win32: an elevated app serves no IPC" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    var app: App = undefined;
    try testApp(&app, &core_app);
    defer testCleanup(&app);

    var identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const base = try testIpcBase(&buf);
    const name = try IpcServer.pipeName(alloc, base, &identity);
    defer alloc.free(name);
    const own = try IpcServer.instancePipeName(alloc, name, std.os.windows.GetCurrentProcessId());
    defer alloc.free(own);
    identity.elevated = true;
    app.serveIpc(&identity, base);
    identity.elevated = false;
    try std.testing.expect(try testIpcNameFree(name, &identity, app.msg_hwnd));
    try std.testing.expect(try testIpcNameFree(own, &identity, app.msg_hwnd));
    app.serveIpc(&identity, base);
    try std.testing.expect(!try testIpcNameFree(name, &identity, app.msg_hwnd));
    try std.testing.expect(!try testIpcNameFree(own, &identity, app.msg_hwnd));
}

test "win32: quitting stops the app's IPC, and so does the session's end" {
    const alloc = std.testing.allocator;
    const identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const base = try testIpcBase(&buf);
    const name = try IpcServer.pipeName(alloc, base, &identity);
    defer alloc.free(name);
    const own = try IpcServer.instancePipeName(alloc, name, std.os.windows.GetCurrentProcessId());
    defer alloc.free(own);
    const hwnd = win32.CreateWindowExW(0, L("STATIC"), null, 0, 0, 0, 0, 0, win32.HWND_MESSAGE, null, null, null) orelse
        return error.TestUnexpectedResult;
    defer _ = win32.DestroyWindow(hwnd);

    for ([_]bool{ false, true }) |session_end| {
        var core_app: CoreApp = undefined;
        core_app.alloc = alloc;
        var app: App = undefined;
        try testApp(&app, &core_app);
        app.quit_timer = .off;
        try registerClasses(app.hinstance);
        var terminated = false;
        defer if (!terminated) {
            testCleanup(&app);
            unregisterClasses(app.hinstance);
        };
        defer _ = testTakeQuit();

        app.serveIpc(&identity, base);
        try std.testing.expect(!try testIpcNameFree(name, &identity, hwnd));
        try std.testing.expect(!try testIpcNameFree(own, &identity, hwnd));
        if (session_end) {
            const f = try testFrame(&app);
            const a = try testPane(&app, f);
            f.tab().tree = try .init(alloc, a);
            f.tab().focused = a;
            try std.testing.expectEqual(0, Window.wndProc(f.hwnd, win32.WM_ENDSESSION, 1, 0x1));
            try std.testing.expect(try testIpcNameFree(name, &identity, hwnd));
            try std.testing.expect(try testIpcNameFree(own, &identity, hwnd));
        }
        terminated = true;
        app.terminate();
        try std.testing.expect(try testIpcNameFree(name, &identity, hwnd));
        try std.testing.expect(try testIpcNameFree(own, &identity, hwnd));
    }
}

/// For tests: the terminals IPC requests open, made as `TestQuick` makes
/// them (`Window.test_create_pane`), and what the last was to start with.
const TestIpc = struct {
    var made: usize = 0;
    var context: ?apprt.surface.NewSurfaceContext = null;
    /// Its command's program, if one was asked for.
    var command: ?[]const u8 = null;
    var command_buf: [64]u8 = undefined;

    fn start() void {
        TestQuick.start();
        Window.test_create_pane = &create;
        made = 0;
        context = null;
        command = null;
    }

    fn create(w: *Window, opts: Surface.Options) anyerror!*Surface {
        const pane = try TestQuick.create(w, opts);
        made += 1;
        context = opts.context;
        command = null;
        if (opts.overrides) |o| if (o.command) |c| {
            const program: []const u8 = switch (c) {
                .direct => |argv| argv[0],
                .shell => |line| line,
            };
            @memcpy(command_buf[0..program.len], program);
            command = command_buf[0..program.len];
        };
        return pane;
    }

    /// Send `app` a request as a client does, on the pipe of `name`, have
    /// it read (WM_GHOSTTY_IPC) and carried out (`createRequested`), and
    /// return what the client was answered. Reading it opens nothing: it
    /// is recorded, or refused, and `run` carries it out, as it does a
    /// binding's window.
    fn send(
        app: *App,
        name: [:0]const u16,
        action: ipc.Action,
        surface_id: u64,
        arguments: ?[]const [:0]const u8,
    ) !ipc.Status {
        const alloc = app.core_app.alloc;
        const bytes = try ipc.encodeRequest(alloc, action, surface_id, arguments);
        defer alloc.free(bytes);
        var client: IpcServer.TestClient = .{ .name = name, .request = bytes };
        try client.start();
        IpcServer.testAwaitPost(app.msg_hwnd, WM_GHOSTTY_IPC) catch |err| {
            _ = client.finish() catch {};
            return err;
        };
        const windows = app.windows.items.len;
        const handled = App.wndProc(app.msg_hwnd, WM_GHOSTTY_IPC, 0, 0);
        const unopened = app.windows.items.len == windows;
        app.createRequested();
        const reply = try client.finish();
        try std.testing.expectEqual(0, handled);
        try std.testing.expect(unopened);
        try std.testing.expectEqual(0, app.requests.items.len);
        return reply.status;
    }
};

test "win32: IPC requests open windows, tabs and the quick terminal as they ask, and their clients hear how it went" {
    // On a desktop of its own: its windows show, and would come in front
    // of the programs on the user's (testOnOwnDesktop).
    try testOnOwnDesktop(testIpcOpens, .{});
}

/// The test of what IPC requests open, run by its test on a desktop of
/// its own.
fn testIpcOpens() !void {
    const alloc = std.testing.allocator;
    // A new tab goes beside a terminal the core knows (`ipcTabParent`).
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    TestIpc.start();
    defer TestQuick.stop();
    // A test's terminals have no core to inherit from (`inheritedOptions`).
    app.config.@"window-inherit-working-directory" = false;
    app.config.@"tab-inherit-working-directory" = false;
    app.config.@"window-inherit-font-size" = false;
    // Nothing an IPC request does shows a box: its client is told.
    const Boxes = struct {
        var count: usize = 0;
        fn box(_: ?win32.HWND, _: win32.LPCWSTR, _: win32.UINT) c_int {
            count += 1;
            return win32.IDOK;
        }
    };
    Boxes.count = 0;
    const message_box = &@import("dialog.zig").test_message_box;
    message_box.* = &Boxes.box;
    defer message_box.* = null;

    const identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const base = try testIpcBase(&buf);
    app.serveIpc(&identity, base);
    try std.testing.expect(app.ipc != null);
    const name = try IpcServer.pipeName(alloc, base, &identity);
    defer alloc.free(name);
    var caption: [64]u16 = undefined;

    // A window, its terminal started with the command asked for and titled
    // as asked, shown and brought forward.
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .new_window, 0, &.{ "--title=hi", "-e", "cmd.exe", "/k" }));
    try std.testing.expectEqual(1, app.windows.items.len);
    const a = app.windows.items[0];
    const pa = a.tab().focused orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(1, TestIpc.made);
    try std.testing.expectEqual(.window, TestIpc.context.?);
    try std.testing.expectEqualStrings("cmd.exe", TestIpc.command.?);
    try std.testing.expectEqualSlices(u16, std.unicode.utf8ToUtf16LeStringLiteral("hi"), testCaption(a, &caption));
    try std.testing.expect(win32.IsWindowVisible(a.hwnd).toBool());
    try std.testing.expectEqual(a.hwnd, TestQuick.front.?);

    // A second window, focused, as the core has it.
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .new_window, 0, null));
    try std.testing.expectEqual(2, app.windows.items.len);
    const b = app.windows.items[1];
    const pb = b.tab().focused orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(null, TestIpc.command);
    pa.core_surface.id = 0x11;
    pb.core_surface.id = 0x22;
    try core_app.surfaces.appendSlice(alloc, &.{ pa, pb });
    core_app.focused_surface = &pb.core_surface;

    // A tab beside the terminal of the id given, in its window, made as a
    // tab, started with the command asked for and titled as asked, shown,
    // and its window brought forward.
    TestQuick.front = null;
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .new_tab, 0x11, &.{ "--title=t", "-e", "pwsh.exe" }));
    try std.testing.expectEqual(2, app.windows.items.len);
    try std.testing.expectEqual(2, a.tabs.items.len);
    try std.testing.expectEqual(1, b.tabs.items.len);
    const ta = a.tab().focused orelse return error.TestUnexpectedResult;
    try std.testing.expect(ta != pa);
    try std.testing.expectEqual(.tab, TestIpc.context.?);
    try std.testing.expectEqualStrings("pwsh.exe", TestIpc.command.?);
    try std.testing.expectEqualSlices(u16, std.unicode.utf8ToUtf16LeStringLiteral("t"), testCaption(a, &caption));
    try std.testing.expectEqual(a.hwnd, TestQuick.front.?);

    // With an id no terminal has, or none, beside the focused one.
    for ([_]u64{ 0x99, 0 }) |id| {
        try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .new_tab, id, null));
        try std.testing.expectEqual(2, app.windows.items.len);
        try std.testing.expectEqual(.tab, TestIpc.context.?);
        try std.testing.expectEqual(b.hwnd, TestQuick.front.?);
    }
    try std.testing.expectEqual(3, b.tabs.items.len);

    // In a new window when no terminal is focused, or the one asked for
    // and the focused one are closing.
    core_app.focused_surface = null;
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .new_tab, 0, null));
    try std.testing.expectEqual(3, app.windows.items.len);
    try std.testing.expectEqual(.window, TestIpc.context.?);
    core_app.focused_surface = &pb.core_surface;
    pa.closing = true;
    b.closing = true;
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .new_tab, 0x11, null));
    pa.closing = false;
    b.closing = false;
    try std.testing.expectEqual(4, app.windows.items.len);
    try std.testing.expectEqual(2, a.tabs.items.len);
    try std.testing.expectEqual(3, b.tabs.items.len);

    // A command that does not parse is refused, and nothing opens.
    const made = TestIpc.made;
    for ([_]ipc.Action{ .new_window, .new_tab }) |action| {
        try std.testing.expectEqual(.bad_arguments, try TestIpc.send(&app, name, action, 0, &.{"--command= "}));
    }
    try std.testing.expectEqual(made, TestIpc.made);
    try std.testing.expectEqual(4, app.windows.items.len);

    // A window or tab that cannot be made is told its client, and nothing
    // is left of it.
    TestQuick.fail = true;
    try std.testing.expectEqual(.failed, try TestIpc.send(&app, name, .new_window, 0, null));
    try std.testing.expectEqual(.failed, try TestIpc.send(&app, name, .new_tab, 0x22, null));
    TestQuick.fail = false;
    try std.testing.expectEqual(4, app.windows.items.len);
    try std.testing.expectEqual(3, b.tabs.items.len);

    // The quick terminal, made and shown, then hidden; one that cannot be
    // made is told its client.
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .toggle_quick_terminal, 0, null));
    const quick = app.quick orelse return error.TestUnexpectedResult;
    TestQuick.settle(quick);
    try std.testing.expect(quick.quickShown());
    try std.testing.expectEqual(.ok, try TestIpc.send(&app, name, .toggle_quick_terminal, 0, null));
    TestQuick.settle(quick);
    try std.testing.expect(!quick.quickShown());
    try std.testing.expect(win32.DestroyWindow(quick.hwnd).toBool());
    try std.testing.expect(app.quick == null);
    TestQuick.fail = true;
    try std.testing.expectEqual(.failed, try TestIpc.send(&app, name, .toggle_quick_terminal, 0, null));
    TestQuick.fail = false;
    try std.testing.expect(app.quick == null);

    try std.testing.expectEqual(0, Boxes.count);
}

test "win32: an IPC request waiting when the app quits is told so, and freed" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    var app: App = undefined;
    try testApp(&app, &core_app);
    defer testCleanup(&app);
    defer _ = testTakeQuit();
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));

    const identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const base = try testIpcBase(&buf);
    app.serveIpc(&identity, base);
    const name = try IpcServer.pipeName(alloc, base, &identity);
    defer alloc.free(name);
    const bytes = try ipc.encodeRequest(alloc, .new_window, 0, &.{"--title=a"});
    defer alloc.free(bytes);

    // Recorded, then the quit comes before `run` carries it out: nothing
    // opens, and quitting stops the server (`stopIpc`), which tells the
    // client. The testing allocator finds the request if it is not freed
    // with the requests left (`freeRequests`).
    var client: IpcServer.TestClient = .{ .name = name, .request = bytes };
    try client.start();
    IpcServer.testAwaitPost(app.msg_hwnd, WM_GHOSTTY_IPC) catch |err| {
        _ = client.finish() catch {};
        return err;
    };
    const handled = App.wndProc(app.msg_hwnd, WM_GHOSTTY_IPC, 0, 0);
    const recorded = app.requests.items.len;
    const quit = app.performAction(.app, .quit, {}) catch false;
    app.createRequested();
    app.stopIpc();
    const reply = try client.finish();
    try std.testing.expectEqual(0, handled);
    try std.testing.expectEqual(1, recorded);
    try std.testing.expect(quit);
    try std.testing.expectEqual(0, app.windows.items.len);
    try std.testing.expectEqual(ipc.Status.quitting, reply.status);
}

test "win32: the app's IPC pipe is named by its class, as GTK's bus is, else by the build's id" {
    const alloc = std.testing.allocator;
    const identity = try IpcServer.Identity.ofProcess();
    const build = try IpcServer.pipeName(alloc, toast.app_id, &identity);
    defer alloc.free(build);
    const own = try IpcServer.pipeName(alloc, "a.b", &identity);
    defer alloc.free(own);
    const long: [IpcServer.max_name_len]u8 = @splat('x');
    const Case = struct { class: ?[]const u8, name: []const u16, named: ?[]const u8 = null };
    const cases = [_]Case{
        .{ .class = "a.b", .name = own, .named = "a.b" },
        .{ .class = null, .name = build },
        // A class that cannot name a pipe is ignored.
        .{ .class = "a\\b", .name = build },
        .{ .class = "", .name = build },
        .{ .class = &long, .name = build },
    };
    for (cases) |case| {
        const named = try App.ipcName(alloc, case.class, &identity);
        defer alloc.free(named.name);
        try std.testing.expectEqualSlices(u16, case.name, named.name);
        if (case.named) |class|
            try std.testing.expectEqualStrings(class, named.class orelse return error.TestUnexpectedResult)
        else
            try std.testing.expectEqual(null, named.class);
    }
}

/// For tests: run `cli` against `app` as a CLI process would, with the app
/// reading its request (WM_GHOSTTY_IPC) and carrying it out
/// (`createRequested`), and return what it returned.
fn testCliSend(app: *App, cli: *IpcClient.TestCli) !bool {
    try cli.start();
    IpcServer.testAwaitPost(app.msg_hwnd, WM_GHOSTTY_IPC) catch |err| {
        _ = cli.finish() catch {};
        return err;
    };
    const handled = App.wndProc(app.msg_hwnd, WM_GHOSTTY_IPC, 0, 0);
    app.createRequested();
    const result = cli.finish();
    try std.testing.expectEqual(0, handled);
    return result;
}

test "win32: `ghostty +new-window` and the others reach the running instance by IPC, and end as it answers" {
    // On a desktop of its own: its windows show, and would come in front
    // of the programs on the user's (testOnOwnDesktop).
    try testOnOwnDesktop(testIpcCli, .{});
}

/// The test of the CLI's IPC against the app, run by its test on a desktop
/// of its own.
fn testIpcCli() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    defer _ = testTakeQuit();
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    TestIpc.start();
    defer TestQuick.stop();
    // A test's terminals have no core to inherit from (`inheritedOptions`).
    app.config.@"window-inherit-working-directory" = false;
    app.config.@"tab-inherit-working-directory" = false;
    app.config.@"window-inherit-font-size" = false;

    const identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const class = try testIpcBase(&buf);
    // With a real instance's limits: a first window can take longer than
    // the limit the pending request below is given.
    app.serveIpc(&identity, class);
    try std.testing.expect(app.ipc != null);

    // Done: it succeeds, and says nothing.
    {
        var arguments = [_][:0]const u8{ "--title=a", "-e", "cmd.exe" };
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_window, .arguments = &arguments };
        try std.testing.expect(try testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("", cli.said());
    }
    try std.testing.expectEqual(1, app.windows.items.len);
    try std.testing.expectEqualStrings("cmd.exe", TestIpc.command orelse return error.TestUnexpectedResult);
    const a = app.windows.items[0];
    const pa = a.tab().focused orelse return error.TestUnexpectedResult;
    pa.core_surface.id = 0x11;
    try core_app.surfaces.append(alloc, pa);

    // A tab beside the terminal of the id given.
    {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_tab, .surface_id = 0x11 };
        try std.testing.expect(try testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("", cli.said());
    }
    try std.testing.expectEqual(1, app.windows.items.len);
    try std.testing.expectEqual(2, a.tabs.items.len);

    // The quick terminal, shown, then hidden.
    for ([_]bool{ true, false }) |visible| {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .toggle_quick_terminal };
        try std.testing.expect(try testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("", cli.said());
        const quick = app.quick orelse return error.TestUnexpectedResult;
        TestQuick.settle(quick);
        try std.testing.expectEqual(visible, quick.quickShown());
    }
    try std.testing.expect(win32.DestroyWindow(app.quick.?.hwnd).toBool());

    // Refused: it fails, saying why.
    {
        var arguments = [_][:0]const u8{"--command= "};
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_window, .arguments = &arguments };
        try std.testing.expectError(error.IPCFailed, testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("+new-window failed: the command does not parse\n", cli.said());
    }
    try std.testing.expectEqual(1, app.windows.items.len);

    // Not carried out in time: it succeeds, saying the instance is busy,
    // and the tab opens once the app gets to it. Served again, so that
    // a request not answered in 300 ms is pending.
    app.stopIpc();
    IpcServer.test_limits = .{ .answer_ms = 300 };
    app.serveIpc(&identity, class);
    IpcServer.test_limits = null;
    try std.testing.expect(app.ipc != null);
    core_app.focused_surface = &pa.core_surface;
    {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_tab };
        try cli.start();
        IpcServer.testAwaitPost(app.msg_hwnd, WM_GHOSTTY_IPC) catch |err| {
            _ = cli.finish() catch {};
            return err;
        };
        try std.testing.expect(try cli.finish());
        try std.testing.expectEqualStrings("+new-tab: the running Ghostty is busy, and does it once it is free\n", cli.said());
        try std.testing.expectEqual(2, a.tabs.items.len);
        try std.testing.expectEqual(0, App.wndProc(app.msg_hwnd, WM_GHOSTTY_IPC, 0, 0));
        app.createRequested();
    }
    try std.testing.expectEqual(3, a.tabs.items.len);

    // Quitting: a new window starts a Ghostty of its own, and the quick
    // terminal fails, saying so. The core's terminals held the one of the
    // id for the tab; quitting asks each whether it needs a confirmation,
    // and a test's has no core to ask.
    core_app.surfaces.clearRetainingCapacity();
    core_app.focused_surface = null;
    try std.testing.expect(try app.performAction(.app, .quit, {}));
    IpcClient.TestSpawn.start();
    defer IpcClient.TestSpawn.stop();
    {
        var arguments = [_][:0]const u8{"--title=b"};
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_window, .arguments = &arguments };
        try std.testing.expect(try testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("", cli.said());
        try IpcClient.TestSpawn.expectStarted(class, &arguments);
    }
    {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .toggle_quick_terminal };
        try std.testing.expectError(error.IPCFailed, testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("+toggle-quick-terminal failed: the running Ghostty is quitting\n", cli.said());
    }
    try std.testing.expectEqual(1, app.windows.items.len);
}

test "win32: an instance serves IPC to its terminals by a pipe of its own, where another serves the shared one" {
    // On a desktop of its own: its window shows (testOnOwnDesktop).
    try testOnOwnDesktop(testIpcInstance, .{});
}

/// The test of an instance's own IPC pipe, run by its test on a desktop
/// of its own.
fn testIpcInstance() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    TestIpc.start();
    defer TestQuick.stop();
    app.config.@"window-inherit-working-directory" = false;
    app.config.@"window-inherit-font-size" = false;

    const identity = try IpcServer.Identity.ofProcess();
    var buf: [64]u8 = undefined;
    const class = try testIpcBase(&buf);
    const pid = std.os.windows.GetCurrentProcessId();

    // The session's first instance, which serves the shared pipe.
    const first_hwnd = win32.CreateWindowExW(0, L("STATIC"), null, 0, 0, 0, 0, 0, win32.HWND_MESSAGE, null, null, null) orelse
        return error.TestUnexpectedResult;
    defer _ = win32.DestroyWindow(first_hwnd);
    const shared = (try App.ipcName(alloc, class, &identity)).name;
    defer alloc.free(shared);
    const first = try IpcServer.start(alloc, shared, &identity, first_hwnd, WM_GHOSTTY_IPC);
    defer first.stop();

    app.serveIpc(&identity, class);
    try std.testing.expect(app.ipc == null);
    try std.testing.expect(app.ipc_instance != null);

    // Asked for in its terminal: a window of its own, answered on its pipe.
    {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_window, .instance = .{ .pid = pid } };
        try std.testing.expect(try testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("", cli.said());
    }
    try std.testing.expectEqual(1, app.windows.items.len);
    const pa = app.windows.items[0].tab().focused orelse return error.TestUnexpectedResult;
    // Its terminals name it by its process ID and its class.
    var named_buf: [80]u8 = undefined;
    const named = try std.fmt.bufPrint(&named_buf, "{d}:{s}", .{ pid, class });
    var instance_buf: IpcClient.InstanceBuf = undefined;
    const in_terminal = in_terminal: {
        var env = try pa.defaultTermioEnv();
        defer env.deinit();
        try std.testing.expectEqualStrings(named, env.get(IpcClient.instance_env) orelse return error.TestUnexpectedResult);
        break :in_terminal try IpcClient.testInstanceOf(&env, &instance_buf);
    };

    // Asked for in its terminal for no class, as a CLI run there without
    // `--class` asks: a window of its own, though its class is not the
    // build's.
    {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_window, .target = .detect, .instance = in_terminal };
        try std.testing.expect(try testCliSend(&app, &cli));
        try std.testing.expectEqualStrings("", cli.said());
    }
    try std.testing.expectEqual(2, app.windows.items.len);

    // Asked for elsewhere: the first instance's.
    {
        var cli: IpcClient.TestCli = .{ .identity = identity, .class = class, .action = .new_window };
        try cli.start();
        IpcServer.testAwaitPost(first_hwnd, WM_GHOSTTY_IPC) catch |err| {
            _ = cli.finish() catch {};
            return err;
        };
        var entries = first.take();
        defer first.free(&entries);
        try std.testing.expectEqual(1, entries.items.len);
        try std.testing.expect(first.answer(entries.items[0].ticket, .ok, ""));
        try std.testing.expect(try cli.finish());
    }
    try std.testing.expectEqual(0, App.wndProc(app.msg_hwnd, WM_GHOSTTY_IPC, 0, 0));
    try std.testing.expectEqual(0, app.requests.items.len);
    try std.testing.expectEqual(2, app.windows.items.len);

    // Serving none, its terminals name none.
    app.stopIpc();
    try std.testing.expect(app.ipc_instance == null);
    {
        var env = try pa.defaultTermioEnv();
        defer env.deinit();
        try std.testing.expectEqual(null, env.get(IpcClient.instance_env));
    }
}

test "win32: an instance whose start fails stops serving IPC before it says why" {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));

    var buf: [64]u8 = undefined;
    const class = try testIpcBase(&buf);
    app.config.class = class;
    app.startIpc();
    try std.testing.expect(app.ipc != null and app.ipc_instance != null);
    const identity = try IpcServer.Identity.ofProcess();
    const shared = (try App.ipcName(alloc, class, &identity)).name;
    defer alloc.free(shared);

    // Whether the shared pipe was still served as the notice showed, by a
    // wait that finds a pipe of the name without opening it. The failure
    // itself, the initial window's (`startUp`), is not made here: it logs
    // an error, which fails a test run.
    const Notice = struct {
        var name: [:0]const u16 = undefined;
        var boxes: usize = 0;
        var served = true;
        var said = false;

        fn box(owner: ?win32.HWND, text: win32.LPCWSTR, buttons: win32.UINT) c_int {
            boxes += 1;
            served = win32.WaitNamedPipeW(name, 1).toBool() or win32.GetLastError() != .FILE_NOT_FOUND;
            said = owner == null and buttons == win32.MB_OK and
                std.mem.startsWith(u16, std.mem.span(text), std.mem.span(L("Ghostty could not start: Direct3D 11")));
            return win32.IDOK;
        }
    };
    Notice.name = shared;
    Notice.boxes = 0;
    const message_box = &@import("dialog.zig").test_message_box;
    message_box.* = &Notice.box;
    defer message_box.* = null;

    app.failStart(error.D3D11DeviceFailed);
    try std.testing.expectEqual(1, Notice.boxes);
    try std.testing.expect(!Notice.served);
    try std.testing.expect(Notice.said);
    try std.testing.expect(app.ipc == null and app.ipc_instance == null);
}

test "win32: an instance's initial window names its own IPC pipe to its terminals" {
    // On a desktop of its own: its window shows (testOnOwnDesktop).
    try testOnOwnDesktop(testIpcInitialWindow, .{});
}

/// The test of the initial window's terminals and IPC, run by its test on
/// a desktop of its own.
fn testIpcInitialWindow() !void {
    const alloc = std.testing.allocator;
    var core_app: CoreApp = undefined;
    core_app.alloc = alloc;
    core_app.surfaces = .empty;
    defer core_app.surfaces.deinit(alloc);
    core_app.focused_surface = null;
    var app: App = undefined;
    try testApp(&app, &core_app);
    try registerClasses(app.hinstance);
    defer unregisterClasses(app.hinstance);
    defer testCleanup(&app);
    _ = win32.SetWindowLongPtrW(app.msg_hwnd, win32.GWLP_USERDATA, @bitCast(@intFromPtr(&app)));
    TestQuick.start();
    defer TestQuick.stop();
    // Each terminal's environment read as it is made, as the core reads it
    // as the terminal starts (`CoreSurface.init`).
    const Made = struct {
        var count: usize = 0;
        var buf: IpcClient.InstanceBuf = undefined;
        var named: ?IpcClient.Instance = null;

        fn create(w: *Window, opts: Surface.Options) anyerror!*Surface {
            const pane = try TestQuick.create(w, opts);
            var env = try pane.defaultTermioEnv();
            defer env.deinit();
            count += 1;
            named = try IpcClient.testInstanceOf(&env, &buf);
            return pane;
        }
    };
    Made.count = 0;
    Made.named = null;
    Window.test_create_pane = &Made.create;

    var buf: [64]u8 = undefined;
    const class = try testIpcBase(&buf);
    app.config.class = class;
    try app.startUp();
    try std.testing.expect(app.ipc_instance != null);
    try std.testing.expectEqual(1, app.windows.items.len);
    try std.testing.expectEqual(1, Made.count);
    const named = Made.named orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(std.os.windows.GetCurrentProcessId(), named.pid);
    try std.testing.expectEqualStrings(class, named.class orelse return error.TestUnexpectedResult);
}
